import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class TableCreationApp extends JFrame {

    private JButton createButton;
    private JTextField numberTextField;
    private JPanel tablePanel;

    public TableCreationApp() {
        setTitle("Table Creation App");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        createButton = new JButton("Create Tables");
        createButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int numberOfTables = Integer.parseInt(numberTextField.getText());
                createTables(numberOfTables);
            }
        });

        numberTextField = new JTextField();
        numberTextField.setPreferredSize(new Dimension(100, 30));

        JPanel inputPanel = new JPanel();
        inputPanel.add(new JLabel("Number of Tables: "));
        inputPanel.add(numberTextField);
        inputPanel.add(createButton);

        tablePanel = new JPanel();
        tablePanel.setLayout(new BoxLayout(tablePanel, BoxLayout.Y_AXIS));

        add(inputPanel, BorderLayout.NORTH);
        add(new JScrollPane(tablePanel), BorderLayout.CENTER);

        pack();
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void createTables(int numberOfTables) {
        tablePanel.removeAll();

        for (int i = 1; i <= numberOfTables; i++) {
            DefaultTableModel model = new DefaultTableModel(new String[][]{}, new String[]{"Column 1", "Column 2"});
            JTable table = new JTable(model);
            table.setFillsViewportHeight(true);

            tablePanel.add(new JScrollPane(table));
        }

        revalidate();
        repaint();
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new TableCreationApp();
            }
        });
    }
}
