                {
                    tractorBeamTimer += Time.deltaTime;

                    // Tractor beam triggered on long press
                    if (tractorBeamTimer >= tractorBeamActivationTime)
                    {
                        tractorBeam.Activate();
                    }
                }
                else if (touch.phase == TouchPhase.Ended)
                {
                    tractorBeamTimer = 0f;
                }
            }
            else
