    {
        if (other.CompareTag("Pickupable"))
        {
            target = other.transform;
            isPulling = true;
        }
    }

    private void OnTriggerExit(Collider other)
    {
        if (other.transform == target)
        {
            isPulling = false;
        }
    }
}
