3. Write JavaScript code to handle the export functionality. This code should be placed after the HTML table. Here's an example:

```javascript
<script>
function exportToExcel() {
    // Get the table element
    var table = document.getElementById("ECR");

    // Create a new workbook
    var workbook = XLSX.utils.book_new();

    // Create a new worksheet
    var worksheet = XLSX.utils.table_to_sheet(table);

    // Add the worksheet to the workbook
    XLSX.utils.book_append_sheet(workbook, worksheet, "Sheet1");

    // Convert the workbook to a binary Excel file and save it
