```cpp
// 服务器端代码
#include <iostream>
#include <cstdlib>
#include <cstring>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define MAX_BUFFER_SIZE 1024
#define SERVER_PORT 8080

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    char buffer[MAX_BUFFER_SIZE];

    // 创建服务器套接字
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        std::cout << "无法创建套接字。" << std::endl;
        return -1;
    }

    // 设置服务器地址和端口
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = htonl(INADDR_ANY);
    server_address.sin_port = htons(SERVER_PORT);

    // 绑定套接字到地址和端口
    if (bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address)) == -1) {
        std::cout << "绑定失败。" << std::endl;
        return -1;
    }

    // 开始监听连接
    if (listen(server_socket, 5) == -1) {
        std::cout << "监听失败。" << std::endl;
        return -1;
    }

    std::cout << "服务器正在监听端口 " << SERVER_PORT << std::endl;

    // 接受客户端连接请求
    socklen_t client_address_size = sizeof(client_address);
    client_socket = accept(server_socket, (struct sockaddr*)&client_address, &client_address_size);
    if (client_socket == -1) {
        std::cout << "接受连接失败。" << std::endl;
        return -1;
    }

    std::cout << "客户端已连接。" << std::endl;

    // 接收和发送数据
    while (true) {
        memset(buffer, 0, sizeof(buffer));

        // 从客户端接收数据
        if (recv(client_socket, buffer, sizeof(buffer), 0) == -1) {
            std::cout << "接收数据失败。" << std::endl;
            return -1;
        }

        std::cout << "接收到客户端的消息： " << buffer << std::endl;

        // 发送回复给客户端
        std::cout << "回复客户端： ";
        std::cin.getline(buffer, MAX_BUFFER_SIZE);
        if (send(client_socket, buffer, strlen(buffer), 0) == -1) {
            std::cout << "发送数据失败。" << std::endl;
            return -1;
        }

        if (strcmp(buffer, "exit") == 0) {
            break;
        }
    }

    // 关闭套接字
    close(client_socket);
    close(server_socket);

    std::cout << "连接已关闭。" << std::endl;

    return 0;
}
