使用CInternetSession来实现文件下载功能，代码如下：

```cpp
#include <afxinet.h>

void downloadFile(const char* serverName, const char* filePath, const char* savePath) {
    CInternetSession session;
    CHttpFile* httpFile = NULL;

    // 连接服务器
    try {
        httpFile = (CHttpFile*)session.OpenURL(serverName);
    }
    catch (CInternetException* e) {
        TCHAR errorMsg[512];
        e->GetErrorMessage(errorMsg, 512);
        printf("Failed to connect to server: %s\n", errorMsg);
        e->Delete();
        session.Close();
        return;
    }

    // 发送下载请求
    CString request;
    request.Format(_T("GET %s HTTP/1.1\r\nHost: %s\r\n\r\n"), filePath, serverName);
    httpFile->SendRequest(request);

    // 获取服务器响应状态码，200表示成功
    DWORD statusCode;
    httpFile->QueryInfoStatusCode(statusCode);
    if (statusCode != 200) {
        printf("Failed to download file. Server returned status code: %d\n", statusCode);
        httpFile->Close();
        session.Close();
        return;
    }

    // 打开本地文件用于保存下载内容
    FILE* file = fopen(savePath, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        httpFile->Close();
        session.Close();
        return;
    }

    // 读取服务器响应并保存到文件
    char buffer[1024];
    DWORD bytesRead;
    while (bytesRead = httpFile->Read(buffer, sizeof(buffer))) {
        fwrite(buffer, 1, bytesRead, file);
    }

    printf("File downloaded successfully!\n");

    fclose(file);
    httpFile->Close();
    session.Close();
}

int main() {
    const char* serverName = "www.example.com";  // 服务器名称或IP地址
    const char* filePath = "/example.txt";  // 服务器上的文件路径
    const char* savePath = "myfile.txt";  // 本地保存的文件路径

    downloadFile(serverName, filePath, savePath);

    return 0;
}
```

