```cpp
#include <iostream>
#include <map>
#include <unordered_map>
#include <type_traits>

template<typename MapType, typename KeyType>
typename std::enable_if<std::is_same<MapType, std::map<typename MapType::key_type, typename MapType::mapped_type>>::value ||
                        std::is_same<MapType, std::unordered_map<typename MapType::key_type, typename MapType::mapped_type>>::value,
                        typename MapType::mapped_type>::type
getValue(const MapType& m, const KeyType& key)
{
    return m[key];
}

int main() {
