```swift
import UIKit
import PlaygroundSupport

// Define a Bone struct representing a bone in the skeleton
struct Bone {
    let name: String
    var position: CGPoint
}

// Define an Animation struct representing an animation sequence
struct Animation {
    let name: String
    let frames: [Bone]
    let duration: TimeInterval
}

// Define the Skeleton class representing the collection of bones and their animations
class Skeleton {
    var bones: [Bone]
    var currentAnimation: Animation?

    init(bones: [Bone]) {
        self.bones = bones
    }

    func play(animation: Animation) {
        currentAnimation = animation

        // Animate each frame of the animation with a time delay based on frame duration
        for (index, frame) in animation.frames.enumerated() {
            let delay = animation.duration * TimeInterval(index) / TimeInterval(animation.frames.count)
            DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
                self.updateBonesWith(frame: frame)
            }
        }

        // After animation completion, reset back to the initial position
        DispatchQueue.main.asyncAfter(deadline: .now() + animation.duration) {
            self.updateBonesWith(frame: self.bones[0])
        }
    }

    private func updateBonesWith(frame: Bone) {
        for i in 0..<bones.count {
            bones[i].position = frame.position
        }
        redraw()
    }

    // Helper function to redraw the skeleton (e.g., render on a view)
    private func redraw() {
        // Perform the drawing or rendering logic here...
        print("Redraw: \(bones)")
    }
}

// Usage example
let boneA = Bone(name: "BoneA", position: CGPoint(x: 0, y: 0))
let boneB = Bone(name: "BoneB", position: CGPoint(x: 20, y: 0))

let animationFrames: [Bone] = [
    Bone(name: "Frame1", position: CGPoint(x: 20, y: 10)),
    Bone(name: "Frame2", position: CGPoint(x: 40, y: 20))
]

let idleAnimation = Animation(name: "Idle", frames: [boneA, boneB], duration: 2.0)
let walkAnimation = Animation(name: "Walk", frames: animationFrames, duration: 1.0)

let skeleton = Skeleton(bones: [boneA, boneB])
skeleton.play(animation: idleAnimation)

// After some time, if you want to switch to another animation like walking:
DispatchQueue.main.asyncAfter(deadline: .now() + 3.0) {
    skeleton.play(animation: walkAnimation)
}

// Keep playground running to see the output
PlaygroundPage.current.needsIndefiniteExecution = true
```

In this simplified example, we define a `Bone` struct representing a single bone in the skeleton. The `Animation` struct represents an animation sequence composed of an array of bone positions over time.

The `Skeleton` class manages a collection of bones and the current animation. The `play` method sets the current animation and animates each frame by updating bone positions over time with delays based on frame duration.

The example demonstrates how to create a simple skeleton with two bones (`BoneA` and `BoneB`) and two animations (`idleAnimation` and `walkAnimation`). We initiate the skeleton with the idle animation and switch to the walk animation after a delay. You can observe the `redraw` function to visualize the bone positions, but in a real-world implementation, you would typically render or draw the skeleton on a view or screen.

