Можно также использовать THREE.BufferGeometry и добавить треугольники с помощью метода `.addGroup()` для определения индексов вершин и методов `.addAttribute()` или `.setAttribute()` для добавления атрибутов вершин.

```javascript
let geometry = new THREE.BufferGeometry();

let vertices = new Float32Array(points.length);
let indices = [];

for (let i = 0; i < points.length - 2; i += 3) {
  let triangle = new THREE.Triangle(
    points[i],
    points[i + 1],
    points[i + 2]
  );

