  vertices[startIndex] = triangle.a.x;
  vertices[startIndex + 1] = triangle.a.y;
  vertices[startIndex + 2] = triangle.a.z;
  vertices[startIndex + 3] = triangle.b.x;
  vertices[startIndex + 4] = triangle.b.y;
  vertices[startIndex + 5] = triangle.b.z;
  vertices[startIndex + 6] = triangle.c.x;
  vertices[startIndex + 7] = triangle.c.y;
  vertices[startIndex + 8] = triangle.c.z;

  // Добавление индексов треугольника в массив индексов
  let index = i / 3;
  indices.push(index, index, index);
}

// Добавление массива вершин в геометрию
geometry.addAttribute('position', new THREE.BufferAttribute(vertices, 3));

// Добавление массива индексов в группы геометрии
