```c
#include <stdio.h>
#include <stdlib.h>

int* twoSum(int* nums, int numsSize, int target, int* returnSize) {
    // Hashmap to store the complement element and its index
    int* hashmap = (int*)malloc(numsSize * sizeof(int));

    // Iterate through the array
    for (int i = 0; i < numsSize; i++) {
        int complement = target - nums[i];

        // Check if the complement exists in the hashmap
        for (int j = 0; j < i; j++) {
            if (hashmap[j] == complement) {
                int* result = (int*)malloc(2 * sizeof(int));

                // Assign the indices of the two numbers
                result[0] = j;
                result[1] = i;

                *returnSize = 2;
                return result;
            }
        }

        // If complement not found, add the current number and its index to the hashmap
        hashmap[i] = nums[i];
    }

    *returnSize = 0; // No solution found
    return NULL;
}

int main() {
    int nums[] = {2, 7, 11, 15};
    int target = 9;
    int numsSize = sizeof(nums) / sizeof(nums[0]);

    int returnSize;
    int* result = twoSum(nums, numsSize, target, &returnSize);

    printf("Indices of the two numbers that add up to target: %d %d\n", result[0], result[1]);

    free(result);

    return 0;
}
```

