```
const transformForComboEditor = (
  product: Product,
  allProducts: Products,
  itemGroup: ItemGroup,
  category: Category,
): { params:ComboEditorCtxProps, card: ProductCardData, isValid: true }
| { isValid: false, params: null, card: null } => {
  try {
    const {
      products,
      comboGroupsById,
      optionsByComboId,
      parentComboGroupsIds,
      comboGroups,
    } = product.combo.reduce((acc, combogroup) => {
      const comboGroup = {
        id: combogroup.combogroupId,
        parentId: combogroup.parentCombogroupId,
        items: combogroup.items,
        required: combogroup.required,
        title: combogroup.title,
      };

      acc.comboGroupsById[combogroup.combogroupId] = comboGroup;
      acc.comboGroups.push(comboGroup);

      if (combogroup.parentCombogroupId === null) {
        acc.parentComboGroupsIds.push(combogroup.combogroupId);
      }

      combogroup.items.forEach((productId) => {
        if (!allProducts[productId]) {
          throw new Error(`combo without product: id-${productId}`);
        }
        acc.products[productId] = allProducts[productId];
      });

      if (combogroup.parentCombogroupId && combogroup.items.length) {
        if (acc.optionsByComboId[combogroup.parentCombogroupId]) {
          acc.optionsByComboId[combogroup.parentCombogroupId].push(combogroup.combogroupId);
        } else {
          acc.optionsByComboId[combogroup.parentCombogroupId] = [combogroup.combogroupId];
        }
      }

      return acc;
    }, {
      comboGroupsById: {},
      products: {},
      optionsByComboId: {},
      parentComboGroupsIds: [],
      comboGroups: [],
    } as {
      comboGroupsById: ComboEditorCtxProps['comboGroupsById'];
      comboGroups: ComboEditorCtxProps['comboGroups']
      products: ComboEditorCtxProps['products'];
      optionsByComboId: Record<number, Array<number>>;
      parentComboGroupsIds: Array<number>;
    });

    const stopped = itemGroup.stopped || category.stopped;

    return {
      isValid: true,
      params: {
        title: itemGroup.title,
        image: product.image,
        price: parseFloat(product.price),
        comboGroupsById,
        comboGroups,
        products,
        optionsByComboId,
        parentComboGroupsIds,
      },
      card: {
        stopped,
        single: true,
        isUnavailable: stopped || product.stopped,
        editable: itemGroup.editable,
        nutrients: product.nutrients,
        badge: product.badge,
        oldPrice: product.oldPrice,
        constructorType: product.constructorType,
        productTitle: product.title,
        id: product.id,
        price: product.price,
        image: product.image,
        weight: product.weight,
        title: itemGroup.title,
        description: itemGroup.description,
        availableAt: itemGroup.availableAt || category.availableAt,
      },
    };
  } catch (error) {
    console.error(error);
    return {
      isValid: false,
      params: null,
      card: null,
    };
  }
};
