class FileSelectionTableView : public QTableView
{
    // ...

protected:
    void mouseDoubleClickEvent(QMouseEvent *event) override
    {
        QModelIndex index = indexAt(event->pos());

        if (index.isValid() && index.column() == 0) {  // Колонка с флажком
