Для того чтобы сохраненные значения не стирались после сохранения, можно добавить код, который будет устанавливать сохраненные значения обратно в элементы ввода. Вот полный код:

```javascript
document.getElementById("saveButton").onclick = function() {
    var name = document.getElementById("name").value;
    var age = document.getElementById("age").value;
    var city = document.getElementById("city").value;
    var company = document.getElementById("company").value;
    var email = document.getElementById("email").value;
    var tel = document.getElementById("tel").value;
    var comment = document.getElementById("comment").value;

    // Сохраняем значения в локальное хранилище
    localStorage.setItem("name", name);
    localStorage.setItem("age", age);
    localStorage.setItem("city", city);
    localStorage.setItem("company", company);
    localStorage.setItem("email", email);
    localStorage.setItem("tel", tel);
    localStorage.setItem("comment", comment);

    alert("Данные успешно сохранены");
}

// При загрузке страницы устанавливаем сохраненные значения в элементы ввода
window.onload = function() {
    document.getElementById("name").value = localStorage.getItem("name");
    document.getElementById("age").value = localStorage.getItem("age");
    document.getElementById("city").value = localStorage.getItem("city");
    document.getElementById("company").value = localStorage.getItem("company");
    document.getElementById("email").value = localStorage.getItem("email");
    document.getElementById("tel").value = localStorage.getItem("tel");
    document.getElementById("comment").value = localStorage.getItem("comment");
}
```

Теперь, при каждом сохранении, значения будут сохраняться в локальное хранилище браузера и при загрузке страницы эти значения будут устанавливаться обратно в соответствующие элементы ввода.

