Here's a C++ code that solves the problem:

```cpp
#include <iostream>
#include <chrono>

int findTeacherDay(int year) {
    std::chrono::year_month_day first_of_october(year, std::chrono::October, 1);
    std::chrono::weekday weekday = std::chrono::year_month_weekday(first_of_october).weekday();

    int diff = (std::chrono::Sunday - weekday).count();
    if (diff < 0) {
        diff += 7;
    }

    return diff + 1;
}

