```

Then, define a struct representing the columns you want to retrieve from the MySQL query result. For example, let's say you have a table with columns `id` (integer) and `name` (string):

```rust
struct Record {
    id: i32,
    name: String,
}
```

Now, you can use the `query_map` function to execute the query and map the result into a `Vec<Record>`:

```rust
use mysql::*;
use mysql::prelude::*;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a MySQL connection pool
    let pool = Pool::new(
        // MySQL connection options
        mysql::Opts::from_url("mysql://user:password@localhost:3306/database")?,
    )?;

    // Get a connection from the pool
    let mut conn = pool.get_conn()?;

    // Execute the query and map the result into Vec<Record>
    let query = "SELECT id, name FROM your_table";
    let rows: Vec<Record> = conn.query_map(query, |(id, name)| {
        Record {
            id,
            name,
        }
    })?;

    // Process the records
    for record in rows {
        println!("ID: {}, Name: {}", record.id, record.name);
    }

    Ok(())
}
```

