        // Create SOAP Element
        SOAPElement soapElement = soapBody.addChildElement("SomeAction", "ns", "http://example.com/namespace");

        // Add child elements to SOAP Element
        SOAPElement childElement1 = soapElement.addChildElement("Param1");
        childElement1.setValue("Value1");

        SOAPElement childElement2 = soapElement.addChildElement("Param2");
        childElement2.setValue("Value2");

        // Print SOAP Request
        System.out.println("SOAP Request:");
        soapMessage.writeTo(System.out);
    }
}
