        derivative_pos = (error_pos - _last_error_pos) / dT_s;
        derivative_pos = _last_derivative_pos + ((dT_s / (_RC + dT_s)) * (derivative_pos - _last_derivative_pos));
        _last_error_pos = error_pos;
        _last_derivative_pos = derivative_pos;
        pid_output += KD * derivative_pos;
    }

    if (fabs(KI) > 0) {
        _integrator_pos += (error_pos * KI) * dT_s;
        if (_integrator_pos < -inte_lim)
