        derivative_vel = (error_vel - _last_error_vel) / dT_s;
        derivative_vel = _last_derivative_vel + ((dT_s / (_RC + dT_s)) * (derivative_vel - _last_derivative_vel));
        _last_error_vel = error_vel;
        _last_derivative_vel = derivative_vel;
        pid_output += KD * derivative_vel;
    }

    if (fabs(KI) > 0) {
        _integrator_vel += (error_vel * KI) * dT_s;
        if (_integrator_vel < -inte_lim)
            _integrator_vel = -inte_lim;
        else if (_integrator_vel > inte_lim)
            _integrator_vel = inte_lim;
