```cpp
// Define the pin connections for the stepper motor
#define IN1 2
#define IN2 3
#define IN3 4
#define IN4 5

// Define the speed and number of steps per revolution
int stepsPerRevolution = 200;   
int motorSpeed = 1000;           

// Define the step sequence for the stepper motor
int stepSequence[][4] = {
  {HIGH, LOW, LOW, LOW},
  {LOW, HIGH, LOW, LOW},
  {LOW, LOW, HIGH, LOW},
  {LOW, LOW, LOW, HIGH}
};

void setup() {
  // Configure the stepper motor pins as outputs
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
}

void loop() {
  // Rotate the stepper motor clockwise for one revolution
  for (int i = 0; i < stepsPerRevolution; i++) {
    stepForward();
    delay(motorSpeed);
  }
  delay(1000);  // Pause for one second

  // Rotate the stepper motor counterclockwise for one revolution
  for (int i = 0; i < stepsPerRevolution; i++) {
    stepBackward();
    delay(motorSpeed);
  }
  delay(1000);  // Pause for one second
}

// Function to perform one step forward sequence
void stepForward() {
  for (int i = 0; i < 4; i++) {
    digitalWrite(IN1, stepSequence[i][0]);
    digitalWrite(IN2, stepSequence[i][1]);
    digitalWrite(IN3, stepSequence[i][2]);
    digitalWrite(IN4, stepSequence[i][3]);
  }
}

// Function to perform one step backward sequence
void stepBackward() {
  for (int i = 3; i >= 0; i--) {
    digitalWrite(IN1, stepSequence[i][0]);
    digitalWrite(IN2, stepSequence[i][1]);
    digitalWrite(IN3, stepSequence[i][2]);
    digitalWrite(IN4, stepSequence[i][3]);
  }
}
```

