```csharp
using System;
using System.Data.SqlClient;

public class DatabaseSync
{
    private const string OnlineConnectionString = "your_online_database_connection_string";
    private const string OfflineConnectionString = "your_offline_database_connection_string";

    public void SyncDatabases()
    {
        // Step 1: Fetch data from the online database
        var onlineData = GetDataFromOnlineDatabase();

        // Step 2: Fetch data from the offline database
        var offlineData = GetDataFromOfflineDatabase();

        // Step 3: Compare and synchronize data
        SyncData(onlineData, offlineData);
    }

    private DataTable GetDataFromOnlineDatabase()
    {
        using (var connection = new SqlConnection(OnlineConnectionString))
        {
            var query = "SELECT * FROM YourTable";
            var command = new SqlCommand(query, connection);
            var adapter = new SqlDataAdapter(command);
            var dataTable = new DataTable();
            adapter.Fill(dataTable);
            return dataTable;
        }
    }

    private DataTable GetDataFromOfflineDatabase()
    {
        using (var connection = new SqlConnection(OfflineConnectionString))
        {
            var query = "SELECT * FROM YourTable";
            var command = new SqlCommand(query, connection);
            var adapter = new SqlDataAdapter(command);
            var dataTable = new DataTable();
            adapter.Fill(dataTable);
            return dataTable;
        }
    }

    private void SyncData(DataTable onlineData, DataTable offlineData)
    {
        var onlineDataRows = onlineData.Rows.Cast<DataRow>().ToList();
        var offlineDataRows = offlineData.Rows.Cast<DataRow>().ToList();

        // Step 4: Apply changes to the offline database
        foreach (var onlineRow in onlineDataRows)
        {
            var offlineRow = offlineDataRows.FirstOrDefault(r => r["Id"].Equals(onlineRow["Id"]));
            if (offlineRow != null)
            {
                // Update existing offline record
                UpdateOfflineRecord(offlineRow, onlineRow);
            }
            else
            {
                // Create new offline record
                CreateOfflineRecord(onlineRow);
            }
        }

        // Step 5: Sync new data from offline to online
        foreach (var offlineRow in offlineDataRows)
        {
            var onlineRow = onlineDataRows.FirstOrDefault(r => r["Id"].Equals(offlineRow["Id"]));
            if (onlineRow == null)
            {
                // Sync new record from offline to online
                SyncOfflineToOnline(offlineRow);
            }
        }
    }

    private void UpdateOfflineRecord(DataRow offlineRow, DataRow onlineRow)
    {
        // Update offline record with the data from the online record
        offlineRow["Column1"] = onlineRow["Column1"];
        offlineRow["Column2"] = onlineRow["Column2"];

        // Save changes to the offline database
        using (var connection = new SqlConnection(OfflineConnectionString))
        {
            var query = "UPDATE YourTable SET Column1 = @Column1, Column2 = @Column2 WHERE Id = @Id";
            var command = new SqlCommand(query, connection);
            command.Parameters.AddWithValue("@Column1", offlineRow["Column1"]);
            command.Parameters.AddWithValue("@Column2", offlineRow["Column2"]);
            command.Parameters.AddWithValue("@Id", offlineRow["Id"]);
            connection.Open();
            command.ExecuteNonQuery();
        }
    }

    private void CreateOfflineRecord(DataRow onlineRow)
    {
        // Insert a new offline record with the data from the online record
        using (var connection = new SqlConnection(OfflineConnectionString))
        {
            var query = "INSERT INTO YourTable (Column1, Column2) VALUES (@Column1, @Column2)";
            var command = new SqlCommand(query, connection);
            command.Parameters.AddWithValue("@Column1", onlineRow["Column1"]);
            command.Parameters.AddWithValue("@Column2", onlineRow["Column2"]);
            connection.Open();
            command.ExecuteNonQuery();
        }
    }

    private void SyncOfflineToOnline(DataRow offlineRow)
    {
        // Sync new record from offline to online database
        using (var connection = new SqlConnection(OnlineConnectionString))
        {
            var query = "INSERT INTO YourTable (Column1, Column2) VALUES (@Column1, @Column2)";
            var command = new SqlCommand(query, connection);
            command.Parameters.AddWithValue("@Column1", offlineRow["Column1"]);
            command.Parameters.AddWithValue("@Column2", offlineRow["Column2"]);
            connection.Open();
            command.ExecuteNonQuery();
        }
    }
}
```

Note: You need to replace `"your_online_database_connection_string"` and `"your_offline_database_connection_string"` with the actual connection strings for your online and offline databases. Additionally, modify the table name and column names (`YourTable`, `Column1`, `Column2`) as per your specific database schema.

This example assumes you have a table with `Id`, `Column1`, and `Column2` columns. Modify the code according to your database schema and specific synchronization requirements.

