Вы можете использовать событие window.onbeforeunload для сохранения данных перед выходом со страницы. Это событие срабатывает, когда пользователь пытается покинуть страницу или обновить ее. Вот обновленный код:

```javascript
// Сохранение данных при нажатии на кнопку
document.getElementById("saveButton").onclick = function() {
  var name = document.getElementById("name").value;
  var age = document.getElementById("age").value;
  var city = document.getElementById("city").value;
  var company = document.getElementById("company").value;
  var email = document.getElementById("email").value;
  var tel = document.getElementById("tel").value;
  var comment = document.getElementById("comment").value;

  if (name === "" || age === "" || city === "" || company === "" || email === "" || tel === "" || comment === "") {
    alert("Пожалуйста, заполните все поля.");
  } else {
    alert("Данные успешно сохранены");
    var savedData = {
      "ФИО": name,
      "Возраст": age,
      "Город": city,
      "Компания": company,
      "Электронная почта": email,
      "Телефон": tel,
      "Описание компетенций и опыта": comment
    };
    localStorage.setItem("savedData", JSON.stringify(savedData));
  }

  return false;
};

// Сохранение данных при выходе со страницы или обновлении
window.onbeforeunload = function() {
  var name = document.getElementById("name").value;
  var age = document.getElementById("age").value;
  var city = document.getElementById("city").value;
  var company = document.getElementById("company").value;
  var email = document.getElementById("email").value;
  var tel = document.getElementById("tel").value;
  var comment = document.getElementById("comment").value;

  if (name !== "" && age !== "" && city !== "" && company !== "" && email !== "" && tel !== "" && comment !== "") {
    var savedData = {
      "ФИО": name,
      "Возраст": age,
      "Город": city,
      "Компания": company,
      "Электронная почта": email,
      "Телефон": tel,
      "Описание компетенций и опыта": comment
    };
    localStorage.setItem("savedData", JSON.stringify(savedData));
  }
};
```

