    // Планируем удаление данных после определенного времени
    var timeRemaining = expirationTime - Date.now();
    setTimeout(function() {
      localStorage.removeItem("savedData");
      localStorage.removeItem("expirationTime");
    }, timeRemaining);
  }

  document.getElementById("myForm").onsubmit = function() {
    var name = document.getElementById("name").value;
    var age = document.getElementById("age").value;
    var city = document.getElementById("city").value;
    var company = document.getElementById("company").value;
    var email = document.getElementById("email").value;
    var tel = document.getElementById("tel").value;
    var comment = document.getElementById("comment").value;

    if (name === "" || age === "" || city === "" || company === "" || email === "" || tel === "" || comment === "") {
      alert("Пожалуйста, заполните все поля.");
    } else {
      alert("Данные успешно сохранены");
      var savedData = {
        "ФИО": name,
        "Возраст": age,
        "Город": city,
        "Компания": company,
        "Электронная почта": email,
        "Телефон": tel,
        "Описание компетенций и опыта": comment
      };
      localStorage.setItem("savedData", JSON.stringify(savedData));

      // Устанавливаем время действия данных (в данном примере - 1 минута)
      var expirationTime = Date.now() + 1 * 60 * 1000; // 1 минута
      localStorage.setItem("expirationTime", expirationTime);

      // Планируем удаление данных после определенного времени
      setTimeout(function() {
        localStorage.removeItem("savedData");
        localStorage.removeItem("expirationTime");
      }, 1 * 60 * 1000); // 1 минута
    }
    return false;
  };
};
```

В этом обновленном коде, после сохранения данных в `localStorage`, устанавливается время истечения действия данных в `localStorage` с помощью метки времени `expirationTime`. Затем используется функция `setTimeout`, чтобы установить план удаления данных через указанное время. Также добавлены проверки, чтобы убедиться, что сохраненные данные все еще действительны, основываясь на истечении времени.

