```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;

public class CreateTableExample {
    public static void main(String[] args) {
        try {
            // Connect to the in-memory H2 database
            Connection conn = DriverManager.getConnection("jdbc:h2:mem:test;DB_CLOSE_DELAY=-1");

            // Create a table
            Statement statement = conn.createStatement();
            String createTableQuery = "CREATE TABLE employees ("
                    + "id INT PRIMARY KEY AUTO_INCREMENT,"
                    + "name VARCHAR(100) NOT NULL,"
                    + "age INT,"
                    + "salary DECIMAL(10,2)"
                    + ")";
            statement.executeUpdate(createTableQuery);
            System.out.println("Table created successfully.");

            // Close resources
            statement.close();
            conn.close();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

This example demonstrates the creation of a table named `employees` with columns `id` (an auto-increment primary key), `name` (a non-null VARCHAR), `age`, and `salary`. The table is created using the `CREATE TABLE` SQL statement.

