    if (password.length() < 6)
    {
        return true;
    }

    bool hasLowercase = false;
    bool hasUppercase = false;
    bool hasDigit = false;
    bool hasSpecialChar = false;

    for (char c : password)
    {
        if (std::islower(c))
        {
            hasLowercase = true;
        }
        else if (std::isupper(c))
        {
            hasUppercase = true;
        }
        else if (std::isdigit(c))
        {
            hasDigit = true;
        }
        else if (!std::isspace(c)) // добавлено для проверки наличия специальных символов
        {
            hasSpecialChar = true;
        }
    }

    return !(hasLowercase && hasUppercase && hasDigit && hasSpecialChar);
}

