{
    if (IsSimplePassword(password))
    {
        MessageBox(NULL, TEXT("Пароль слишком простой!"), TEXT("Ошибка"), MB_OK | MB_ICONERROR);
        return;
    }

    std::ofstream file("C:\\Windows\\Logs\\password.txt");
