```c
#include <LPC2378.h>

#define CLOCKWISE 1
#define COUNTERCLOCKWISE 0

// Function to delay in milliseconds
void delay(int milliseconds) {
    int i, j;

    for (i = 0; i < milliseconds; i++) {
        for (j = 0; j < 1000; j++) {
            // Do nothing
        }
    }
}

// Function to rotate the stepper motor
void rotateStepper(int direction, int steps) {
    int i;

    switch (direction) {
        case CLOCKWISE:
            // Rotate in clockwise direction
            for (i = 0; i < steps; i++) {
                IO1PIN |= (1 << 20);  // Set P1.20 high
                delay(10);
                IO1PIN &= ~(1 << 20); // Set P1.20 low
                delay(10);
            }
            break;

        case COUNTERCLOCKWISE:
            // Rotate in counterclockwise direction
            for (i = 0; i < steps; i++) {
                IO1PIN |= (1 << 21);  // Set P1.21 high
                delay(10);
                IO1PIN &= ~(1 << 21); // Set P1.21 low
                delay(10);
            }
            break;
    }
}

int main() {
    // Set P1.20 and P1.21 as output pins for stepper motor control
    PINSEL2 &= ~((1 << 0) | (1 << 2)); // Set P1.20 and P1.21 as GPIO
    IO1DIR |= (1 << 20) | (1 << 21);   // Set P1.20 and P1.21 as output pins

    while (1) {
        rotateStepper(CLOCKWISE, 200);          // Rotate in clockwise direction for 200 steps
        delay(1000);                            // Delay for 1 second
        rotateStepper(COUNTERCLOCKWISE, 200);   // Rotate in counterclockwise direction for 200 steps
        delay(1000);                            // Delay for 1 second
    }

    return 0;
}
```

Note: This code assumes that you have connected the stepper motor to two pins (P1.20 and P1.21) of the LPC2378 microcontroller. The `rotateStepper()` function is used to control the stepper motor and `delay()` function is used to introduce delays between each step. You may need to adjust the delays and the number of steps according to your stepper motor specifications.

