#property indicator_buffers 5
#property indicator_plots   1
#property indicator_type1   DRAW_LINE
#property indicator_color1  Blue

// Indicator parameter
input int    period=20;               // Period for calculating pitchfork

// Indicator buffers
double        Buffer_MedianLine[];
double        Buffer_UpperLine[];
double        Buffer_LowerLine[];
double        Buffer_Price[];

// Pitchfork object
int           pitchforkHandle;

//+------------------------------------------------------------------+
//| Custom indicator initialization function                         |
//+------------------------------------------------------------------+
int OnInit()
{
   // Set indicator buffers
   SetIndexBuffer(0, Buffer_MedianLine);
   SetIndexBuffer(1, Buffer_UpperLine);
   SetIndexBuffer(2, Buffer_LowerLine);
   SetIndexBuffer(3, Buffer_Price);

   // Set indicator label
   PlotIndexSetString(0, PLOT_LABEL, "Andrew's Pitchfork");

   return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Custom indicator iteration function                              |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
   // Calculate indicator starting point
   int start = prev_calculated - 1;
   if (start < 0)
      start = period;

   // Calculate pitchfork parameters
   double sumX=0, sumXX=0, sumXY=0, sumY=0;
   for(int i=start; i<rates_total; i++)
   {
      sumX += i;
      sumXX += i*i;
      sumXY += i*close[i];
      sumY += close[i];
   }

   double a = (period*sumXY - sumX*sumY) / (period*sumXX - sumX*sumX);
   double b = (sumY - a*sumX) / period;

   double numerator=0, denominator=0;
   for(int i=0; i<period; i++)
   {
      numerator += (close[i]-a*i-b)*(i-start)*(i-start);
      denominator += (i-start)*(i-start);
   }

   double c = numerator / denominator;

   // Calculate pitchfork lines
   double median = a * (rates_total-1) + b;
   double upper = c + median;
   double lower = -c + median;

   // Store pitchfork lines in buffers
   for(int i=0; i<rates_total; i++)
   {
      Buffer_MedianLine[i] = median;
      Buffer_UpperLine[i] = upper;
      Buffer_LowerLine[i] = lower;
      Buffer_Price[i] = close[i];
   }

   // Calculate days elapsed
   datetime prevTime = Time[0];
   datetime curTime;
   int daysElapsed = 0;
   for(int i=1; i<rates_total; i++)
   {
      curTime = Time[i];
      if(DayOfYear(curTime) != DayOfYear(prevTime))
         daysElapsed++;
      prevTime = curTime;
   }

   // Remove previous pitchfork object
   if(pitchforkHandle != INVALID_HANDLE)
      ObjectDelete(pitchforkHandle);

   // Calculate pitchfork coordinates
   datetime startDatetime = Time[start];
   datetime endDatetime = Time[rates_total-1];
   double x1 = TimeToStruct(startDatetime).tm_yday + TimeToStruct(startDatetime).tm_year*365 + daysElapsed;
   double y1 = Buffer_MedianLine[start];
   double x2 = TimeToStruct(endDatetime).tm_yday + TimeToStruct(endDatetime).tm_year*365 + daysElapsed;
   double y2 = Buffer_MedianLine[rates_total-1];

   datetime upperDatetime = Time[start];
   datetime lowerDatetime = Time[rates_total-1];
   double x3 = TimeToStruct(upperDatetime).tm_yday + TimeToStruct(upperDatetime).tm_year*365 + daysElapsed;
   double y3 = Buffer_UpperLine[start];
   double x4 = TimeToStruct(lowerDatetime).tm_yday + TimeToStruct(lowerDatetime).tm_year*365 + daysElapsed;
   double y4 = Buffer_LowerLine[rates_total-1];

   // Plot pitchfork on chart
   pitchforkHandle = ObjectCreate("Pitchfork", OBJ_PITCHFORK, 0, startDatetime, y1, endDatetime, y2);
   ObjectSet(pitchforkHandle, OBJPROP_FIRSTLEVEL, x3, y3);
   ObjectSet(pitchforkHandle, OBJPROP_SECONDLEVEL, x4, y4);

   return(rates_total);
}
```

The code above defines an MT5 indicator that calculates and plots the Andrew's Pitchfork on the chart. The `OnInit()` function is called during indicator initialization to set indicator buffers and label. The `OnCalculate()` function is called on each new tick or bar to calculate the pitchfork lines and plot them on the chart.

Make sure to replace `"Your Company Name"` and `"https://www.example.com"` with your own company name and website. You can also customize the indicator parameter, line colors, and other properties according to your preference.

