// Define the wait queue entry structure
typedef struct WaitQueueEntry {
    TaskHandle_t taskHandle;
    struct WaitQueueEntry* next;
} WaitQueueEntry_t;

// Define the wait queue head structure
typedef struct WaitQueueHead {
    SemaphoreHandle_t mutex;
    WaitQueueEntry_t* first;
    WaitQueueEntry_t* last;
} WaitQueueHead_t;

// Initialize wait queue head
void init_waitqueue_head(WaitQueueHead_t* wq_head) {
    wq_head->mutex = xSemaphoreCreateMutex();
    wq_head->first = NULL;
    wq_head->last = NULL;
}

// Initialize wait queue entry
void init_waitqueue_entry(struct WaitQueueEntry* wq_entry, TaskHandle_t task) {
    wq_entry->taskHandle = task;
    wq_entry->next = NULL;
}

// Add task to the wait queue
void add_wait_queue(WaitQueueHead_t* wq_head, struct WaitQueueEntry* wq_entry) {
    xSemaphoreTake(wq_head->mutex, portMAX_DELAY);

    if (wq_head->last == NULL) {
        wq_head->first = wq_entry;
        wq_head->last = wq_entry;
    } else {
        wq_head->last->next = wq_entry;
        wq_head->last = wq_entry;
    }

    xSemaphoreGive(wq_head->mutex);
}

// Wake up the first task from the wait queue
void wake_up(WaitQueueHead_t* wq_head) {
    xSemaphoreTake(wq_head->mutex, portMAX_DELAY);

    if (wq_head->first != NULL) {
        struct WaitQueueEntry* next = wq_head->first->next;
        xTaskNotifyGive(wq_head->first->taskHandle);  // Use task notification to wake up the task
        wq_head->first = next;

        if (wq_head->first == NULL) {
            wq_head->last = NULL;
        }
    }

    xSemaphoreGive(wq_head->mutex);
}

// Wake up all tasks from the wait queue
void wake_up_all(WaitQueueHead_t* wq_head) {
    xSemaphoreTake(wq_head->mutex, portMAX_DELAY);

    while (wq_head->first != NULL) {
        struct WaitQueueEntry* next = wq_head->first->next;
        xTaskNotifyGive(wq_head->first->taskHandle);  // Use task notification to wake up the task
        wq_head->first = next;
    }

    wq_head->last = NULL;

    xSemaphoreGive(wq_head->mutex);
}

