        }
        else if (isupper(password[i]))
        {
            hasUppercase = true;
        }
        else if (islower(password[i]))
        {
            hasLowercase = true;
        }
        else if (!iswspace(password[i]))
        {
            hasSpecialChar = true;
        }
    }

    // Оценка сложности пароля в зависимости от присутствия различных символов и его длины
    if (length < 6 || (!hasDigit && !hasUppercase && !hasLowercase && !hasSpecialChar))
    {
        return 1; // Очень слабый пароль
    }
    else if ((length < 10 && (hasDigit || hasLowercase || hasUppercase)) || (length < 6 && hasSpecialChar))
