        return 2; // Средний пароль
    }
    else if (length >= 10 && (hasDigit || hasLowercase || hasUppercase) && hasSpecialChar)
    {
        return 3; // Сильный пароль
    }
    else
    {
        return 4; // Очень сильный пароль
    }
}



