// Функция для добавления приложения в автозагрузку системы
void AddToAutorun()
{
    HKEY hKey;
    LPCWSTR subKey = L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run";
    LPCWSTR valueName = L"MyApp";
    LPCWSTR path = L"C:\\path\\to\\your\\application.exe";

    // Открытие ключа реестра
    if (RegOpenKeyEx(HKEY_CURRENT_USER, subKey, 0, KEY_SET_VALUE, &hKey) == ERROR_SUCCESS)
    {
        // Добавление значения в ключ реестра
        if (RegSetValueEx(hKey, valueName, 0, REG_SZ, (BYTE*)path, (wcslen(path) + 1) * sizeof(wchar_t)) != ERROR_SUCCESS)
        {
            MessageBox(NULL, L"Не удалось добавить приложение в автозагрузку", L"Ошибка", MB_OK | MB_ICONERROR);
        }

        // Закрытие ключа реестра
        RegCloseKey(hKey);
    }
    else
    {
        MessageBox(NULL, L"Не удалось открыть ключ реестра", L"Ошибка", MB_OK | MB_ICONERROR);
    }
}


