    /* Skip no questions if neither option1 nor option2 is selected */
    Qualtrics.SurveyEngine.setEmbeddedData('skipQuestionID2', false);
    Qualtrics.SurveyEngine.setEmbeddedData('skipQuestionID3', false);
  }
});
