  alignment: { vertical: 'middle', horizontal: 'center' },
};
```

5. Set the auto fit option for the height of the cell:
```javascript
cell.alignment = { shrinkToFit: true, wrapText: true };
```

6. Save the workbook with the changes:
```javascript
await workbook.xlsx.writeFile('path_to_save_file.xlsx');
