import java.util.Scanner;

public class QueueManagementSystem {
    private static FoodQueue[] queues;
    private static final int MAX_QUEUES = 3;

    public static void main(String[] args) {
        queues = new FoodQueue[MAX_QUEUES];
        initializeQueues();

        Scanner scanner = new Scanner(System.in);

        while (true) {
            displayMenu();
            String input = scanner.nextLine();

            if (input.equals("102")) {
                addCustomer(scanner);
            } else if (input.equals("103")) {
                removeCustomer(scanner);
            } else if (input.equals("110")) {
                printQueueIncome();
            } else if (input.equals("999")) {
                System.out.println("Exiting the program...");
                break;
            } else {
                System.out.println("Invalid input. Please try again.");
            }
        }
    }

    private static void initializeQueues() {
        queues[0] = new FoodQueue("Cashiers", 2);
        queues[1] = new FoodQueue("Drive-Thru", 3);
        queues[2] = new FoodQueue("Takeout", 5);
    }

    private static void displayMenu() {
        System.out.println("*****************");
        System.out.println("* Menu Options *");
        System.out.println("*****************");
        System.out.println("102 or ACQ: Add customer to a Queue");
        System.out.println("103 or RCQ: Remove a customer from a Queue (From a specific location)");
        System.out.println("110 or IFQ: Print the income of each queue");
        System.out.println("999 or EXT: Exit the Program");
        System.out.print("Enter your choice: ");
    }

    private static void addCustomer(Scanner scanner) {
        System.out.print("Enter customer's first name: ");
        String firstName = scanner.nextLine();
        System.out.print("Enter customer's last name: ");
        String lastName = scanner.nextLine();
        System.out.print("Enter number of burgers required: ");
        int burgersRequired = Integer.parseInt(scanner.nextLine());

        Customer customer = new Customer(firstName, lastName, burgersRequired);

        FoodQueue shortestQueue = getShortestQueue();
        if (shortestQueue != null) {
            shortestQueue.addCustomer(customer);
        } else {
            System.out.println("All queues are full. Customer cannot be added.");
        }
    }

    private static FoodQueue getShortestQueue() {
        FoodQueue shortestQueue = queues[0];
        for (int i = 1; i < MAX_QUEUES; i++) {
            if (queues[i].getLength() < shortestQueue.getLength()) {
                shortestQueue = queues[i];
            }
        }
        if (shortestQueue.isFull()) {
            return null; // All queues are full
        } else {
            return shortestQueue;
        }
    }

    private static void removeCustomer(Scanner scanner) {
        System.out.println("Select the queue from which customer should be removed:");
        displayQueueOptions();

        int queueIndex = Integer.parseInt(scanner.nextLine()) - 1;

        if (queueIndex >= 0 && queueIndex < MAX_QUEUES) {
            FoodQueue selectedQueue = queues[queueIndex];
            System.out.println("Select the customer index to remove:");
            selectedQueue.displayQueue();

            int customerIndex = Integer.parseInt(scanner.nextLine()) - 1;

            selectedQueue.removeCustomer(customerIndex);
        } else {
            System.out.println("Invalid queue index.");
        }
    }

    private static void displayQueueOptions() {
        for (int i = 0; i < MAX_QUEUES; i++) {
            System.out.println((i + 1) + ". " + queues[i].getName());
        }
        System.out.print("Enter your choice: ");
    }

    private static void printQueueIncome() {
        for (int i = 0; i < MAX_QUEUES; i++) {
            System.out.println(queues[i].getName() + " queue income: " + queues[i].getIncome());
        }
    }
}
