```cpp
#include <iostream>
#include <Windows.h>
#include <wingdi.h>

void CaptureWindow(HWND hWnd) {
    // Get the window's dimensions
    RECT windowRect;
    GetClientRect(hWnd, &windowRect);
    int width = windowRect.right - windowRect.left;
    int height = windowRect.bottom - windowRect.top;
    HDC hWindowDC = GetDC(hWnd);

    // Create a compatible device context (DC) for the bitmap
    HDC hMemDC = CreateCompatibleDC(hWindowDC);
    HBITMAP hBitmap = CreateCompatibleBitmap(hWindowDC, width, height);
    HBITMAP hOldBitmap = (HBITMAP)SelectObject(hMemDC, hBitmap);

    // Copy the window's image to the bitmap
    BitBlt(hMemDC, 0, 0, width, height, hWindowDC, 0, 0, SRCCOPY);

    // Save the bitmap to a file
    BITMAPINFOHEADER bi;
    bi.biSize = sizeof(BITMAPINFOHEADER);
    bi.biWidth = width;
    bi.biHeight = -height;
    bi.biPlanes = 1;
    bi.biBitCount = 24;
    bi.biCompression = BI_RGB;
    bi.biSizeImage = 0;
    bi.biXPelsPerMeter = 0;
    bi.biYPelsPerMeter = 0;
    bi.biClrUsed = 0;
    bi.biClrImportant = 0;

    BITMAPFILEHEADER bmf;
    bmf.bfType = 0x4D42;
    bmf.bfSize = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER) + width * height * 3;
    bmf.bfReserved1 = 0;
    bmf.bfReserved2 = 0;
    bmf.bfOffBits = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);

    // Open a file to write the bitmap
    HANDLE hFile = CreateFile("screenshot.bmp", GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);

    // Write the bitmap headers to the file
    DWORD dwWritten;
    WriteFile(hFile, &bmf, sizeof(BITMAPFILEHEADER), &dwWritten, NULL);
    WriteFile(hFile, &bi, sizeof(BITMAPINFOHEADER), &dwWritten, NULL);

    // Write the bitmap data to the file
    BYTE* bitmapData = new BYTE[width * height * 3];
    GetDIBits(hMemDC, hBitmap, 0, height, bitmapData, (BITMAPINFO*)&bi, DIB_RGB_COLORS);
    WriteFile(hFile, bitmapData, width * height * 3, &dwWritten, NULL);

    // Release resources
    delete[] bitmapData;
    CloseHandle(hFile);
    SelectObject(hMemDC, hOldBitmap);
    DeleteDC(hMemDC);
    ReleaseDC(hWnd, hWindowDC);
    DeleteObject(hBitmap);

    std::cout << "Window image captured and saved to screenshot.bmp" << std::endl;
}

int main() {
    // Get the handle of the window to capture
    HWND hWnd = GetDesktopWindow();

    // Capture the window's image
    CaptureWindow(hWnd);

    return 0;
}
```

In this code, the `CaptureWindow` function captures the image of a specified window. It first gets the window's dimensions by calling `GetClientRect`, and then creates a compatible device context (DC) and a bitmap using `CreateCompatibleDC` and `CreateCompatibleBitmap`. The window's image is copied to the bitmap using `BitBlt`. Then, the image data is saved to a bitmap file using `GetDIBits`, along with the necessary bitmap headers. Finally, the function cleans up the resources and saves the image to a file named "screenshot.bmp".

Note: This code captures the image of the desktop window (`GetDesktopWindow`) in this example, but you can change `hWnd` to the handle of any other window you want to capture.

