public class Main {
    private static FoodQueue[] foodQueues;
    private static int maxQueues = 3;
    private static int burgerCount = 10;
    private static FoodQueue waitingQueue = new FoodQueue(10);

    public static FoodQueue getShortestQueue(int maxQueues) {
        FoodQueue shortestQueue = foodQueues[0];
        for (int i = 1; i < maxQueues; i++) {
            if (foodQueues[i].getSize() < shortestQueue.getSize()) {
                shortestQueue = foodQueues[i];
            }
        }
        if (shortestQueue.isFull()) {
            return null; // All queues are full
        } else {
            return shortestQueue;
        }
    }

    public static void addCustomer(Scanner scanner) {
        System.out.print("Enter customer’s first name: ");
        String firstName = scanner.nextLine();
        System.out.print("Enter customer’s last name: ");
        String lastName = scanner.nextLine();
        System.out.print("Enter number of burgers required: ");
        int burgersRequired = Integer.parseInt(scanner.nextLine()); // Consume the newline character

        Customer customer = new Customer(firstName, lastName, burgersRequired);

        if (burgerCount < burgersRequired) {
            System.out.println("Can't offer that many burgers. We have " + burgerCount + " burgers remaining.");
        } else {
            FoodQueue shortestQueue = getShortestQueue(maxQueues);
            if (shortestQueue != null) {
                shortestQueue.addCustomer(customer);
                burgerCount -= burgersRequired; // Subtract the burgers from available stock
            } else {
                System.out.println("All queues are full. Customer cannot be queued. Customer will be added to the waiting list.");
                waitingQueue.addCustomer(customer);
            }
        }
    }

    public static void main(String[] args) {
        foodQueues = new FoodQueue[maxQueues];
        foodQueues[0] = new FoodQueue(2);
        foodQueues[1] = new FoodQueue(3);
        foodQueues[2] = new FoodQueue(5);

        Scanner scanner = new Scanner(System.in);

        for (int i = 0; i < maxQueues; i++) {
            System.out.print("Enter the number of customers to add to queue " + (i + 1) + ": ");
            int numCustomers = Integer.parseInt(scanner.nextLine());

            for (int j = 0; j < numCustomers; j++) {
                System.out.println("Adding customer to queue " + (i + 1));
                addCustomer(scanner);
            }
        }

        System.out.println("Waiting list:");
        waitingQueue.displayQueue();

        System.out.println("Income: " + getTotalIncome());

        scanner.close();
    }

    public static double getTotalIncome() {
        double totalIncome = 0;
        for (int i = 0; i < maxQueues; i++) {
            totalIncome += foodQueues[i].getIncome();
        }
        return totalIncome;
    }
}
