MainWindow.xaml.cs:

```csharp
using System.Windows;
using System.Windows.Input;
using System.Windows.Media.Media3D;

namespace Parallax3D
{
    public partial class MainWindow : Window
    {
        private double mouseX;
        private double mouseY;

        public MainWindow()
        {
            InitializeComponent();
        }

        private void Window_MouseMove(object sender, MouseEventArgs e)
        {
            mouseX = e.GetPosition(Canvas3D).X;
            mouseY = e.GetPosition(Canvas3D).Y;

            UpdateLayers();
        }

        private void UpdateLayers()
        {
            double centerX = Canvas3D.ActualWidth / 2;
            double centerY = Canvas3D.ActualHeight / 2;

            // Layer 1
            double layer1X = mouseX / centerX - 0.5; // Calculate parallax effect
            double layer1Y = mouseY / centerY - 0.5;
            double layer1Z = 0;

            TransformLayer(Layer1, layer1X, layer1Y, layer1Z);

            // Layer 2
            double layer2X = mouseX / centerX - 0.2; // Adjust parallax effect
            double layer2Y = mouseY / centerY - 0.2;
            double layer2Z = -100;

            TransformLayer(Layer2, layer2X, layer2Y, layer2Z);

            // Layer 3
            double layer3X = mouseX / centerX - 0.1; // Adjust parallax effect
            double layer3Y = mouseY / centerY - 0.1;
            double layer3Z = -200;

            TransformLayer(Layer3, layer3X, layer3Y, layer3Z);
        }

        private void TransformLayer(UIElement layer, double translateX, double translateY, double translateZ)
        {
            Transform3DGroup transformGroup = new Transform3DGroup();

            // Translate transform
            TranslateTransform3D translateTransform = new TranslateTransform3D(translateX, translateY, translateZ);
            transformGroup.Children.Add(translateTransform);

            // Apply the transform to the layer
            layer.Transform = transformGroup;
        }
    }
}
```

In this code, we have a `Canvas3D` that contains three `Canvas` elements named `Layer1`, `Layer2`, and `Layer3`. Each layer represents a different depth in the parallax effect. The `Window_MouseMove` event handler calculates the relative position of the mouse within the `Canvas3D` and updates the translate transforms for each layer based on the mouse position. The `TransformLayer` method creates a `TranslateTransform3D` with the specified translation values for each layer.

You can fill in the `Canvas` elements with your desired content (such as images or shapes) to create the parallax effect.

