```

3. Implement the function:
```cpp
HRESULT SaveTextureToPng(IDirect3DDevice9* device, IDirect3DTexture9* texture, const char* filename) {
    // Retrieve texture details
    D3DSURFACE_DESC desc;
    texture->GetLevelDesc(0, &desc);

    int width = desc.Width;
    int height = desc.Height;
    int pitch = width * 4; // Assuming the texture format is A8R8G8B8

    // Create a temporary memory buffer to hold the texture data
    std::vector<unsigned char> textureData(width * height * 4);

    // Lock the texture and copy the data to the buffer
    D3DLOCKED_RECT lockedRect;
    texture->LockRect(0, &lockedRect, nullptr, D3DLOCK_READONLY);
    unsigned char* sourceData = (unsigned char*)lockedRect.pBits;
    for (int y = 0; y < height; ++y) {
        memcpy(&textureData[y * pitch], &sourceData[y * lockedRect.Pitch], pitch);
    }
    texture->UnlockRect(0);

    // Save the texture data to a PNG file
    HRESULT hr = D3DXSaveTextureToFileA(filename, D3DXIFF_PNG, texture, nullptr);
    if (FAILED(hr)) {
        return hr;
    }

    return S_OK;
}
```

