#define MAX_COMMANDS 7
#define MAX_ARGS 10
#define MAX_INPUT_LENGTH 100

void execute_command(char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Error forking child process");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process

        char *args[MAX_ARGS];
        int argc = 0;

        // Tokenize the command into arguments
        char *token = strtok(command, " ");
        while (token != NULL && argc < MAX_ARGS) {
            args[argc++] = token;
            token = strtok(NULL, " ");
        }
        args[argc] = NULL;

        // Execute the command
        if (execvp(args[0], args) == -1) {
            perror("Error executing command");
            exit(EXIT_FAILURE);
        }
    } else {
        // Parent process
        if (wait(NULL) == -1) {
            perror("Error waiting for child process");
            exit(EXIT_FAILURE);
        }
    }
}

void execute_piped_commands(char *commands[], int num_commands) {
    int pipes[num_commands - 1][2];
    int command_status[MAX_COMMANDS] = {0};

    // Create pipes for each command
    for (int i = 0; i < num_commands - 1; i++) {
        if (pipe(pipes[i]) == -1) {
            perror("Error creating pipe");
            exit(EXIT_FAILURE);
        }
    }

    // Fork child processes for each command
    for (int i = 0; i < num_commands; i++) {
        pid_t pid = fork();

        if (pid == -1) {
            perror("Error forking child process");
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            // Child process

            // Redirect input/output as necessary
            if (i == 0) {
                // First command, redirect output to pipe
                if (dup2(pipes[i][1], STDOUT_FILENO) == -1) {
                    perror("Error redirecting output");
                    exit(EXIT_FAILURE);
                }
                // Close unused read end of the pipe
                close(pipes[i][0]);
            } else if (i == num_commands - 1) {
                // Last command, redirect input from pipe
                if (dup2(pipes[i - 1][0], STDIN_FILENO) == -1) {
                    perror("Error redirecting input");
                    exit(EXIT_FAILURE);
                }
                // Close unused write end of the pipe
                close(pipes[i - 1][1]);
            } else {
                // Middle commands, redirect both input and output
                if (dup2(pipes[i - 1][0], STDIN_FILENO) == -1) {
                    perror("Error redirecting input");
                    exit(EXIT_FAILURE);
                }
                if (dup2(pipes[i][1], STDOUT_FILENO) == -1) {
                    perror("Error redirecting output");
                    exit(EXIT_FAILURE);
                }
                // Close unused ends of the pipes
                close(pipes[i - 1][1]);
                close(pipes[i][0]);
            }

            // Close all pipe ends
            for (int j = 0; j < num_commands - 1; j++) {
                close(pipes[j][0]);
                close(pipes[j][1]);
            }

            // Execute the command
            execute_command(commands[i]);
            exit(EXIT_SUCCESS);
        }
    }

    // Close all pipe ends in the parent process
    for (int i = 0; i < num_commands - 1; i++) {
        close(pipes[i][0]);
        close(pipes[i][1]);
    }

    // Wait for child processes to finish and collect their exit status
    for (int i = 0; i < num_commands; i++) {
        int status;
        if (wait(&status) == -1) {
            perror("Error waiting for child process");
            exit(EXIT_FAILURE);
        }
        command_status[i] = WEXITSTATUS(status);
    }

    // Determine the overall exit status based on the logical operators
    int overall_status = (commands[num_commands - 1][0] == '&') ? 0 : 1;
    for (int i = 0; i < num_commands; i++) {
        if (commands[i][0] == '&' && command_status[i] != 0) {
            overall_status = 1;
            break;
        }
        if (commands[i][0] == '|' && command_status[i] == 0) {
            overall_status = 0;
            break;
        }
    }

    // exit(overall_status);
}

