    private int size;
    private float scale;
    private Vector3Int position;
    private ChunkData data;

    public Chunk(int size, float scale, Vector3Int position)
    {
        this.size = size;
        this.scale = scale;
        this.position = position;
        this.data = new ChunkData(size);
    }

    public void Generate()
    {
        for (int x = 0; x < size; x++)
        {
            for (int y = 0; y < size; y++)
            {
                for (int z = 0; z < size; z++)
                {
                    float noiseValue = Mathf.PerlinNoise((position.x + x) * scale, (position.z + z) * scale);
                    int height = Mathf.FloorToInt(noiseValue * size);
                    if (y <= height)
