    // Count the frequency of each character in the sentence
    for (int i = 0; i < strlen(sentence); i++) {
        charCount[(int)sentence[i]]++;
    }

    // Find the most frequent characters and their count
    int maxCount = 0;
    char mostCommonChars[256] = "";

    for (int i = 0; i < 256; i++) {
        if (charCount[i] > maxCount) {
            maxCount = charCount[i];
            mostCommonChars[0] = (char)i;
            mostCommonChars[1] = '\0';
        } else if (charCount[i] == maxCount) {
            strncat(mostCommonChars, (char*)&i, 1);
        }
    }

    printf("The number of the most frequent characters in the sentence: %d\n", maxCount);
    printf("The most frequent characters: %s\n", mostCommonChars);
}

