  "...": "...",
  "permissions": [
    "storage"
  ],
  "..."
}
```

2. In your content script or background script, import the `chrome.storage` API:

```javascript
// content.js or background.js

// Import the Chrome storage API
const storage = chrome.storage.sync; // Use chrome.storage.local for storage specific to the current machine
```

3. Save the state of the extension whenever a change occurs. For example, if you want to save a single value:

```javascript
// Save the state
function saveState(value) {
  storage.set({ state: value }, () => {
    console.log("State saved successfully!");
  });
}

// Example: Save the state whenever a checkbox is clicked
