  saveState(event.target.checked);
});
```

4. Retrieve the saved state when the extension is launched:

```javascript
// Retrieve the saved state on extension launch
function retrieveState(callback) {
  storage.get("state", (result) => {
    const savedState = result.state;
    // Do something with the retrieved state
    callback(savedState);
  });
}

// Example: Retrieve the state on extension launch and set it to a checkbox
