    message.setMessage(messageType, channel, note, velocity);
    track.add(new MidiEvent(message, tick));
    addNoteOffEvent(track, messageType, channel, note, velocity, tick + tickDuration);
}

private static void addNoteOffEvent(Track track, int messageType, int channel, int note, int velocity, int tick) throws InvalidMidiDataException {
