```java
import javax.sound.midi.*;

public class MidiQuantizationExample {

    public static void main(String[] args) {
        int[] quantizations = {16, 32, 64, 128, 256};
        int note = 72; // C5 note
        int duration = 100; // Note duration in milliseconds

        for (int quantization : quantizations) {
            try {
                Sequence sequence = new Sequence(Sequence.PPQ, quantization);
                Track track = sequence.createTrack();

                int tick = 0;
                int noteCount = quantization / 16; // Calculate the number of notes based on quantization

                for (int i = 0; i < noteCount; i++) {
                    ShortMessage noteOn = new ShortMessage();
                    noteOn.setMessage(ShortMessage.NOTE_ON, 0, note, 127);

                    ShortMessage noteOff = new ShortMessage();
                    noteOff.setMessage(ShortMessage.NOTE_OFF, 0, note, 0);

                    MidiEvent noteOnEvent = new MidiEvent(noteOn, tick);
                    MidiEvent noteOffEvent = new MidiEvent(noteOff, tick + duration);

                    track.add(noteOnEvent);
                    track.add(noteOffEvent);

                    tick += quantization / noteCount; // Update the tick position for the next note
                }

                MidiSystem.write(sequence, 1, new java.io.File("C5_Quantization_" + quantization + ".mid"));
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

