    for (int i = 0; i < N - 3; i++) {
        for (int j = 0; j < interpolationFactor; j++) {
            float t = (float)j / interpolationFactor;
            float interpolatedValue = cubicInterpolation(input[i], input[i+1], input[i+2], input[i+3], t);
            interpolated.push_back(interpolatedValue);
        }
    }

    // Print interpolated values
    std::cout << "Interpolated Values:" << std::endl;
    for (float value : interpolated) {
