Para recargar comandos slash en Discord.js, puedes utilizar el método `setCommands` del objeto `ApplicationCommandManager`. Aquí hay un ejemplo de cómo hacerlo:

```javascript
const { Client } = require('discord.js');
const client = new Client();

client.on('ready', async () => {
  console.log(`Bot listo como ${client.user.tag}`);

  const guildId = 'ID_DEL_SERVIDOR';

  const commands = [
    {
      name: 'ping',
      description: 'Muestra el ping del bot',
    },
    // Agrega más comandos aquí
    // ...
  ];

  const guild = client.guilds.cache.get(guildId);

