let arrayLineResult;

function recursiveFunction(arrayTriangle, count) {
  if (count > 0) {
    arrayTriangle2 = arrayTriangle.reduce((result, triangle) => {
      ab = [ 
        (triangle[0][0] + triangle[1][0])/2,
        (triangle[0][1] + triangle[1][1])/2,
        (triangle[0][2] + triangle[1][2])/2,
