        (triangle[0][1] + triangle[2][1])/2,
        (triangle[0][2] + triangle[2][2])/2,
      ];
      return result.concat([ [ a, ab, ac ], [ ab, b, bc ], [ ac, bc, c ] ]);
    }, []);
    arrayTriangle = arrayTriangle2;
    count = count - 1;

    recursiveFunction(arrayTriangle, count);
