Certainly! Here's an example of Qt code that demonstrates how to use UDP communication with a separate QThread:

```cpp
#include <QtWidgets>
#include <QUdpSocket>

class WorkerThread : public QThread {
    Q_OBJECT
public:
    explicit WorkerThread(QObject *parent = nullptr) : QThread(parent) {}

signals:
    void messageReceived(const QString &message);

protected:
    void run() override {
        QUdpSocket udpSocket;

        if (!udpSocket.bind(QHostAddress::LocalHost, 1234)) {
            emit messageReceived("Failed to bind the socket!");
            return;
        }

        while (!isInterruptionRequested()) {
            QByteArray datagram;
            datagram.resize(udpSocket.pendingDatagramSize());

            QHostAddress sender;
            quint16 senderPort;

            udpSocket.readDatagram(datagram.data(), datagram.size(), &sender, &senderPort);

            QString receivedMessage = QString::fromUtf8(datagram.constData());
            emit messageReceived(receivedMessage);
        }
    }
};

class MainWindow : public QMainWindow {
    Q_OBJECT
public:
    explicit MainWindow(QWidget *parent = nullptr) : QMainWindow(parent) {
        udpThread = new WorkerThread(this);
        connect(udpThread, &WorkerThread::messageReceived, this, &MainWindow::displayMessage);
        udpThread->start();

        mainWidget = new QWidget(this);
        QVBoxLayout *layout = new QVBoxLayout(mainWidget);

        label = new QLabel("No messages received yet.", this);
        layout->addWidget(label);

        setCentralWidget(mainWidget);
    }

    ~MainWindow() override {
        udpThread->requestInterruption();
        udpThread->wait();
    }

public slots:
    void displayMessage(const QString &message) {
        label->setText("Received message: " + message);
    }

private:
    WorkerThread *udpThread;
    QWidget *mainWidget;
    QLabel *label;
};

#include "main.moc"

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    MainWindow window;
    window.show();
    return app.exec();
}
```

In this example, we have a `WorkerThread` class that inherits from `QThread`. This thread handles the UDP communication and emits a signal whenever a message is received. The main UI thread (`MainWindow`) connects to this signal and updates a QLabel to display the received message.

Make sure to include the necessary Qt headers and add the relevant `.moc` include at the end to enable signal-slot communication.

Note: Don't forget to add the appropriate Qt modules to your project file (`.pro`) to ensure the required dependencies are linked properly, like `QT += core widgets network`.

