```csharp
using System;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;

public class WindowSizeConverter
{
    // Import the GetWindowRect method from User32.dll
    [DllImport("user32.dll")]
    private static extern bool GetWindowRect(IntPtr hwnd, out RECT rect);

    // Define the RECT structure to hold the window dimensions
    private struct RECT
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    public void ConvertWindowSize(Window window)
    {
        IntPtr handle = new System.Windows.Interop.WindowInteropHelper(window).Handle;
        RECT rect;
        GetWindowRect(handle, out rect);

        double width = rect.Right - rect.Left;
        double height = rect.Bottom - rect.Top;

        // Create a Grid and set its dimensions
        Grid grid = new Grid();
        grid.Width = width;
        grid.Height = height;

        // Generate the output string
        string output = $"<Grid Width=\"{width}\" Height=\"{height}\" />";
        Console.WriteLine(output); // or do whatever you need with the string
    }
}
```

