import java.util.Arrays;

class Pupil {
    private String name;
    private int[][] marks;

    public Pupil(String name, int[][] marks) {
        this.name = name;
        this.marks = marks;
    }

    public double getMark(int quarter) {
        int[] quarterMarks = marks[quarter - 1];
        double sum = 0;
        for (int mark : quarterMarks) {
            sum += mark;
        }
        return sum / quarterMarks.length;
    }

    public double getMark() {
        int totalMarks = 0;
        int totalSubjects = 0;
        for (int[] quarterMarks : marks) {
            for (int mark : quarterMarks) {
                totalMarks += mark;
                totalSubjects++;
            }
        }
        return (double) totalMarks / totalSubjects;
    }

    public String getInfo() {
        return "Name: " + name + " Marks: " + Arrays.deepToString(marks);
    }

    @Override
    public String toString() {
        return getInfo();
    }
}

public class Main {
    public static void main(String[] args) {
        // Чтение входных данных
        Scanner scanner = new Scanner(System.in);
        String name = scanner.nextLine();
        int[][] marks = new int[4][];
        for (int i = 0; i < 4; i++) {
            int[] quarterMarks = Arrays.stream(scanner.nextLine().split(" "))
                    .mapToInt(Integer::parseInt)
                    .toArray();
            marks[i] = quarterMarks;
        }
        scanner.close();

        // Создание объекта Pupil
        Pupil pupil = new Pupil(name, marks);

        // Вывод информации об ученике
        System.out.println("I: " + String.format("%.1f", pupil.getMark(1)));
        System.out.println("II: " + String.format("%.1f", pupil.getMark(2)));
        System.out.println("III: " + String.format("%.1f", pupil.getMark(3)));
        System.out.println("IV: " + String.format("%.1f", pupil.getMark(4)));
        System.out.println("Total for " + pupil.name + ": " + String.format("%.1f", pupil.getMark()));
    }
}
