    ```

2. Create two files, `sender.js` and `receiver.js`.

3. In `sender.js`, establish a connection with RabbitMQ and create a channel. Then, declare a queue for receiving responses. Here's an example implementation:

```javascript
const amqp = require('amqplib');

async function startSender() {
  try {
    const connection = await amqp.connect('amqp://localhost');
    const channel = await connection.createChannel();

    const queue = 'response_queue';
    await channel.assertQueue(queue, { durable: false });

    const message = 'Hello, RabbitMQ!';
    const correlationId = generateUuid();
    const replyTo = queue;

    channel.consume(replyTo, (msg) => {
      if (msg.properties.correlationId === correlationId) {
        console.log(`Received response: ${msg.content.toString()}`);
      }
    }, { noAck: true });

    channel.sendToQueue('request_queue', Buffer.from(message), {
      correlationId,
      replyTo,
    });

    console.log(`Sent request: ${message}`);
  } catch (error) {
    console.error('Error occurred:', error);
  }
}

function generateUuid() {
  return Math.random().toString() + Math.random().toString() + Math.random().toString();
}

startSender();
```

