    mut file_dialog_events: ResMut<Events<bevy::asset::FileEvent>>,
    mut selected_file: ResMut<SelectedFile>,
    mut query: Query<(&Interaction, &Handle<Button>)>,
) {
    for (interaction, button) in query.iter_mut() {
        if let Interaction::Clicked = *interaction {
            if let Ok(LoadState::Asset) = file_dialog_events.get_reader().latest(&button.id) {
                if let Some(file_event) = file_dialog_events
                    .iter(&button.id)
                    .find(|event| {
                        if let bevy::asset::FileEvent::Completed { path, .. } = event {
                            path.extension() == Some("glb".as_ref())
                        } else {
                            false
                        }
                    })
                {
                    if let bevy::asset::FileEvent::Completed { path, handle } = file_event {
                        selected_file.0 = path.clone().into_os_string().into_string().unwrap();
                        commands.entity(button.entity).despawn();
