                                    bottom: Val::Px(80.0),
                                    ..Default::default()
                                },
                                ..Default::default()
                            },
                            ..Default::default()
                        });
                    }
                }
            }
        }
    }
}

fn create_mesh(
    commands: &mut Commands,
    asset_server: Res<AssetServer>,
    mut meshes: ResMut<Assets<Mesh>>,
    selected_file: Res<SelectedFile>,
) {
    if !selected_file.0.is_empty() {
