const puppeteer = require('puppeteer');
const os = require('os');
const { Worker, isMainThread } = require('worker_threads');

const threadCount = os.cpus().length; // Number of threads (browsers) to run in parallel
const numRefreshes = 10; // Number of hard refreshes to perform
const refreshDelay = 2000; // Delay in milliseconds between each refresh

// Function to perform hard refreshes in a browser
async function performRefreshes(threadId) {
  const browser = await puppeteer.launch({ headless: 'new' }); // Launch new browser
  const page = await browser.newPage(); // Create a new page
  await page.goto('https://example.com'); // Open the webpage

  for (let i = 0; i < numRefreshes; i++) {
    await page.reload({ ignoreCache: true }); // Perform hard refresh
    console.log(`Thread ${threadId} - Refresh ${i+1}/${numRefreshes}`);
    await page.waitForTimeout(refreshDelay); // Delay between each refresh
  }

  await browser.close(); // Close the browser
}

async function run() {
  if (isMainThread) {
    // Spawn multiple threads to run concurrently
    for (let i = 0; i < threadCount; i++) {
      new Worker(__filename);
    }
  } else {
    // Perform hard refreshes in the current thread
    await performRefreshes(isMainThread ? 0 : 1);
  }
}

run().catch(console.error);
```

