const puppeteer = require('puppeteer');
const { Worker, isMainThread } = require('worker_threads');
const { get } = require('http');

const threadCount = 8; // Number of threads (browsers) to run in parallel
const numRefreshes = 10; // Number of hard refreshes to perform
const torProxyPort = 9050; // Tor proxy port

// Function to check if Tor proxy is available
function checkTorProxy(callback) {
  const options = {
    host: '127.0.0.1',
    port: torProxyPort,
    timeout: 2000, // Timeout in milliseconds
  };

  const req = get(options, function (res) {
    if (res.statusCode === 200) {
      callback(true);
    } else {
      callback(false);
    }
  });

  req.on('error', function () {
    callback(false);
  });

  req.end();
}

// Function to perform hard refreshes in a browser
async function performRefreshes(threadId) {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: [`--proxy-server=socks5://127.0.0.1:${torProxyPort}`],
  });

  const page = await browser.newPage(); // Create a new page
  await page.goto('https://lawnbagsigns.com/lawn-signs.php'); // Open the webpage

  for (let i = 0; i < numRefreshes; i++) {
    await page.reload({ ignoreCache: true }); // Perform hard refresh
    console.log(`Thread ${threadId} - Refresh ${i + 1}/${numRefreshes}`);
  }

  await browser.close(); // Close the browser
}

async function run() {
  if (isMainThread) {
    checkTorProxy((isProxyAvailable) => {
      // Start Tor proxy only if it's available
      if (isProxyAvailable) {
        // Spawn multiple threads to run concurrently
