IEnumerable<IEnumerable<T>> GetPermutations<T>(IEnumerable<T> list)
{
    return list.Count() == 1 
        ? new[] { list } 
        : list.SelectMany((item, index) => GetPermutations(list.Where((_, i) => i != index)).Select(permutation => new[] { item }.Concat(permutation)));
}

void Main()
{
    int someInt = 124;
    string num = someInt.ToString();

    var listOfNums = new List<int>();
    Permute(num.ToCharArray(), 0, num.Length - 1, listOfNums);
    listOfNums.Sort();

    try
    {
        Console.WriteLine(listOfNums[listOfNums.IndexOf(someInt) + 1]);
    }
    catch (Exception)
    {
        Console.WriteLine(-1);
    }
}

void Permute(char[] arr, int l, int r, List<int> listOfNums)
{
    if (l == r)
    {
        listOfNums.Add(int.Parse(new string(arr)));
    }
    else
    {
        for (int i = l; i <= r; i++)
        {
            Swap(ref arr[l], ref arr[i]);
            Permute(arr, l + 1, r, listOfNums);
            Swap(ref arr[l], ref arr[i]);
        }
    }
}

void Swap(ref char a, ref char b)
{
    char temp = a;
    a = b;
    b = temp;
}

