```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter a series of single digit numbers (separated by spaces):");
        string input = Console.ReadLine(); // Read the user's input

        string[] numbers = input.Split(' '); // Split the input by spaces and store in an array

        int sum = 0; // Initialize a variable to store the sum

        foreach (string number in numbers)
        {
            int digit;
            if (int.TryParse(number, out digit) && digit >= 0 && digit <= 9)
            {
                sum += digit; // Add each number to the sum
            }
        }

        Console.WriteLine("The sum of the numbers is: " + sum);
    }
}
```

