Конечно! Вот пример рекурсивной функции на C++, решающей данную задачу с помощью бэктрекинга:

```c++
#include <iostream>
#include <vector>
#include <algorithm>

void backtrack(std::vector<int>& nums, std::vector<bool>& used, std::vector<int>& current, std::vector<std::vector<int>>& permutations) {
    if (current.size() == nums.size()) {
        permutations.push_back(current);
        return;
    }

    for (int i = 0; i < nums.size(); i++) {
        if (!used[i] && (i == 0 || (nums[i] != nums[i-1] || used[i-1]))) {
            used[i] = true;
            current.push_back(nums[i]);
            backtrack(nums, used, current, permutations);
            current.pop_back();
            used[i] = false;
        }
    }
}

std::vector<std::vector<int>> permuteUnique(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end());
    std::vector<std::vector<int>> permutations;
    std::vector<bool> used(nums.size(), false);
    std::vector<int> current;
    backtrack(nums, used, current, permutations);
    return permutations;
}

int main() {
    std::vector<int> nums = {1, 1, 2};
    std::vector<std::vector<int>> permutations = permuteUnique(nums);

    for (const auto& perm : permutations) {
        for (const auto& num : perm) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

