        let (start_2, end_2) = parse_interval(line_2);
        let (start_3, end_3) = parse_interval(line_3);

        fill_set(&mut set_1, start_1, end_1);
        fill_set(&mut set_2, start_2, end_2);
        fill_set(&mut set_3, start_3, end_3);
    }

    let intersections = set_1.intersection(&set_2).cloned().collect::<Vec<usize>>();
    let differences = set_1.difference(&set_2).cloned().collect::<Vec<usize>>();
    let unions = set_1.union(&set_2).cloned().collect::<Vec<usize>>();

    println!("Intersections: {:?}", intersections);
    println!("Differences: {:?}", differences);
    println!("Unions: {:?}", unions);
}

