The `onValueSelected` method is not a built-in method in JavaFX's `FXHTML` class.

The `FXHTML` class is used to render HTML content within a JavaFX application. It provides methods for loading HTML content, setting the content's width and height, and retrieving the rendered content as an image, among others. However, it does not provide a direct method for handling value selection.

If you need to handle value selection within the rendered HTML content, you would typically use JavaScript code embedded within the HTML to achieve this. You can interact with the JavaScript code using the `JSObject` returned by the `FXHTML` class. For example, you can call JavaScript functions to communicate data or trigger actions when certain events occur, such as the selection of a value.

Here's an example of how you can handle value selection within `FXHTML` using JavaScript:

```java
import javafx.application.Application;
import javafx.event.EventHandler;
import javafx.scene.Scene;
import javafx.scene.input.MouseEvent;
import javafx.scene.layout.VBox;
import javafx.scene.web.WebEngine;
import javafx.scene.web.WebEvent;
import javafx.scene.web.WebView;
import javafx.stage.Stage;
import netscape.javascript.JSObject;

public class HTMLValueSelectionExample extends Application {

    @Override
    public void start(Stage primaryStage) {
        WebView webView = new WebView();
        WebEngine webEngine = webView.getEngine();

        // Load HTML content
        webEngine.loadContent("<html><body>" +
                "<select id=\"mySelect\">" +
                "<option value=\"option1\">Option 1</option>" +
                "<option value=\"option2\">Option 2</option>" +
                "<option value=\"option3\">Option 3</option>" +
                "</select>" +
                "<script>" +
                "document.getElementById('mySelect').addEventListener('change', function () {" +
                "var selectedValue = document.getElementById('mySelect').value;" +
                "valueSelected(selectedValue);" +
                "});" +
                "function valueSelected(value) {" +
                "console.log('Selected value:', value);" +
                "};" +
                "</script>" +
                "</body></html>");

        // Set up JSObject to communicate with JavaScript
        JSObject jsObject = (JSObject) webEngine.executeScript("window");
        jsObject.setMember("javaFXApp", this);

        // Event handler for value selection
        webEngine.setOnAlert(event -> {
            String selectedValue = event.getData();
            System.out.println("Selected value: " + selectedValue);
        });

        VBox root = new VBox(webView);
        Scene scene = new Scene(root, 400, 300);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public void valueSelected(String value) {
        // Handle value selection
        System.out.println("Selected value from Java: " + value);
    }

    public static void main(String[] args) {
        launch(args);
    }
