Вот пример кода на C# для модели ARIMA (Авторегрессионная интегрированная скользящая модель):

```csharp
using System;
using MathNet.Numerics.LinearAlgebra;

namespace ARIMAmodel
{
    class Program
    {
        static void Main(string[] args)
        {
            // Пример данных временного ряда
            double[] data = { 1.2, 2.8, 3.5, 2.1, 3.6, 1.5, 4.3, 2.9, 3.4, 2.0 };

            // Создание ARIMA модели с p=1, d=1 и q=1
            ARIMA model = new ARIMA(p: 1, d: 1, q: 1);

            // Обучение модели на данных временного ряда
            model.Fit(data);

            // Прогнозирование следующих 3 значений ряда
            double[] forecast = model.Forecast(steps: 3);

            Console.WriteLine("Forecasted values:");
            foreach (var value in forecast)
            {
                Console.WriteLine(value);
            }
        }
    }

    public class ARIMA
    {
        private int p; // порядок авторегрессии
        private int d; // порядок интегрирования
        private int q; // порядок скользящего среднего
        private Vector<double> data; // вектор данных временного ряда

        public ARIMA(int p, int d, int q)
        {
            this.p = p;
            this.d = d;
            this.q = q;
        }

        public void Fit(double[] inputData)
        {
            // Преобразование массива в вектор
            data = Vector<double>.Build.DenseOfArray(inputData);
        }

        public double[] Forecast(int steps)
        {
            // Создание модели ARIMA
            var model = new MathNet.Numerics.TimeSeries.Models.ARIMA(p, d, q);

            // Обучение модели на данных временного ряда
            var arimaModel = model.Learn(data);

            // Прогнозирование следующих значений ряда
            var forecast = arimaModel.Forecast(steps);

            return forecast.Values.ToArray();
        }
    }
}
```

