int on_message_callback(eXosip_event_t *ev) {
    if (ev->type == EXOSIP_MESSAGE_NEW) {
        if (ev->request) {
            osip_message_t *request = ev->request;
            const char *message_body = osip_message_get_body(request, 0);

            // 解析收到的JSON消息
            json_object *json_root = json_tokener_parse(message_body);
            // 构建要回复的JSON消息
            json_object *json_response = // 构建你要回复的JSON消息

            // 将回复的JSON消息转换为字符串
            const char *response_body = json_object_to_json_string(json_response);

            osip_message_t *response = NULL;
            // 构造一个200 OK请求
            eXosip_message_build_answer(ev->tid, 200, &response);

            // 配置回复消息的Content-Type头
            osip_message_set_content_type(response, "application/json");

            // 设置回复消息的Body，即JSON消息
            osip_message_set_body(response, response_body, strlen(response_body));

            // 发送回复
            eXosip_message_send_response(ev->tid, 200, response);

            // 释放资源
            osip_message_free(response);
            json_object_put(json_root);
        }
    }
    return 0;
}
