```kotlin
import android.Manifest
import android.content.pm.PackageManager
import android.hardware.camera2.CameraAccessException
import android.hardware.camera2.CameraManager
import android.os.Bundle
import android.os.Handler
import android.view.View
import android.widget.Button
import android.widget.EditText
import androidx.appcompat.app.AppCompatActivity
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat

class MainActivity : AppCompatActivity() {
    private lateinit var timeEditText: EditText
    private lateinit var digitEditText: EditText
    private lateinit var startButton: Button

    private val handler = Handler()
    private var currentIndex = 0
    private var binaryDigits = ""

    private var cameraManager: CameraManager? = null
    private var cameraID: String? = null
    private var isFlashOn = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        timeEditText = findViewById(R.id.timeEditText)
        digitEditText = findViewById(R.id.digitEditText)
        startButton = findViewById(R.id.startButton)

        cameraManager = getSystemService(CAMERA_SERVICE) as CameraManager?

        // Проверяем и запрашиваем разрешение камеры, если требуется
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.CAMERA)
                != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(this,
                    arrayOf(Manifest.permission.CAMERA), CAMERA_PERMISSION_CODE)
        }

        startButton.setOnClickListener {
            val timeStr = timeEditText.text.toString()
            val digitStr = digitEditText.text.toString()

            if (timeStr.isNotEmpty() && digitStr.isNotEmpty()) {
                val time = timeStr.toLong()
                binaryDigits = digitStr
                currentIndex = 0

                startAnimation(time)
            }
        }
    }

    private fun startAnimation(time: Long) {
        if (currentIndex >= binaryDigits.length) {
            return
        }

        val currentDigit = binaryDigits[currentIndex]
        toggleFlashLight(currentDigit == '1')

        handler.postDelayed({
            currentIndex++
            startAnimation(time)
        }, time)
    }

    private fun toggleFlashLight(isOn: Boolean) {
        try {
            if (isOn) {
                if (!isFlashOn) {
                    if (cameraID == null) {
                        val cameraIds = cameraManager?.cameraIdList
                        if (cameraIds != null) {
                            for (id in cameraIds) {
                                val characteristics = cameraManager?.getCameraCharacteristics(id)
                                val flashAvailable = characteristics?.get(CameraManager.FLASH_INFO_AVAILABLE)
                                val lensFacing = characteristics?.get(CameraManager.LENS_FACING)

                                if (flashAvailable == true && lensFacing == CameraCharacteristics.LENS_FACING_BACK) {
                                    cameraID = id
                                    break
                                }
                            }
                        }
                    }

                    cameraManager?.setTorchMode(cameraID!!, true)
                    isFlashOn = true
                }
            } else {
                if (isFlashOn) {
                    cameraManager?.setTorchMode(cameraID!!, false)
                    isFlashOn = false
                }
            }
        } catch (e: CameraAccessException) {
            e.printStackTrace()
        }
    }

    companion object {
        private const val CAMERA_PERMISSION_CODE = 123
    }
}
```

