```javascript
const jwt = require('jsonwebtoken');

// Function to validate the access token
function validateAccessToken(req, res, next) {
  // Get the access token from the Authorization header
  const bearerToken = req.headers.authorization;
  if (!bearerToken) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Extract the actual token from the bearer token
  const accessToken = bearerToken.split(' ')[1];
  if (!accessToken) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    // Verify and decode the access token
    const decodedToken = jwt.verify(accessToken, 'YOUR_AZURE_AD_SIGNING_KEY');
    // You can now access the token claims like decodedToken.oid, decodedToken.roles, etc.
    // Perform any additional validation or checks here as required

    // Pass the decoded token to the next middleware or route handler
    req.accessToken = decodedToken;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
}

module.exports = validateAccessToken;
```

In this example, we use the `jsonwebtoken` library to verify the access token using a signing key. You need to replace `'YOUR_AZURE_AD_SIGNING_KEY'` with the actual signing key from your Azure AD configuration.

