```c
#include <stdio.h>
#include <math.h>

void perspectiveMatrix(float fovY, float aspectRatio, float nearPlane, float farPlane, float matrix[4][4]) {
    float fovRad = 1.0f / tanf(fovY * 0.5f * 3.14159f / 180.0f);

    // Set the values of the perspective matrix
    matrix[0][0] = fovRad / aspectRatio;
    matrix[0][1] = 0.0f;
    matrix[0][2] = 0.0f;
    matrix[0][3] = 0.0f;

    matrix[1][0] = 0.0f;
    matrix[1][1] = fovRad;
    matrix[1][2] = 0.0f;
    matrix[1][3] = 0.0f;

    matrix[2][0] = 0.0f;
    matrix[2][1] = 0.0f;
    matrix[2][2] = (farPlane + nearPlane) / (nearPlane - farPlane);
    matrix[2][3] = -1.0f;

    matrix[3][0] = 0.0f;
    matrix[3][1] = 0.0f;
    matrix[3][2] = (2.0f * farPlane * nearPlane) / (nearPlane - farPlane);
    matrix[3][3] = 0.0f;
}

int main() {
    float matrix[4][4];

    // Generate the perspective matrix
    perspectiveMatrix(60.0f, 1.333f, 0.1f, 100.0f, matrix);

    // Print the perspective matrix
    for(int i = 0; i < 4; i++) {
        for(int j = 0; j < 4; j++) {
            printf("%f ", matrix[i][j]);
        }
        printf("\n");
    }

    return 0;
}
```

