```c
/**
 * @brief Compare memory regions.
 *
 * This function compares the memory regions pointed to by `ptr1` and `ptr2`
 * for equality up to `nitems` number of items. It returns -1 if `ptr1` is
 * smaller than `ptr2`, 1 if `ptr1` is larger than `ptr2`, and 0 if they are equal.
 *
 * @param ptr1 Pointer to the first memory region.
 * @param ptr2 Pointer to the second memory region.
 * @param nitems Number of items to compare.
 * 
 * @return Returns -1 if `ptr1` is smaller than `ptr2`, 1 if `ptr1` is larger than 
 *         `ptr2`, and 0 if they are equal.
 */
size_t krt_memcmp(const void *ptr1, const void *ptr2, size_t nitems)
{
        const uint8_t *p1 = (const uint8_t *)ptr1;
        const uint8_t *p2 = (const uint8_t *)ptr2;
        for (size_t i = 0; i < nitems; i++)
        {
                if (p1[i] != p2[i])
                {
                        if (p1[i] < p2[i])
                        {
                                return -1;
                        }
                        else
                        {
                                return 1;
                        }
                }
        }
        return 0;
}
