void printCube() {
    int i, j, k;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            for (k = 0; k < 3; k++) {
                printf("%d ", cube[i][j][k]);
            }
            printf("\t");
        }
        printf("\n");
    }
}

// Function to check if a player has won
int checkWin(int player) {
    int i, j, k;

    // Checking all the rows
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (cube[i][j][0] == player && cube[i][j][1] == player && cube[i][j][2] == player) {
                return 1;
            }
        }
    }

    // Checking all the columns
    for (i = 0; i < 3; i++) {
        for (k = 0; k < 3; k++) {
            if (cube[i][0][k] == player && cube[i][1][k] == player && cube[i][2][k] == player) {
                return 1;
            }
        }
    }

    // Checking all the diagonals
    for (i = 0; i < 3; i++) {
        if (cube[i][0][0] == player && cube[i][1][1] == player && cube[i][2][2] == player) {
            return 1;
        }
        if (cube[i][0][2] == player && cube[i][1][1] == player && cube[i][2][0] == player) {
            return 1;
        }
    }

    // Checking diagonals across the faces
    if (cube[0][0][0] == player && cube[1][1][1] == player && cube[2][2][2] == player) {
        return 1;
    }
    if (cube[0][0][2] == player && cube[1][1][1] == player && cube[2][2][0] == player) {
        return 1;
    }
    if (cube[0][2][0] == player && cube[1][1][1] == player && cube[2][0][2] == player) {
        return 1;
    }
    if (cube[0][2][2] == player && cube[1][1][1] == player && cube[2][0][0] == player) {
        return 1;
    }

    return 0; // No winner
}

// Function to update the cube with player's move
void makeMove(int face, int row, int column) {
    cube[face][row][column] = currentPlayer;
}

// Function to switch between players
void switchPlayer() {
    if (currentPlayer == PLAYER1) {
        currentPlayer = PLAYER2;
    } else {
        currentPlayer = PLAYER1;
    }
}

