```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        CalculateTotalPay("Employee A", 7.50, 35);  // Base pay: $7.50, Hours worked: 35
        CalculateTotalPay("Employee B", 8.20, 43);  // Base pay: $8.20, Hours worked: 43
        CalculateTotalPay("Employee C", 6.50, 50);  // Base pay: $6.50, Hours worked: 50
    }

    static void CalculateTotalPay(string employeeName, double basePay, int hoursWorked)
    {
        const double minimumWage = 8.00;
        const int maxHours = 60;

        if (basePay < minimumWage)
        {
            Console.WriteLine($"Error: Base pay for {employeeName} is below the minimum wage.");
        }
        else if (hoursWorked > maxHours)
        {
            Console.WriteLine($"Error: {employeeName} worked more than {maxHours} hours in a week.");
        }
        else
        {
            double regularPay = 0;
            double overtimePay = 0;

            if (hoursWorked <= 40)
            {
                regularPay = hoursWorked * basePay;
            }
            else
            {
                regularPay = 40 * basePay;
                overtimePay = (hoursWorked - 40) * (basePay * 1.5);
            }

            double totalPay = regularPay + overtimePay;

            Console.WriteLine($"Total pay for {employeeName}: {totalPay:C}");
        }
    }
}
```

In this program, we define a method called `CalculateTotalPay` that takes the employee name, base pay, and hours worked as parameters. Inside this method, we first check if the base pay is below the minimum wage or if the hours worked exceed the maximum allowed hours. If any of these conditions are met, we display an error message.

If the conditions are not met, we calculate the total pay based on the given criteria:
- If the hours worked are 40 or less, we calculate the regular pay by multiplying the hours worked by the base pay.
- If the hours worked are more than 40, we calculate the regular pay as 40 multiplied by the base pay, and the overtime pay as the remaining hours multiplied by 1.5 times the base pay.
- We then calculate the total pay by adding the regular pay and overtime pay.

