```java
import java.util.Arrays;
import java.util.Random;

public class SudokuGenerator {

    private static final int SIZE = 9;
    private static final int EMPTY_VALUE = 0;

    private int[][] board;

    public SudokuGenerator() {
        board = new int[SIZE][SIZE];
    }

    public void generate() {
        if (fillSudoku(0, 0)) {
            removeCells();
        } else {
            System.out.println("Unable to generate a valid Sudoku board.");
        }
    }

    private boolean fillSudoku(int row, int col) {
        if (col == SIZE) {
            col = 0;
            if (++row == SIZE) {
                return true;
            }
        }

        if (board[row][col] != EMPTY_VALUE) {
            return fillSudoku(row, col + 1);
        }

        for (int num = 1; num <= SIZE; num++) {
            if (isValid(row, col, num)) {
                board[row][col] = num;
                if (fillSudoku(row, col + 1)) {
                    return true;
                }
                board[row][col] = EMPTY_VALUE;
            }
        }
        return false;
    }

    private boolean isValid(int row, int col, int num) {
        for (int i = 0; i < SIZE; i++) {
            if (board[row][i] == num || board[i][col] == num) {
                return false;
            }
        }

        int boxRow = 3 * (row / 3);
        int boxCol = 3 * (col / 3);
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[boxRow + i][boxCol + j] == num) {
                    return false;
                }
            }
        }
        return true;
    }

    private void removeCells() {
        Random random = new Random();
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (random.nextDouble() <= 0.5) {
                    board[i][j] = EMPTY_VALUE;
                }
            }
        }
    }

    public void printBoard() {
        for (int i = 0; i < SIZE; i++) {
            System.out.println(Arrays.toString(board[i]));
        }
    }

    public static void main(String[] args) {
        SudokuGenerator generator = new SudokuGenerator();
        generator.generate();
        generator.printBoard();
    }
}
```

This program uses a backtracking algorithm to generate a complete Sudoku board, and then removes some cells randomly to create a partially-filled board. The `fillSudoku` method recursively tries to fill each cell in the board with a valid number, backtracking when necessary. The `isValid` method checks if a number is valid in a particular position according to the Sudoku rules. The `removeCells` method randomly removes some cells from the board to create a puzzle.

In the main method, an instance of `SudokuGenerator` is created, and the `generate` and `printBoard` methods are called to generate a Sudoku board and print it to the console.

