import java.io.FileWriter;
import java.io.IOException;
import java.util.Random;
import java.util.Scanner;

public class PasswordGenerator {

    private static final String UPPERCASE = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String LOWERCASE = "abcdefghijklmnopqrstuvwxyz";
    private static final String NUMBERS = "0123456789";
    private static final String SPECIAL_CHARACTERS = "!@#$%^&*()-_=+[]{}\\|;:'\",.<>/?";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user for password options
        System.out.print("Enter the length of the password: ");
        int length = scanner.nextInt();
        System.out.print("Include uppercase letters? (Y/N): ");
        boolean includeUppercase = scanner.next().equalsIgnoreCase("Y");
        System.out.print("Include lowercase letters? (Y/N): ");
        boolean includeLowercase = scanner.next().equalsIgnoreCase("Y");
        System.out.print("Include numbers? (Y/N): ");
        boolean includeNumbers = scanner.next().equalsIgnoreCase("Y");
        System.out.print("Include special characters? (Y/N): ");
        boolean includeSpecialCharacters = scanner.next().equalsIgnoreCase("Y");

        // Generate the password
        String password = generatePassword(length, includeUppercase, includeLowercase,
                includeNumbers, includeSpecialCharacters);

        // Save the password to a file
        try {
            FileWriter writer = new FileWriter("passwords.txt", true);
            writer.write(password + "\n");
            writer.close();
            System.out.println("Password saved to passwords.txt");
        } catch (IOException e) {
            System.out.println("An error occurred while saving the password to a file.");
            e.printStackTrace();
        }
    }

    private static String generatePassword(int length, boolean includeUppercase,
                                           boolean includeLowercase, boolean includeNumbers,
                                           boolean includeSpecialCharacters) {
        StringBuilder characters = new StringBuilder();

        if (includeUppercase) {
            characters.append(UPPERCASE);
        }
        if (includeLowercase) {
            characters.append(LOWERCASE);
        }
        if (includeNumbers) {
            characters.append(NUMBERS);
        }
        if (includeSpecialCharacters) {
            characters.append(SPECIAL_CHARACTERS);
        }

        Random random = new Random();
        StringBuilder password = new StringBuilder();

        for (int i = 0; i < length; i++) {
            int index = random.nextInt(characters.length());
            password.append(characters.charAt(index));
        }

        return password.toString();
    }
}
```

