  const itinerary = randomCodes.map(code => {
    const country = getCountryNameByCode(code);
    return `${country} (${code})`;
  }).join(' -> ');

  const itineraryElement = document.getElementById('itinerary');
  itineraryElement.textContent = `Your random travel itinerary: ${itinerary}`;
}

function getRandomCountryCodes(count) {
  const shuffled = countryCodes.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count).map(obj => obj.code);
