        var options = new BackgroundJobServerOptions
        {
            Queues = new[] { "default", "myqueue" }, // Add any custom queues you want to use
            WorkerCount = 1 // Number of workers to process background jobs
        };

        using (var server = new BackgroundJobServer(options))
        {
            // Start the Hangfire server
        }
    }
}
```

Step 4: In the Global.asax file, add the following code:
```csharp
void Application_Start(object sender, EventArgs e)
{
    // Code that runs on application startup
    HangfireConfig.ConfigureHangfire();
}
```

Step 5: Create a new ASPX page called "Default.aspx" and add a button control to it:
```aspx
<%@ Page Language="C#" AutoEventWireup="true" CodeBehind="Default.aspx.cs" Inherits="HangfireExample._Default" %>

