</body>
</html>
```

Step 6: In the code-behind file "Default.aspx.cs", add the following code:
```csharp
using Hangfire;

namespace HangfireExample
{
    public partial class _Default : System.Web.UI.Page
    {
        protected void btnScheduleJob_Click(object sender, EventArgs e)
        {
            Hangfire.BackgroundJob.Enqueue(() => ProcessJob()); // Schedule the background job
        }

        public void ProcessJob()
        {
            // Code to be executed in the background
            System.Threading.Thread.Sleep(5000); // Simulate some long-running operation
            System.Diagnostics.Debug.WriteLine("Background job executed!");
        }
    }
}
```

That's it! Now, when you run the application and click the "Schedule Job" button on the Default.aspx page, a background job is enqueued and processed by Hangfire.

