        return view
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        Slider_List = listOf(
            SlideItem("hello", "hi", R.drawable._54282_admin),
            SlideItem("hello", "hi", R.drawable._54282_admin),
            SlideItem("hello", "hi", R.drawable._54282_admin),
            SlideItem("hello", "hi", R.drawable._54282_admin),
            SlideItem("hello", "hi", R.drawable._54282_admin),
        )
        recyclerView = requireView().findViewById(R.id.sliderRecyclerView)
        recyclerView.setHasFixedSize(false)
        recyclerView.layoutManager =
            LinearLayoutManager(requireContext(), LinearLayoutManager.HORIZONTAL, false)
        recyclerView.adapter = SliderAdapter(Slider_List)

        val snapHelper = LinearSnapHelper()
        snapHelper.attachToRecyclerView(recyclerView)

        timer = Timer()
        timer.scheduleAtFixedRate(object : TimerTask() {
            override fun run() {
                recyclerView.post{
                    val layoutManager = recyclerView.layoutManager as LinearLayoutManager
                    val firstVisiblePosition = layoutManager.findFirstVisibleItemPosition()
                    val lastVisiblePosition = layoutManager.findLastVisibleItemPosition()

                    if (firstVisiblePosition > 0 && lastVisiblePosition < Slider_List.size - 1) {
                        // Слайдер не находится в полном состоянии элемента
                        val centerPosition = layoutManager.findLastCompletelyVisibleItemPosition()

                        val centerX = recyclerView.width / 2
                        val childView = recyclerView.findViewHolderForAdapterPosition(centerPosition)?.itemView
                        val childCenterX = childView?.left?.plus(childView.width / 2)

                        if (childCenterX != null && childCenterX < centerX) {
                            // Слайдер смещен влево от центра
                            recyclerView.smoothScrollToPositionWithOffset(centerPosition + 1, 0)
                        } else {
                            // Слайдер смещен вправо от центра
                            recyclerView.smoothScrollToPositionWithOffset(centerPosition, 0)
                        }
                    } else {
                        // Слайдер находится в полном состоянии элемента
                        recyclerView.smoothScrollToPosition(firstVisiblePosition)
                    }
                }
            }
        }, 0, 10000)
    }

    override fun onDestroyView() {
        super.onDestroyView()
        timer.cancel()
    }

    companion object {
        @JvmStatic
        fun newInstance() = HomeFragment()
    }
