// Alternative to built-in 'brw<a>', represents state.
// Suitable for cases where you want to abstract a piece of code that
// uses non-null pointers.

// Creates a pure reference object that represents a state.
// @param initial: The initial value of the state.
// @returns: A reference object that can be used to set or get the value of the state.
func pure_ref<a>(initial: a): ref<a> {
    // Create a new ref effect-handler by catching the 'this' effect.
    try this catch this: ref<a> {
        // Define the set and get methods for the ref object.
        * set(value): resume => resume(pure_ref(value)),
        * get: resume => resume(initial),
    }
}

// Creates an impure reference object that represents a state using a provided brw object.
// @param brw: The brw object that provides the set and get methods for the state.
// @returns: A reference object that can be used to set or get the value of the state.
func impure_ref<a>(brw: brw<a>): ref<a> {
    // Create a new ref effect-handler by catching the 'this' effect.
    try this catch this: ref<a> {
        // Define the set and get methods for the ref object.
        * set(value): resume => brw.set(value); resume(brw),
        * get: resume => resume(brw.get()),
    }
}
