Certainly! To determine if the rocket will reach Mars, we need to compare the product of velocity and time with the distance to Mars, as well as the product of fuel and fuel consumption with the distance. We also need to consider the availability of enough time and fuel.

Here's the C# program that calculates whether the rocket will reach Mars based on the given criteria:

```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        double velocity, time, distance, fuel, fuelConsumption;

        Console.WriteLine("Enter the velocity of the rocket (in km/h):");
        velocity = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter the time available for the journey (in hours):");
        time = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter the distance to Mars (in kilometers):");
        distance = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter the amount of fuel available (in liters):");
        fuel = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter the fuel consumption (in kilometers per liter):");
        fuelConsumption = Convert.ToDouble(Console.ReadLine());

        double fuelRequired = distance / fuelConsumption;

        if (velocity * time >= distance && fuel * fuelConsumption >= distance)
        {
            Console.WriteLine("Welcome to Mars");
        }
        else if (velocity * time < distance && fuel * fuelConsumption < distance)
        {
            Console.WriteLine("Failure, Not enough time and fuel");
        }
        else if (velocity * time < distance)
        {
            Console.WriteLine("Failure, Not enough time");
        }
        else if (fuel * fuelConsumption < distance)
        {
            Console.WriteLine("Failure, Not enough fuel");
        }
    }
}
