  const input = inputField.value.toLowerCase(); // Convert input to lowercase
  const anagrams = getAnagrams(input);
  displayAnagrams(anagrams);
}

// Function to generate anagrams
function getAnagrams(word) {
  const permutations = [];

  // Recursive function
  function generate(word, ana = '') {
    if (!word) {
      permutations.push(ana);
      return;
    }

    for (let i = 0; i < word.length; i++) {
      generate(word.slice(0, i) + word.slice(i + 1), ana + word[i]);
    }
  }

  generate(word);
  return permutations;
}

