    {
        while (true)
        {
            if (isTimeReduction)
            {
                ConvertTime(ref timeSeconds, -1);
                yield return new WaitForSeconds(1);
            }
            else
            {
                ConvertTime(ref timeSeconds, 1);
                yield return new WaitForSeconds(1);
            }
        }
    }

    private void ConvertTime(ref float time, int multiplier)
    {
        var convertedTime = time * multiplier;
        var hours = Mathf.Floor(convertedTime / 3600);
        var minutes = Mathf.Floor((convertedTime % 3600) / 60);
        var seconds = Mathf.Floor(convertedTime % 60);

        UpdateQuestTime(hours, minutes, seconds);
    }

    private void UpdateQuestTime(float hours, float minutes, float seconds)
    {
        hourHand.text = $"{((int)hours):D2}:{((int)minutes):D2}:{((int)seconds):D2}";
    }
