```c
#include <stdint.h>
#include "FreeRTOS.h"
#include "task.h"

#define CACHE_LINE_SIZE 32

// Function to flush a cache line
static inline void flush_cache_line(volatile void *p)
{
    __asm__ volatile ("DC CIVAC, %0" : : "r" (p));
}

// Function to flush the entire data cache
static inline void flush_dcache(void)
{
    __asm__ volatile ("DSB SY");
    __asm__ volatile ("DC CIVAC, ALL");
    __asm__ volatile ("DSB SY");
    __asm__ volatile ("ISB SY");
}

// Function to flush a specific range of memory
void __flush_dcache_area(void *ptr, size_t len)
{
    uintptr_t start_addr = (uintptr_t)ptr;
    uintptr_t end_addr = start_addr + len;
    uintptr_t start_line = start_addr & ~(CACHE_LINE_SIZE - 1);
    uintptr_t end_line = (end_addr + CACHE_LINE_SIZE - 1) & ~(CACHE_LINE_SIZE - 1);

    taskENTER_CRITICAL();

    flush_dcache();

    // Flush cache lines within the specified range
    volatile uint8_t *line_ptr;
    for (line_ptr = (volatile uint8_t *)start_line; line_ptr < (volatile uint8_t *)end_line; line_ptr += CACHE_LINE_SIZE)
    {
        flush_cache_line(line_ptr);
    }

    flush_dcache();

    taskEXIT_CRITICAL();
}
```

This implementation provides a similar functionality to the original `__flush_dcache_area()` function by flushing the entire data cache and then flushing each cache line within the specified memory range. The function also ensures atomicity by using a critical section.

