// Function to add two arrays representing numbers
function addArrays(arr1, arr2) {
  let res = [];
  let carry = 0;
  let len = Math.max(arr1.length, arr2.length);

  for (let i = 0; i < len; i++) {
    let sum = (arr1[i] || 0) + (arr2[i] || 0) + carry;
    res.push(sum % 10);
    carry = Math.floor(sum / 10);
  }

  if (carry > 0) {
    res.push(carry);
  }

  return res;
}

// Function to multiply two arrays representing numbers
function multiplyArrays(arr1, arr2) {
  let res = Array(arr1.length + arr2.length).fill(0);

  for (let i = 0; i < arr1.length; i++) {
    for (let j = 0; j < arr2.length; j++) {
      let product = arr1[i] * arr2[j];
      let pos1 = i + j;
      let pos2 = pos1 + 1;

      let sum = product + res[pos2];

      res[pos1] += Math.floor(sum / 10);
      res[pos2] = sum % 10;
    }
  }

  while (res.length > 0 && res[res.length - 1] === 0) {
    res.pop();
  }

  return res;
}

// Function to perform modular exponentiation for arrays representing numbers
function modularExponentiation(base, exponent, modulus) {
  if (modulus.length === 1 && modulus[0] === 1) return [0];

  let result = [1];

  for (let i = 0; i < exponent.length; i++) {
    let currBit = exponent[i];
    if (currBit === 1) {
