```javascript
// Function to send a message and get a response from the ChatGPT model
async function sendMessage(message) {
    const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            'message': message
        })
    });

    if (!response.ok) {
        throw new Error(`An error occurred: ${response.status}`);
    }

    const { id } = await response.json();

    // Open a new connection to stream the messages
    const eventSource = new EventSource(`/api/chat/stream?id=${id}`);
    eventSource.onmessage = (event) => {
        const { message } = JSON.parse(event.data);

        // Handle the received message (e.g., append it to the chat container)
        displayMessage(message);
    };
}

// Function to display a chat message on the web page
