            float currentSpeed = speeds[i];

            if (currentSpeed >= 0)
            {
                float time = Math.Abs((2 * currentSpeed) / 9.8f);
                if (time < fastestTime)
                {
                    fastestTime = time;
                    fastestObject = currentObject;
                }
            }

            float altitude = Math.Abs((currentSpeed * currentSpeed) / (2 * 9.8f));
            if (altitude > highestAltitude)
            {
                highestAltitude = altitude;
                highestObject = currentObject;
            }
        }

