        char[][] seaMap = new char[N][]; // Create a 2D array to store the sea map

        // Read each line of the map and store it in the seaMap array
        for (int i = 0; i < N; i++)
        {
            seaMap[i] = Console.ReadLine().ToCharArray();
        }

        int islandCount = CountIslands(seaMap); // Count the number of separated islands

        Console.WriteLine(islandCount); // Output the number of islands
    }

    public static int CountIslands(char[][] seaMap)
    {
        int islandCount = 0;
        int N = seaMap.Length;
        int M = seaMap[0].Length;
        bool[][] visited = new bool[N][]; // Create a 2D array to keep track of visited elements
        for (int i = 0; i < N; i++)
        {
            visited[i] = new bool[M];
        }

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < M; j++)
            {
                if (seaMap[i][j] != '*' && !visited[i][j])
                {
                    islandCount++;
                    VisitIsland(seaMap, visited, i, j, N, M);
                }
            }
        }

        return islandCount;
    }

    public static void VisitIsland(char[][] seaMap, bool[][] visited, int i, int j, int N, int M)
    {
        if (i < 0 || i >= N || j < 0 || j >= M)
        {
            return;
        }

        if (visited[i][j] || seaMap[i][j] == '*')
        {
            return;
        }

        visited[i][j] = true;
        VisitIsland(seaMap, visited, i + 1, j, N, M); // Visit downward
        VisitIsland(seaMap, visited, i - 1, j, N, M); // Visit upward
        VisitIsland(seaMap, visited, i, j + 1, N, M); // Visit right
        VisitIsland(seaMap, visited, i, j - 1, N, M); // Visit left
    }
}
```

