2. Создайте компонент для вашего Pixi-сцены:
```javascript
const MyStage = () => {
  const [children, setChildren] = useState([]);

  // Функция для добавления дочерних элементов на сцену
  const addChild = (child) => {
    setChildren((prevChildren) => [...prevChildren, child]);
  };

  // Функция для очистки сцены
  const clearStage = () => {
    setChildren([]);
  };

  // Очищаем сцену при первом рендеринге
  useEffect(() => {
    clearStage();
  }, []);

  // Используем функцию useTick для вызова функции очистки сцены каждый кадр
  useTick(() => {
    clearStage();
  });

  return (
    <Stage>
      {children}
    </Stage>
  );
};
```

3. Используйте компонент MyStage в своем приложении:
```javascript
