```java
private <K, V> Map<K, JsonFieldAuditChangeDetector.ValueDifference> difference(
        Map<? extends K, V> newNode,
        Map<? extends K, V> oldNode,
        String fieldName) {

    Map<K, JsonFieldAuditChangeDetector.ValueDifference> differences = new HashMap<>();

    Map<K, Object> onlyOldValue = new HashMap<>(oldNode);

    String suffix = getSuffix(newNode);

    newNode.entrySet().forEach(entryFromNewValue -> {
        K newValueKey = entryFromNewValue.getKey();
        Object newEntryValue = entryFromNewValue.getValue();

        String fieldNameKey = fieldName + "." + newValueKey + suffix;

        if (oldNode.containsKey(newValueKey)) {
            Object oldEntryValue = onlyOldValue.remove(newValueKey);

            if (oldEntryValue instanceof Map && newEntryValue instanceof Map) {
                differences.putAll(difference((Map) newEntryValue, (Map) oldEntryValue, fieldNameKey));
            } else if (oldEntryValue instanceof List && newEntryValue instanceof List) {
                differences.putAll(difference(this, (List) newEntryValue, (List) oldEntryValue, differences, fieldNameKey));
            } else if (!Objects.equals(newEntryValue, oldEntryValue)) {
                differences.put((K) fieldNameKey, new JsonFieldAuditChangeDetector.ValueDifference<>(newEntryValue, oldEntryValue));
            }
        } else {
            differences.put((K) fieldNameKey, new JsonFieldAuditChangeDetector.ValueDifference(newEntryValue, null));
        }
    });

    return differences;
}
```

