void setup() {
  Serial.begin(9600);
  espSerial.begin(115200); // Set baud rate for ESP8266 communication
  delay(2000); // Wait for ESP8266 module to initialize

  sendDataToServer(); // Send initial temperature data to server
}

void loop() {
