}

float readTemperature() {
  int rawValue = analogRead(temperaturePin);
  float voltage = rawValue * 5.0 / 1024.0;
  float temperature = (voltage - 0.5) * 100.0;
  return temperature;
}

void sendDataToESP(float temperature) {
  espSerial.print("TEMP:"); // Send temperature prefix
  espSerial.print(temperature); // Send temperature value
  espSerial.print("\n"); // Send line break
}

void sendDataToServer() {
  espSerial.println("AT+CWMODE=1"); // Set ESP8266 to Station mode
