#include <SoftwareSerial.h>
#include <ESP8266WiFi.h>
#include <ESP8266HTTPClient.h>

SoftwareSerial megaSerial(10, 11);  // RX, TX pins for Arduino Mega communication

const char* ssid = "Your_WiFi_SSID";
const char* password = "Your_WiFi_Password";
const char* serverAddress = "your_server_address";
const int serverPort = your_server_port;

void setup() {
  Serial.begin(9600);
  megaSerial.begin(115200); // Set baud rate for Arduino Mega communication

  delay(1000);
  connectToWiFi();
}

void loop() {
  String receivedData = "";

  while (megaSerial.available() > 0) {
    char receivedChar = megaSerial.read();
    receivedData += receivedChar;
    delay(2); // Some delay to allow receiving complete data
  }

  if (receivedData.startsWith("TEMP:")) {
    String temperatureString = receivedData.substring(5);
    float temperature = temperatureString.toFloat();
    sendDataToServer(temperature);
  }
}

void connectToWiFi() {
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }

  Serial.println("Connected to WiFi!");
}

void sendDataToServer(float temperature) {
  HTTPClient http;
  String serverURL = "http://" + String(serverAddress) + "/sensor.php";

  if (http.begin(serverURL)) {
    http.addHeader("Content-Type", "application/x-www-form-urlencoded");
    String data = "data=" + String(temperature);

    int httpResponseCode = http.POST(data);
    if (httpResponseCode > 0) {
      String response = http.getString();
      Serial.println("Server response: " + response);
    } else {
      Serial.print("HTTP POST failed with error code ");
      Serial.println(httpResponseCode);
    }

    http.end();
  } else {
    Serial.println("Unable to connect to server!");
  }
}
