```c
#include <stdio.h>
#include <string.h>
#include <netinet/ip.h>

// IP伪头部结构体
struct pseudoheader {
    uint32_t source_address;
    uint32_t destination_address;
    uint8_t placeholder;
    uint8_t protocol;
    uint16_t tcp_length;
};

// 计算16位校验和
uint16_t calculate_checksum(uint16_t *data, int length) {
    uint32_t sum = 0;
    while (length > 1) {
        sum += *data++;
        length -= 2;
    }

    // 处理最后剩余的奇数个字节
    if (length == 1) {
        sum += *((uint8_t *)data);
    }

    // 将进位添加到低位
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }

    // 取反获得校验和
    return (uint16_t)(~sum);
}

int main() {
