Here is an example of AES ECB mode encryption using the Rust programming language with the `aes` and `block-modes` crates.

```rust
use aes::Aes256;
use block_modes::{BlockMode, Ecb};
use block_modes::block_padding::NoPadding;

fn main() {
    let key: [u8; 32] = [ // The AES-256 key
        0x2b, 0x7e, 0x15, 0x16, 0x28, 0xae, 0xd2, 0xa6,
        0xab, 0xf7, 0x15, 0x88, 0x09, 0xcf, 0x4f, 0x3c,
        0x2b, 0x7e, 0x15, 0x16, 0x28, 0xae, 0xd2, 0xa6,
        0xab, 0xf7, 0x15, 0x88, 0x09, 0xcf, 0x4f, 0x3c,
    ];
    let plaintext = b"plaintext data"; // The input data to encrypt

    let cipher = Ecb::<Aes256, NoPadding>::new_var(&key, Default::default()).unwrap();
    let ciphertext = cipher.encrypt_vec(plaintext);

    println!("Ciphertext: {:?}", ciphertext);
}
```

