import featureFlag from './featureFlag';

describe('featureFlag', () => {
	let mockWindow;

	beforeEach(() => {
		mockWindow = {
			omnia: {
				featureFlags: {
					flags: {},
					flagChangeListeners: {},
					setFlag: jest.fn(),
				},
			},
		};
	});

	it('should return default value when window is undefined', () => {
		delete global.window;
		const flag = featureFlag<boolean>('testFlag', false);
		expect(flag.getValue()).toBe(undefined);
	});

	it('should return default value when window.omnia.featureFlags is undefined', () => {
		mockWindow.omnia.featureFlags = undefined;
		const flag = featureFlag<boolean>('testFlag', false);
		expect(flag.getValue()).toBe(undefined);
	});

	it('should return default value when flag is not set', () => {
		const flag = featureFlag<boolean>('testFlag', false);
		expect(flag.getValue()).toBe(false);
	});

	it('should return flag value when flag is set', () => {
		mockWindow.omnia.featureFlags.flags.testFlag = true;
		const flag = featureFlag<boolean>('testFlag', false);
		expect(flag.getValue()).toBe(true);
	});

	it('should set flag value and call listener when setFlag is called', () => {
		const flag = featureFlag<boolean>('testFlag', false);
		const listener = jest.fn();
		flag.setListener(listener);
		flag.getValue();
		expect(flag.getValue()).toBe(false);

		flag.setFlag(true);
		expect(flag.getValue()).toBe(true);
		expect(listener).toHaveBeenCalledWith(true);
	});

	it('should throw an error when trying to set a listener without featureFlags', () => {
		delete mockWindow.omnia.featureFlags;
		const flag = featureFlag<boolean>('testFlag', false);
		expect(() => flag.setListener(jest.fn())).toThrow('Failed to set a feature flag listener.');
	});

	it('should remove flag listener when removeListener is called', () => {
		const flag = featureFlag<boolean>('testFlag', false);
		const listener = jest.fn();
		flag.setListener(listener);
		flag.getValue();
		expect(flag.getValue()).toBe(false);

		flag.removeListener();
		flag.setFlag(true);
		expect(flag.getValue()).toBe(true);
		expect(listener).not.toHaveBeenCalled();
	});
