import React, { useLayoutEffect, useState } from 'react';
import { Image, Pressable, StyleSheet, Text } from 'react-native';
import Animated, {
  useSharedValue,
  withTiming,
  useAnimatedStyle,
} from 'react-native-reanimated';

// Components
import { LocationIcon } from '../components';

// Images
const allLocationsIcon = require('@assets/home/header/allLocationsIcon.png');

type SimpleLocationItemProps = {
  color: string;
  label: string;
  index: number;
  onPress: (index: number) => void;
};

const SimpleLocationItem = ({
  color,
  label,
  index,
  onPress,
}: SimpleLocationItemProps) => {
  const [isSelected, setIsSelected] = useState(false);
  const borderColor = useSharedValue('transparent');

  const animatedStyle = useAnimatedStyle(() => {
    return {
      borderColor: borderColor.value,
      borderWidth: isSelected ? withTiming(2) : withTiming(0),
    };
  });

  const onItemPress = () => {
    setIsSelected(!isSelected);
    borderColor.value = isSelected ? withTiming('transparent') : withTiming('orange');
    onPress(index);
  };

  return (
    <Pressable onPress={onItemPress}>
      <Animated.View style={[styles.circleContainer, animatedStyle]}>
        <LocationIcon backgroundColor={color}>
          <Text style={styles.character}>{label}</Text>
        </LocationIcon>
      </Animated.View>
    </Pressable>
  );
};

export default SimpleLocationItem;

