class Sorter {
public:
    Sorter() {
        sortDirection.clear();
    }

    void toggleSortDirection(int col) {
        if (sortDirection.find(col) == sortDirection.end()) {
            sortDirection[col] = true; // true = ascending, default sorting direction
        } else {
