#include <stdio.h>

// Function to calculate the greatest common divisor using Euclidean algorithm
long long gcdExtended(long long a, long long b, long long* x, long long* y) {
    // Base case when a = 0
    if (a == 0) {
        *x = 0;
        *y = 1;
        return b;
    }

    long long x1, y1; // Variables to store results of recursive call
    long long gcd = gcdExtended(b % a, a, &x1, &y1);

    // Update x and y using results of recursive call
    *x = y1 - (b / a) * x1;
    *y = x1;

    return gcd;
}

// Function to calculate modular multiplicative inverse of 'a' modulo 'm'
long long modularMultiplicativeInverse(long long a, long long m) {
    long long x, y;
    long long gcd = gcdExtended(a, m, &x, &y);

    if (gcd != 1) {
        printf("Inverse doesn't exist\n");
        return -1;
    }

    return (x % m + m) % m;
}

