    long long modulus = /* specify your desired modulus value, e.g., 2^31 - 1 */;

    // Calculate the modular multiplicative inverse of 'a' modulo 'modulus'
    long long aInverse = modularMultiplicativeInverse(a, modulus);

    // Calculate the constant term required for reverse LCG
    long long cReverse = (c - 1 + modulus) * aInverse % modulus;

    printf("Multiplier: %lld\n", aInverse);
    printf("Constant: %lld\n", cReverse);
}

int main() {
