To calculate gradients in Rust, you can use the `ndarray::gradient::Gradient` trait along with the `ndarray::Zip` iterator to iterate over the array and calculate the gradients manually.

Here's an updated version of the code:

```rust
use ndarray::{Array, Array2, Axis};
use ndarray_stats::errors::MinMaxError;
use std::f64::consts::PI;

fn clamp(z: &Array2<f64>, vmin: f64, vmax: f64) -> Result<Array2<f64>, MinMaxError> {
    Ok(z.mapv(|val| val.max(vmin).min(vmax)))
}

fn gradient_angle(z: &Array2<f64>) -> Array2<f64> {
    let dz_dx = z.indexed_iter()
        .map(|((r, c), _)| {
            let left = z.get((r, c.saturating_sub(1))).unwrap_or(&0.0);
            let right = z.get((r, c + 1)).unwrap_or(&0.0);
            right - left
        })
        .collect();

    let dz_dy = z.indexed_iter()
        .map(|((r, c), _)| {
            let up = z.get((r.saturating_sub(1), c)).unwrap_or(&0.0);
            let down = z.get((r + 1, c)).unwrap_or(&0.0);
            down - up
        })
        .collect();

    Array::from_shape_vec(z.dim(), dz_dy.into_iter().map(|dy| dy.atan2(dz_dx[0])).collect()).unwrap()
}

fn gradient_norm(z: &Array2<f64>) -> Array2<f64> {
    let dz_dx = z.indexed_iter()
        .map(|((r, c), _)| {
            let left = z.get((r, c.saturating_sub(1))).unwrap_or(&0.0);
            let right = z.get((r, c + 1)).unwrap_or(&0.0);
            right - left
        })
        .collect();

    let dz_dy = z.indexed_iter()
        .map(|((r, c), _)| {
            let up = z.get((r.saturating_sub(1), c)).unwrap_or(&0.0);
            let down = z.get((r + 1, c)).unwrap_or(&0.0);
            down - up
        })
        .collect();

    let dz_dx_sq: Vec<f64> = dz_dx.iter().map(|&dx| dx.powi(2)).collect();
    let dz_dy_sq: Vec<f64> = dz_dy.iter().map(|&dy| dy.powi(2)).collect();

    Array::from_shape_vec(z.dim(), dz_dx_sq.iter().zip(dz_dy_sq.iter()).map(|(&dx_sq, &dy_sq)| dx_sq + dy_sq).collect()).unwrap()
