fn gaussian_curvature(z: &Array2<f64>, sigma: f64) -> Result<(Array2<f64>, Array2<f64>), MinMaxError> {
    let gaussian_filtered = ndarray::ArrayD::<f64>::from(z.clone().to_owned()).gaussian_filter(sigma);

    let z = Array::from_shape_vec(z.dim(), gaussian_filtered.into_raw_vec()).unwrap();

    let zx = gradient_norm(&z);
    let zy = gradient_norm(&z.t());

    let zxx = gradient_norm(&zx);
    let zxy = gradient_norm(&zy.t());

    let zyy = gradient_norm(&zy.t());

    // Gaussian curvature = K1 * K2
    let k = (&zxx * &zyy - &zxy.powf(2.0)) / (1.0 + (&zx.powf(2.0)) + (&zy.powf(2.0))).powf(2.0);
    // mean curvature = (K1 + K2)/2
    let h = (&zxx * (1.0 + &zy.powf(2.0)) - 2.0 * &zxy * &zx * &zy + &zyy *
        (1.0 + &zx.powf(2.0))) / (2.0 * (1.0 + &zx.powf(2.0) + &zy.powf(2.0))).sqrt();

    Ok((k, h))
}

fn hillshade(z: &Array2<f64>, azimuth: f64, zenith: f64, talus_ref: f64) -> Result<Array2<f64>, MinMaxError> {
    let azimuth_rad = PI * azimuth / 180.0;
    let zenith_rad = PI * zenith / 180.0;

    let aspect = gradient_angle(z);
    let dn = gradient_norm(z).mapv(|val| val / talus_ref);
    let slope = dn.mapv(|val| val.atan());

    let sh = ((zenith_rad.cos() * &slope.cos()) + (zenith_rad.sin() * &slope.sin() * &(azimuth_rad - &aspect).cos()))
        .mapv(|val| (val - val.floor()).max(0.0) / (val.ceil() - val.floor()).max(1.0));

    Ok(sh)
}

