std::vector<std::vector<int>> generateComplementGraph(const std::vector<std::vector<int>>& graph) {
    int n = graph.size();  // Number of vertices in the graph

    // Create a new adjacency matrix for the complement graph, initially filled with all 0's
    std::vector<std::vector<int>> complement(n, std::vector<int>(n, 0));

