    EVP_DigestInit_ex(mdCtx, md, NULL);
    EVP_DigestUpdate(mdCtx, sharedInfo, sharedInfoLen);
    EVP_DigestFinal_ex(mdCtx, ctx->key, NULL);
    EVP_MD_CTX_free(mdCtx);
}

void KDF_X9_63_DeriveKey(KDF_X9_63_Context* ctx, unsigned char* derivedKey, size_t derivedKeyLen, const unsigned char* keyMaterial, size_t keyMaterialLen) {
    EVP_PKEY* pkey = EVP_PKEY_new();
    EVP_PKEY_CTX* pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    EVP_PKEY_keygen_init(pctx);
    EVP_PKEY_CTX_set_hmac_md(pctx, ctx->md);
    EVP_PKEY_CTX_set_hmac_key(pctx, ctx->key, 32);
    EVP_PKEY_CTX_ctrl(pctx, -1, EVP_PKEY_OP_DERIVE, EVP_PKEY_CTRL_SET_MAC_KEY, keyMaterialLen, (void*)keyMaterial);

    size_t outLen;
    EVP_PKEY_derive(pctx, NULL, &outLen);
    unsigned char* out = (unsigned char*)malloc(outLen);
    EVP_PKEY_derive(pctx, out, &outLen);
    memcpy(derivedKey, out, derivedKeyLen);

    free(out);
    EVP_PKEY_CTX_free(pctx);
    EVP_PKEY_free(pkey);
}

void printHex(unsigned char* data, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        printf("%02x", data[i]);
    }
    printf("\n");
}

int main() {
    const unsigned char sharedInfo[] = "some_shared_info";
    const size_t sharedInfoLen = strlen((const char*)sharedInfo);
    const unsigned char keyMaterial[] = "key_material";
    const size_t keyMaterialLen = strlen((const char*)keyMaterial);
    unsigned char aesKey[16]; // AES-128 Key
    unsigned char hmacKey[64]; // HMAC-SHA512 Key

    // Initialize KDF context
    KDF_X9_63_Context ctx;
    KDF_X9_63_Init(&ctx, EVP_sha256(), sharedInfo, sharedInfoLen);

    // Derive AES-128 key
    KDF_X9_63_DeriveKey(&ctx, aesKey, sizeof(aesKey), keyMaterial, keyMaterialLen);
    printf("AES-128 Key: ");
    printHex(aesKey, sizeof(aesKey));

    // Derive HMAC-SHA512 key
    KDF_X9_63_DeriveKey(&ctx, hmacKey, sizeof(hmacKey), keyMaterial, keyMaterialLen);
    printf("HMAC-SHA512 Key: ");
    printHex(hmacKey, sizeof(hmacKey));

    return 0;
}
```

Note: This code uses the OpenSSL library for cryptographic functions. Make sure to link the OpenSSL library (`-lcrypto`) while compiling the code. Also, remember to include the necessary header files and install OpenSSL if you don't have it already.

The code sets up a structure `KDF_X9_63_Context` to hold the context for the KDF. The `KDF_X9_63_Init` function initializes the context by taking a sharedInfo string and its length, and derives a 256-bit secret key using a chosen hash function (in this example, SHA-256).

The `KDF_X9_63_DeriveKey` function takes the initialized context, along with the key material and its length, and uses the HMAC-based key derivation function defined by X9.63 to derive the desired key. The derived key is stored in the `derivedKey` buffer.

In the `main` function, the example demonstrates the usage of the KDF by deriving both AES-128 and HMAC-SHA512 keys from the sharedInfo and keyMaterial strings, respectively. Finally, the derived keys are printed in hexadecimal format.

Please note that this code is provided as an example and may need to be adjusted depending on your specific requirements and the libraries you are using.

package com.rumikuru.skdumobile.components.template.viewModels

import android.content.ContentValues
import android.content.ContentValues.TAG
import android.content.Context
