要让ComboBox的高度根据内容显示的形式自动变化，可以使用自定义的ComboBox控件和一个ListBox作为其下拉列表。以下是一个示例的代码：

```csharp
public class AutoHeightComboBox : ComboBox
{
    private bool isUpdatingHeight;

    protected override void OnDropDownOpened(EventArgs e)
    {
        base.OnDropDownOpened(e);

        // 更新ComboBox的高度为ListBox的预测高度
        UpdateComboBoxHeight();
    }

    protected override void OnDropDownClosed(EventArgs e)
    {
        base.OnDropDownClosed(e);

        // 还原ComboBox的高度
        this.ClearValue(HeightProperty);
    }

    protected override void OnSelectionChanged(SelectionChangedEventArgs e)
    {
        base.OnSelectionChanged(e);

        if (!isUpdatingHeight && IsDropDownOpen)
        {
            // 更新ComboBox的高度为ListBox的预测高度
            UpdateComboBoxHeight();
        }
    }

    private void UpdateComboBoxHeight()
    {
        // 获取ListBox控件实例
        var listBox = this.Template.FindName("PART_ListBox", this) as ListBox;
        if (listBox == null)
            return;

        // 更新ComboBox的高度为ListBox的预测高度
        isUpdatingHeight = true;
        this.Height = listBox.ActualHeight;
        isUpdatingHeight = false;
    }
}
```

