#define SERVER_PORT 8080          // 服务器端口号
#define MAX_BUFFER_SIZE 4096      // 每个分片的缓冲区大小
#define MAX_PACKET_SIZE 5000      // 要发送的数据大小

int main() {
    int clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == -1) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_addr.s_addr = inet_addr(SERVER_IP);
    serverAddr.sin_port = htons(SERVER_PORT);

    if (connect(clientSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) == -1) {
        perror("Failed to connect to server");
        exit(EXIT_FAILURE);
    }

    char buffer[MAX_BUFFER_SIZE];
    memset(buffer, 0, sizeof(buffer));

    char data[MAX_PACKET_SIZE];
    memset(data, 'A', sizeof(data));

    int totalBytesSent = 0;
    int packetSize = MAX_BUFFER_SIZE;

    while (totalBytesSent < MAX_PACKET_SIZE) {
        if (totalBytesSent + MAX_BUFFER_SIZE > MAX_PACKET_SIZE) {
            packetSize = MAX_PACKET_SIZE - totalBytesSent;
        }

        memcpy(buffer, data + totalBytesSent, packetSize);

        int bytesSent = send(clientSocket, buffer, packetSize, 0);
        if (bytesSent == -1) {
            perror("Failed to send data");
            exit(EXIT_FAILURE);
        }

        totalBytesSent += bytesSent;
    }

    printf("Sent data size: %d bytes\n", totalBytesSent);

    close(clientSocket);

    return 0;
}
