public static void downloadFileFromSharePoint(String url, String username, String password, String outputFilePath)
            throws IOException {
    // Create HTTP client and set authentication credentials
    CloseableHttpClient httpClient = HttpClients.createDefault();
    httpClient.getCredentialsProvider().setCredentials(
            new AuthScope(AuthScope.ANY),
            new UsernamePasswordCredentials(username, password));

    // Create HTTP GET request with the SharePoint file URL
    HttpGet httpGet = new HttpGet(url);

    // Execute the request
    HttpResponse response = httpClient.execute(httpGet);

    // Retrieve the response entity as InputStream
    HttpEntity entity = response.getEntity();
    byte[] fileContent = EntityUtils.toByteArray(entity);

    // Save the file content to the output file path
    try (FileOutputStream outputStream = new FileOutputStream(outputFilePath)) {
        outputStream.write(fileContent);
    }
}
