3. Create a method to get file information.

```java
public static void getFileInfoFromSharePoint(String url, String username, String password) throws IOException {
    // Create HTTP client and set authentication credentials
    CloseableHttpClient httpClient = HttpClients.createDefault();
    httpClient.getCredentialsProvider().setCredentials(
            new AuthScope(AuthScope.ANY),
            new UsernamePasswordCredentials(username, password));

    // Create HTTP GET request with the SharePoint file URL appended with "/_api/web/GetFileByServerRelativeUrl"
    String apiEndpoint = url + "/_api/web/GetFileByServerRelativeUrl('" + url + "')?$expand=ListItemAllFields";
    HttpGet httpGet = new HttpGet(apiEndpoint);

    // Execute the request
    HttpResponse response = httpClient.execute(httpGet);

    // Retrieve the response entity as JSON
    String jsonResponse = EntityUtils.toString(response.getEntity());
    JSONObject fileInfoJson = new JSONObject(jsonResponse).getJSONObject("d");

    // Extract file information
    String fileName = fileInfoJson.getString("Name");
    String filePath = fileInfoJson.getString("ServerRelativeUrl");
    String fileCreatedBy = fileInfoJson.getJSONObject("ListItemAllFields").getString("AuthorId");
    String fileCreatedDate = fileInfoJson.getJSONObject("ListItemAllFields").getString("Created");
    String fileModifiedBy = fileInfoJson.getJSONObject("ListItemAllFields").getString("EditorId");
    String fileModifiedDate = fileInfoJson.getJSONObject("ListItemAllFields").getString("Modified");

    // Print file information
    System.out.println("File Name: " + fileName);
    System.out.println("File Path: " + filePath);
    System.out.println("File Created By: " + fileCreatedBy);
    System.out.println("File Created Date: " + fileCreatedDate);
    System.out.println("File Modified By: " + fileModifiedBy);
    System.out.println("File Modified Date: " + fileModifiedDate);
}
