```csharp
public class PopupQueue
{
    private PopupWrapper topPopup;
    private readonly Queue<PopupWrapper> popups = new Queue<PopupWrapper>();

    public void Add(PopupWrapper popup)
    {
        popups.Enqueue(popup);

        if (topPopup == null)
        {
            OpenNextPopup();
        }
    }

    private void OpenNextPopup()
    {
        if (popups.Count > 0)
        {
            topPopup = popups.Dequeue();
            topPopup.OnClose += CloseTopPopup;
            topPopup.OnCreate += OpenNextPopup;
            topPopup.Show();
        }
    }

    private void CloseTopPopup()
    {
        topPopup.OnClose -= CloseTopPopup;
        topPopup.OnCreate -= OpenNextPopup;
        topPopup.Close();
        topPopup = null;

        OpenNextPopup();
    }

    public void CloseAll()
    {
        if (topPopup != null)
        {
            topPopup.OnClose -= CloseTopPopup;
            topPopup.OnCreate -= OpenNextPopup;
            topPopup.Close();
            topPopup = null;
        }

        popups.Clear();
    }

    public void RemoveLast()
    {
        if (topPopup != null)
        {
            topPopup.OnClose -= CloseTopPopup;
            topPopup.OnCreate -= OpenNextPopup;
            topPopup.Close();
            topPopup = null;
        }

        if (popups.Count > 0)
        {
            popups.Dequeue();
        }

        OpenNextPopup();
    }
}
```

