Para listar todos os QR Codes lidos, você precisa fazer uma chamada GET para o endpoint `/qrcodes` da API. A classe `QRCodeResource` contém o método responsável por essa funcionalidade. 

Você pode usar uma biblioteca HTTP para fazer essa chamada GET para o endpoint. Você pode usar o pacote `axios` no seu projeto React Native. 

Aqui está um exemplo de como fazer isso no arquivo `App.js`:

```javascript
import React, { useState, useRef, useEffect } from 'react';
import { View, Text, TouchableOpacity, Linking } from 'react-native';
import { RNCamera } from 'react-native-camera';
import QRCodeScanner from 'react-native-qrcode-scanner';
import axios from 'axios';

const App = () => {
  const qrcodeRef = useRef(null);
  const [link, setLink] = useState('');
  const [qrcodes, setQrcodes] = useState([]);

  useEffect(() => {
    // Carrega os QR Codes lidos do backend quando o componente é montado
    loadQrcodes();
  }, []);

  const handleLink = () => {
    // Envia os dados escaneados para o backend se houver um link
    if (link) {
      axios
        .post('http://192.168.1.67:8080/qrcodes', { data: link })
        .then(response => {
          if (response.status === 201) {
            console.log('Dados enviados para o backend com sucesso');
            // Atualiza a lista de QR Codes após enviar os dados
            loadQrcodes();
          } else {
            console.log('Falha ao enviar os dados para o backend');
          }
        })
        .catch(error => {
          console.error('Erro ao enviar os dados para o backend:', error);
        });
    }

    // Limpa o link após o processamento
    setLink('');

    // Ativa novamente o scanner de QR Code
    qrcodeRef.current.reactivate();
  };

  const loadQrcodes = () => {
    axios
      .get('http://192.168.1.67:8080/qrcodes')
      .then(response => {
        setQrcodes(response.data);
      })
      .catch(error => {
        console.error('Erro ao carregar os QR Codes do backend:', error);
      });
  };

  return (
    <QRCodeScanner
      ref={qrcodeRef}
      onRead={({ data }) => setLink(data)} // Atualiza o estado do link quando um QR Code é lido
      flasMode={RNCamera.Constants.FlashMode.off}
      topContent={
        <View>
          <Text>{link}</Text>
        </View>
      }
      bottomContent={
        <View>
          <TouchableOpacity
            onPress={handleLink}
            style={{
              padding: 12,
              backgroundColor: '#0277BD',
              marginTop: 20
            }}
          >
            <Text style={{ color: '#FFFFFF' }}>Processar QR Code</Text>
          </TouchableOpacity>
          <Text>QR Codes lidos:</Text>
          {qrcodes.map((qrcode, index) => (
            <Text key={index}>{qrcode}</Text>
          ))}
        </View>
      }
    />
  );
};

export default App;
```

