Here's a possible solution to decrypting Alice's messages using C# code:

```csharp
using System;
using System.Text;

class Program
{
    static void Main(string[] args)
    {
        int N = int.Parse(Console.ReadLine());

        for (int i = 0; i < N; i++)
        {
            string encryptedMessage = Console.ReadLine();
            string decryptedMessage = DecryptMessage(encryptedMessage);

            Console.WriteLine(decryptedMessage);
            Console.WriteLine(IsMessageSecure(decryptedMessage) ? "Secure" : "Insecure");
        }
    }

    static string DecryptMessage(string encryptedMessage)
    {
        StringBuilder decryptedMessage = new StringBuilder();

        foreach (char c in encryptedMessage)
        {
            if (char.IsLetter(c))
            {
                if (char.IsUpper(c))
                {
                    decryptedMessage.Append((char)('Z' - (c - 'A')));
                }
                else
                {
                    decryptedMessage.Append((char)('z' - (c - 'a')));
                }
            }
            else
            {
                decryptedMessage.Append(c);
            }
        }

        return decryptedMessage.ToString();
    }

    static bool IsMessageSecure(string message)
    {
        int modifiedCharCount = 0;
        int totalCharCount = 0;

        foreach (char c in message)
        {
            if (!char.IsWhiteSpace(c) && c != '\n')
            {
                totalCharCount++;
                if (char.IsLetter(c))
                {
                    modifiedCharCount++;
                }
            }
        }

        return (modifiedCharCount * 1.0 / totalCharCount) >= 0.5;
    }
}
```

