    {
        double consumption = CalculateConsumption();
        if (consumption < 5.0)
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    public void FillUp(int mileage, double liters)
    {
        startKilometers = endKilometers;
        endKilometers = mileage;
        this.liters = liters;
    }
