        if (index == numbers.length) {
            // Base case: reached the end of the array
            return sum;
        }

        // Recursive case
        // Explore two possibilities:
        // 1. Add the current number to the sum and move to the next index
        int sum1 = findLargestSum(numbers, index + 1, sum + numbers[index]);

        // 2. Move to the next index without adding the current number to the sum
