import java.util.Arrays;

public class ConsecutiveIntegers {
    public static int minIntegersNeeded(int[] arr) {
        // Sort the array in ascending order
        Arrays.sort(arr);

        int minIntegers = 0;
        for (int i = 1; i < arr.length; i++) {
            // Check the difference between adjacent elements
            int diff = arr[i] - arr[i - 1];

            // If there is a gap, add the required number of integers to fill the gap
            if (diff > 1) {
                minIntegers += diff - 1;
            }
        }

        return minIntegers;
    }

    public static void main(String[] args) {
        int[] arr = {4, 2, 1, 6, 5};
        int minIntegers = minIntegersNeeded(arr);
        System.out.println("Minimum number of integers needed: " + minIntegers);
    }
}
