// Array of food-related emojis
var emojis = ["??", "??", "??", "??", "??"];

// Corresponding riddles
var riddles = [
  "I'm round and cheesy, a favorite of many!",
  "I'm wrapped in seaweed, perfect with soy!",
  "I'm juicy and meaty, a classic delight!",
  "I'm crispy and salty, a side for your bite!",
  "I'm long and savory, a street food delight!"
];

// Corresponding answers
var answers = ["Pizza", "Sushi", "Burger", "French fries", "Hotdog"];

var score = 0;
var currentIndex = 0;

// Function to display the emojis, riddle, and score
function displayRiddle() {
  var emojiElements = document.getElementsByClassName("emoji");
  var riddleElement = document.getElementById("riddle");
  var scoreElement = document.getElementById("score");

  for (var i = 0; i < emojiElements.length; i++) {
    emojiElements[i].textContent = emojis[i];
  }

  riddleElement.textContent = riddles[currentIndex];
  scoreElement.textContent = "Score: " + score;
}

// Function to check the guess against the answer
function checkGuess(guess) {
  if (guess.toLowerCase() === answers[currentIndex].toLowerCase()) {
    score++;
    alert("Correct! It's " + answers[currentIndex] + "!");
  } else {
    score--;
    alert("Wrong! The correct answer is " + answers[currentIndex] + ".");
  }

  currentIndex++;

  if (currentIndex >= riddles.length) {
    currentIndex = 0;
  }

  displayRiddle();
}

// Function to add event listeners to the emoji elements
function addEmojiEventListeners() {
  var emojiElements = document.getElementsByClassName("emoji");

  for (var i = 0; i < emojiElements.length; i++) {
    emojiElements[i].addEventListener("click", function() {
      var guess = this.textContent;
      checkGuess(guess);
    });
  }
}

// Initialize the game on page load
window.onload = function() {
  displayRiddle();
  addEmojiEventListeners();
};
