        static int ComputeMaximumTrinomial(int s)
        {
            int a = 1; // Start with the minimum possible value for a
            int d = s - 3*a; // Since a+b+c+d = s, we can calculate the minimum possible value for d

            int maximumValue = int.MinValue;

