            int[,] dp = new int[W, H]; // 2D array to store the shortest path lengths
            dp[0, 0] = map[0, 0];

            // Calculate the shortest path lengths
            for (int i = 0; i < W; i++)
            {
                for (int j = 0; j < H; j++)
                {
                    if (i == 0 && j != 0)
                    {
                        // Only move down
                        dp[i, j] = dp[i, j - 1] + map[i, j];
                    }
                    else if (i != 0 && j == 0)
                    {
                        // Only move right
                        dp[i, j] = dp[i - 1, j] + map[i, j];
                    }
                    else if (i != 0 && j != 0)
                    {
                        // Move either right or down, choose the minimum path length
                        dp[i, j] = Math.Min(dp[i - 1, j], dp[i, j - 1]) + map[i, j];
                    }
                }
            }

            return dp[W - 1, H - 1];
        }
    }
}
```

