```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <unordered_map>
#include <queue>

using namespace std;

// Structure to store gate information
struct Gate {
    vector<int> inputs;
    int delay;
};

// Function to compute the delay of every primary output in the circuit
unordered_map<char, int> computeOutputDelays(vector<Gate>& gates, unordered_map<char, int>& gateDelays) {
    unordered_map<char, int> outputDelays;
    unordered_map<char, int> inputCount; // Count of inputs for each gate

    // Compute input count for each gate
    for (auto& gate : gates) {
        for (int input : gate.inputs) {
            inputCount[input]++;
        }
    }

    // Queue to store gates with zero inputs (can be processed immediately)
    queue<char> readyGates;

    // Find gates with zero inputs and add them to the queue
    for (auto& gate : gates) {
        for (int input : gate.inputs) {
            if (inputCount[input] == 0) {
                readyGates.push(input);
            }
        }
    }

    // Process gates in topological order
    while (!readyGates.empty()) {
        char gateId = readyGates.front();
        readyGates.pop();

        // Compute the delay of the gate's output
        int outputDelay = gateDelays[gateId];
        for (auto& gate : gates) {
            if (find(gate.inputs.begin(), gate.inputs.end(), gateId) != gate.inputs.end()) {
                outputDelay = max(outputDelay, outputDelays[gateId] + gate.delay);
            }
        }

        // Update the delay of the gate's output and decrease input count of each dependent gate
        outputDelays[gateId] = outputDelay;

        for (auto& gate : gates) {
            if (find(gate.inputs.begin(), gate.inputs.end(), gateId) != gate.inputs.end()) {
                inputCount[gate.inputs[0]]--;
                if (inputCount[gate.inputs[0]] == 0) {
                    readyGates.push(gate.inputs[0]);
                }
            }
        }
    }

    return outputDelays;
}

int main() {
    string circuitFile = "circuit.txt";
    string gateDelayFile = "gate_delays.txt";
    string outputDelayFile = "output_delays.txt";

    // Read circuit file
    ifstream circuitInput(circuitFile);
    vector<Gate> gates;
    unordered_map<char, int> outputDelays;

    char gateId;
    int numInputs;
    while (circuitInput >> gateId >> numInputs) {
        Gate gate;
        gate.inputs.resize(numInputs);
        for (int i = 0; i < numInputs; i++) {
            circuitInput >> gate.inputs[i];
        }
        gates.push_back(gate);
        // Initialize output delays with 0
        outputDelays[gateId] = 0;
    }
    circuitInput.close();

    // Read gate delay file
    ifstream gateDelayInput(gateDelayFile);
    unordered_map<char, int> gateDelays;

    while (gateDelayInput >> gateId) {
        int delay;
        gateDelayInput >> delay;
        gateDelays[gateId] = delay;
    }
    gateDelayInput.close();

    // Compute output delays
    outputDelays = computeOutputDelays(gates, gateDelays);

    // Write output delay file
    ofstream outputDelayOutput(outputDelayFile);
    for (auto& outputDelay : outputDelays) {
        outputDelayOutput << outputDelay.first << " " << outputDelay.second << endl;
    }
    outputDelayOutput.close();

    cout << "Output delays successfully computed and written to " << outputDelayFile << endl;

    return 0;
}
```

