    char gateId;
    int numInputs;
    while (circuitInput >> gateId >> numInputs) {
        Gate gate;
        gate.inputs.resize(numInputs);
        for (int i = 0; i < numInputs; i++) {
            circuitInput >> gate.inputs[i];
        }
        gates.push_back(gate);
        outputDelays[gateId] = 0;
    }
    circuitInput.close();

    ifstream gateDelayInput(gateDelayFile);
    unordered_map<char, int> gateDelays;

