```csharp
private void DrawLineOnPictureBox(int startX, int startY, double angle, int length)
{
    // Создаем новый Bitmap для pictureBox3
    Bitmap bitmap = new Bitmap(pictureBox3.Width, pictureBox3.Height);

    // Создаем объект Graphics из Bitmap
    using (Graphics g = Graphics.FromImage(bitmap))
    {
        // Преобразуем угол в радианы
        double radians = angle * Math.PI / 180.0;

        // Вычисляем значения смещения по x и y на основе длины и угла
        int offsetX = (int)(length * Math.Cos(radians));
        int offsetY = (int)(length * Math.Sin(radians));

        // Рисуем линию от startX, startY до x, y
        g.DrawLine(Pens.Black, startX, startY, startX + offsetX, startY + offsetY);
    }

    // Устанавливаем полученный Bitmap в качестве изображения для pictureBox3
    pictureBox3.Image = bitmap;
}
```

