```csharp
using System;

public interface ITestpaper
{
    string Subject { get; }
    string[] MarkScheme { get; }
    string PassMark { get; }
}

public interface IStudent
{
    string[] TestsTaken { get; }
    void TakeTest(ITestpaper paper, string[] answers);
}

public class Testpaper : ITestpaper
{
    public string Subject { get; }
    public string[] MarkScheme { get; }
    public string PassMark { get; }

    public Testpaper(string subject, string[] markScheme, string passMark)
    {
        Subject = subject;
        MarkScheme = markScheme;
        PassMark = passMark;
    }
}

public class Student : IStudent
{
    private string[] testsTaken;

    public string[] TestsTaken
    {
        get { return testsTaken.Length == 0 ? new string[] { "No tests taken" } : testsTaken; }
    }

    public void TakeTest(ITestpaper paper, string[] answers)
    {
        int totalQuestions = paper.MarkScheme.Length;
        int correctAnswers = 0;

        for (int i = 0; i < totalQuestions; i++)
        {
            if (answers[i] == paper.MarkScheme[i])
            {
                correctAnswers++;
            }
        }

        double percentage = (double)correctAnswers / totalQuestions * 100;
        string result = percentage >= double.Parse(paper.PassMark.Trim('%')) ? "Passed" : "Failed";
        string testName = paper.Subject;

        Array.Resize(ref testsTaken, testsTaken.Length + 1);
        testsTaken[testsTaken.Length - 1] = $"{testName}: {result}! ({percentage.ToString("F0")}%)";
    }
}

class Program
{
    static void Main(string[] args)
    {
        Testpaper paper1 = new Testpaper("Maths", new string[] { "1A", "2C", "3D", "4A", "5A" }, "60%");
        Testpaper paper2 = new Testpaper("Chemistry", new string[] { "1C", "2C", "3D", "4A" }, "75%");
        Testpaper paper3 = new Testpaper("Computing", new string[] { "1D", "2C", "3C", "4B", "5D", "6C", "7A" }, "75%");

        Student student1 = new Student();
        Student student2 = new Student();

        Console.WriteLine(string.Join(", ", student1.TestsTaken));
        student1.TakeTest(paper1, new string[] { "1A", "2D", "3D", "4A", "5A" });
        Console.WriteLine(string.Join(", ", student1.TestsTaken));

        student2.TakeTest(paper2, new string[] { "1C", "2D", "3A", "4C" });
        student2.TakeTest(paper3, new string[] { "1A", "2C", "3A", "4C", "5D", "6C", "7B" });
        Console.WriteLine(string.Join(", ", student2.TestsTaken));
    }
}
```

This code defines two classes: `Testpaper` and `Student`. 

The `Testpaper` class implements the `ITestpaper` interface and has properties for subject, mark scheme, and pass mark. It also has a constructor that takes the subject, mark scheme, and pass mark as parameters.

The `Student` class implements the `IStudent` interface and has a property for tests taken and a method to take a test. The `TakeTest` method calculates the percentage of correct answers and determines if the student passed the test based on the pass mark. It then updates the `testsTaken` array with the test name, result, and percentage. If no tests have been taken, the `TestsTaken` property returns "No tests taken".

In the `Main` method, test papers and students are created. The `TestsTaken` property of each student is printed before and after taking tests. The output will be displayed in the console.

