  const eyeIcon = document.querySelector('.fa-eye');
  const eyeSlashIcon = document.querySelector('.fa-eye-slash');
  const input = document.querySelector('.input-copy-text');

  eyeIcon.classList.toggle('hide');
  eyeSlashIcon.classList.toggle('hide');

