using System;
using System.Management;

public class Program
{
    public static void Main(string[] args)
    {
        ManagementObjectSearcher searcher = new ManagementObjectSearcher("root\\CIMV2", "SELECT * FROM Win32_DesktopMonitor");

        foreach (ManagementObject queryObj in searcher.Get())
        {
            string monitorName = queryObj["Name"].ToString();
            string monitorSize = queryObj["ScreenWidth"].ToString() + "x" + queryObj["ScreenHeight"].ToString();

            Console.WriteLine("Monitor Name: " + monitorName);
            Console.WriteLine("Monitor Size: " + monitorSize);
        }

        Console.ReadKey();
    }
}
```

This code uses `ManagementObjectSearcher` to query the `Win32_DesktopMonitor` class in the WMI namespace `root\\CIMV2`. It retrieves the name and screen resolution properties of each monitor and prints them to the console.

