using System;
using System.Collections.Generic;

public interface ITestpaper
{
    string Subject { get; set; }
    string[] MarkScheme { get; set; }
    string PassMark { get; set; }
}

public interface IStudent
{
    string[] TestsTaken { get; set; }
    void TakeTest(ITestpaper paper, string[] answers);
}

public class Testpaper : ITestpaper
{
    public string Subject { get; set; }
    public string[] MarkScheme { get; set; }
    public string PassMark { get; set; }

    public Testpaper(string subject, string[] markScheme, string passMark)
    {
        Subject = subject;
        MarkScheme = markScheme;
        PassMark = passMark;
    }
}

public class Student : IStudent
{
    public string[] TestsTaken { get; set; }

    public Student()
    {
        TestsTaken = new string[] { "No tests taken" };
    }

    public void TakeTest(ITestpaper paper, string[] answers)
    {
        int totalQuestions = paper.MarkScheme.Length;
        int correctAnswers = 0;

        for (int i = 0; i < totalQuestions; i++)
        {
            if (answers[i] == paper.MarkScheme[i])
            {
                correctAnswers++;
            }
        }

        double percentage = (double)correctAnswers / totalQuestions * 100;
        string result = percentage >= double.Parse(paper.PassMark) ? "Passed" : "Failed";

        string testResult = $"{paper.Subject}: {result}! ({percentage}%)";

        if (TestsTaken[0] == "No tests taken")
        {
            TestsTaken[0] = testResult;
        }
        else
        {
            List<string> takenTestsList = new List<string>(TestsTaken);
            takenTestsList.Add(testResult);
            TestsTaken = takenTestsList.ToArray();
        }
    }
}

