public class BankAccount
{
    private string name;
    private decimal balance;

    public BankAccount(string name, decimal balance)
    {
        this.name = name;
        this.balance = balance;
    }

    public string ShowUserNameAndBalance()
    {
        return name + ", " + FormatCurrency(balance);
    }

    private string FormatCurrency(decimal amount)
    {
        string formattedAmount = string.Format("{0:C}", amount);
        if (amount < 0)
        {
            // Remove the negative sign and add it before the dollar sign
            formattedAmount = formattedAmount.Replace("-", "-$");
        }
        else
        {
            // Add the dollar sign
            formattedAmount = "$" + formattedAmount;
        }

        // Add the two-digit cents if not present
        if (!formattedAmount.Contains("."))
        {
            formattedAmount += ".00";
        }

        return formattedAmount;
    }
}
```

