```go
package main

import (
	"context"
	"fmt"
	"log"
	"strings"
	"time"

	"github.com/chromedp/chromedp"
)

func main() {
	endpoints := []string{"https://shitflare.asia/?pagee=1", "https://shitflare.asia/?pagee=2", "https://shitflare.asia/?pagee=3"}
	for _, endpoint := range endpoints {
		fmt.Printf("Opening page: %s\n", endpoint)
		if err := openWebPage(endpoint); err != nil {
			log.Fatal(err)
		}
		time.Sleep(2 * time.Second) // Wait for some time before opening the next page
	}
}

func openWebPage(endpoint string) error {
	ctx, cancel := chromedp.NewContext(context.Background())
	defer cancel()

	// Create a buffer to capture a screenshot
	var buf []byte
	options := append(chromedp.DefaultExecAllocatorOptions[:],
		chromedp.Flag("headless", false), // Run in visible mode
		chromedp.Flag("disable-gpu", true),
		chromedp.Flag("mute-audio", true),
		chromedp.WindowSize(1920, 1080), // Set a custom window size if needed
	)

	allocatorContext, cancelAllocator := chromedp.NewExecAllocator(context.Background(), options...)
	defer cancelAllocator()
	ctx, cancel = chromedp.NewContext(allocatorContext)
	defer cancel()

	// Open the webpage and capture a screenshot
	if err := chromedp.Run(ctx,
		chromedp.Navigate(endpoint),
		chromedp.CaptureScreenshot(&buf),
	); err != nil {
		return err
	}

	// Save the captured screenshot to a file (optional)
	filename := strings.ReplaceAll(endpoint, "https://", "")
	filename = strings.ReplaceAll(filename, "http://", "")
	filename = strings.ReplaceAll(filename, "/", "_") + ".png"
	if err := saveScreenshotToFile(buf, filename); err != nil {
		return err
	}

	fmt.Printf("Screenshot saved to: %s\n", filename)
	return nil
}

func saveScreenshotToFile(buf []byte, filename string) error {
	return chromedp.SaveScreenshot(filename, buf)
}
```

