```javascript
module.exports = {
  devServer: {
    proxy: {
      '/api': {
        target: 'http://localhost:5000',
        changeOrigin: true
      },
      '/foo': {
        target: 'http://localhost:8080',
        changeOrigin: true
      }
    }
  }
}
