#include <stdio.h>

int countStrings(wchar_t** array) {
    int count = 0;
    wchar_t** ptr = array;

    while (*ptr != NULL) {
        count++;
        ptr++;
    }

    return count;
}

int main() {
    // Example array of wchar_t*
    wchar_t* strings[] = {
        L"Hello",
        L"World",
        L"!",
        NULL
    };

    int numOfStrings = countStrings(strings);
    printf("Number of strings: %d\n", numOfStrings);

    return 0;
}
```

In this example, the `countStrings` function takes a `wchar_t**` array as an argument and iterates through it using a pointer. It checks if the value pointed to by the pointer is `NULL`, incrementing the count if not, and moving the pointer to the next index. Finally, it returns the count of strings found.

