Yes, you can use events to pass or return the newly created object from the second frame to the first frame. Here's an example of how you can achieve this using wxWidgets in C++:

First, define a custom event class to handle the communication between frames. This class will contain the newly created object as a member variable.

```cpp
// Custom event class
class NewObjectEvent : public wxEvent
{
public:
    NewObjectEvent(wxEventType eventType = wxEVT_NULL, int id = 0)
        : wxEvent(id, eventType) {}

    // Setter and getter for the newly created object
    void SetNewObject(Object* newObj) { m_newObject = newObj; }
    Object* GetNewObject() const { return m_newObject; }

    // Required for copying the event object
    wxEvent* Clone() const override { return new NewObjectEvent(*this); }

private:
    Object* m_newObject; // Newly created object
};
```

Next, in your second frame class, when a new object is created, create an instance of the custom event and set the newly created object.

```cpp
// Second frame class
class SecondFrame : public wxFrame
{
public:
    SecondFrame(wxFrame* parent, const wxString& title)
        : wxFrame(parent, wxID_ANY, title) {}

    void OnObjectCreated()
    {
        // Create a new object
        Object* newObj = new Object();

        // Create a custom event and set the newly created object
        NewObjectEvent event(wxEVT_NEW_OBJECT);
        event.SetNewObject(newObj);

        // Post the event to the parent frame
        wxPostEvent(GetParent(), event);

        // Close the second frame or perform other actions
        Close();
    }
};
```

Finally, in the first frame class, connect the event handler and implement the event handling function to retrieve the newly created object and add it to the vector.

```cpp
// First frame class
class FirstFrame : public wxFrame
{
public:
    FirstFrame(const wxString& title)
        : wxFrame(nullptr, wxID_ANY, title)
    {
        // Connect the event handler to the custom event
        Bind(wxEVT_NEW_OBJECT, &FirstFrame::OnNewObject, this);
    }

    void OnNewObject(NewObjectEvent& event)
