	ssh.Handle(handleSSHRequest)

	err := ssh.ListenAndServe(":"+port, nil,
		ssh.PasswordAuth(func(ctx ssh.Context, password string) bool {
			username := ctx.User()
			if storedPassword, exists := users[username]; exists {
				return password == storedPassword
			}
			return false
		}),
	)

	if err != nil {
		log.Fatalf("Failed to start SSH server: %v", err)
	}

	fmt.Println("SSH server started on port", port)
}

func handleSSHRequest(session ssh.Session) {
	fmt.Fprintln(session, "Welcome to the SSH app!")
	for {
		input, err := readInput(session)
		if err != nil {
			log.Printf("Failed to read input: %v", err)
			session.Exit(1)
			return
		}

		command, params := parseInput(input)
		switch command {
		case "function1":
			function1(session, params)
		case "function2":
			function2(session, params)
		default:
			fmt.Fprintf(session, "Unknown command: %s\n", command)
		}
	}
}

func readInput(session ssh.Session) (string, error) {
	fmt.Fprint(session, "$ ")
	input, err := session.ReadCommand()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(input), nil
}

func parseInput(input string) (string, string) {
	parts := strings.SplitN(input, " ", 2)
	command := parts[0]
	params := ""
	if len(parts) > 1 {
		params = parts[1]
	}
	return command, params
}

func function1(session ssh.Session, params string) {
	fmt.Fprintf(session, "Running function1 with params: %s\n", params)
	// Add your function1 logic here
}

func function2(session ssh.Session, params string) {
	fmt.Fprintf(session, "Running function2 with params: %s\n", params)
	// Add your function2 logic here
}
