func (s *session) handleChannel(newChannel ssh.NewChannel) {
	channel, _, err := newChannel.Accept()
	if err != nil {
		fmt.Println("Failed to accept channel:", err)
		return
	}

	io.WriteString(channel, fmt.Sprintf("Welcome, %s, to \"cartel\"!\n", s.username))
	io.WriteString(channel, fmt.Sprintf("[%s@cartel]~$ ", s.username))

