// that allows reading from and writing to the SSH session
type envStdin struct{}

func (envStdin) Read(data []byte) (int, error) {
	return envStdin{}.File.Read(data)
}

func (envStdin) Fd() uintptr {
	return 0 // Stdin file descriptor
}

func (envStdin) Close() error {
	return nil
}

func (envStdin) Write(data []byte) (int, error) {
	return 0, fmt.Errorf("not supported")
}

func (envStdoutErr) Write(data []byte) (int, error) {
	return envStdoutErr{}.File.Write(data)
}

type envStdoutErr struct{}

func (envStdoutErr) Read(data []byte) (int, error) {
	return 0, fmt.Errorf("not supported")
}

func (envStdoutErr) Fd() uintptr {
	return 1 // Stdout file descriptor
}

func (envStdoutErr) Close() error {
	return nil
}
