    if (fcntl(sockfd, F_SETFL, O_NONBLOCK) < 0)
        err_sys("fcntl error");

    bzero(&servaddr, sizeof servaddr);
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
