            err_sys("getsockopt error");

        if (error != 0)
            err_quit("connect error");

        // Socket is now connected, set it back to blocking mode
        if (fcntl(sockfd, F_SETFL, 0) < 0)
            err_sys("fcntl error");
    }
    else
    {
        err_quit("select timeout");
    }

    while ((n = read(sockfd, recvline, MAXLINE)) > 0)
    {
        recvline[n] = '\0';
        if (fputs(recvline, stdout) == EOF)
            err_sys("fputs error");
    }

    if (n < 0)
        err_sys("read error");

    exit(0);
}
