import io.sentry.spring.tracing.SentryTracer;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class TimingAspect {

    private final SentryTracer sentryTracer;

    public TimingAspect(SentryTracer sentryTracer) {
        this.sentryTracer = sentryTracer;
    }

    @Around("@annotation(org.springframework.web.bind.annotation.RequestMapping)")
    public Object around(ProceedingJoinPoint pjp) throws Throwable {
        // Создаем Sentry транзакцию
        SentrySpan span = sentryTracer
                .startChildSpan(pjp.getSignature().getDeclaringTypeName() + "." + pjp.getSignature().getName());

        try {
            // Запускаем метод контроллера
            return pjp.proceed();
        } finally {
            // Завершаем транзакцию и отправляем ее в Sentry
            span.finish();
        }
    }
}
```

