```java
import io.sentry.Sentry;
import io.sentry.SentryEnvelope;
import io.sentry.SpanStatus;
import io.sentry.protocol.SentryId;
import io.sentry.protocol.SentryTransaction;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Pointcut;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class TimingAspect {

    @Pointcut("@annotation(org.springframework.web.bind.annotation.RequestMapping) || " +
            "@annotation(org.springframework.web.bind.annotation.GetMapping) || " +
            "@annotation(org.springframework.web.bind.annotation.PostMapping) || " +
            "@annotation(org.springframework.web.bind.annotation.PutMapping) || " +
            "@annotation(org.springframework.web.bind.annotation.PatchMapping) || " +
            "@annotation(org.springframework.web.bind.annotation.DeleteMapping)")
    public void controllerMethods() {}

    @Around(value = "controllerMethods()")
    public Object profile(ProceedingJoinPoint pjp) throws Throwable {
        SentryEnvelope envelope = Sentry.getCurrentHub().getEnvelope();
        SentryTransaction transaction = SentryEnvelopeUtil.getOrCreateTransaction(envelope);

        try {
            transaction.setTransaction(pjp.getSignature().getName());
            return pjp.proceed();
        } catch (Exception e) {
            transaction.setStatus(SpanStatus.INTERNAL_ERROR);
            Sentry.captureException(e);
            throw e;
        } finally {
            transaction.finish();
            Sentry.captureEnvelope(envelope);
        }
    }
}
```

