To create a simple SSH app using the `github.com/gliderlabs/ssh` and `io` libraries, follow the steps below.

1. Install the required packages:
   ```
   go get github.com/gliderlabs/ssh
   go get golang.org/x/crypto/ssh
   ```

2. Create a new Go file (e.g., `main.go`) and import the necessary packages:
   ```go
   package main

   import (
   	"fmt"
   	"io"
   	"io/ioutil"

   	"github.com/gliderlabs/ssh"
   	"golang.org/x/crypto/ssh/terminal"
   )
   ```

3. Define a struct to store the valid username-password combinations:
   ```go
   type UserCredentials struct {
   	Username string
   	Password string
   }
   ```

4. Create a function to validate the provided username and password:
   ```go
   func isValidCredentials(username, password string) bool {
   	// Define valid username-password combinations
   	validCredentials := []UserCredentials{
   		{"user1", "pass1"},
   		{"user2", "pass2"},
   	}

   	// Check if the provided credentials match
   	for _, credentials := range validCredentials {
   		if credentials.Username == username && credentials.Password == password {
   			return true
   		}
   	}

   	return false
   }
   ```

5. Create a function to handle the SSH session:
   ```go
   func handleSession(s ssh.Session) {
   	// Disable terminal modes
   	term := terminal.NewTerminal(s, "> ")
   	term.Write([]byte("Welcome to the SSH Cartel App!\n\n"))

   	// Read username and password
   	term.Write([]byte("Username: "))
   	username, _ := term.ReadLine()

   	term.Write([]byte("Password: "))
   	password, _ := term.ReadPassword(0) // 0 means it won't show the entered characters

   	term.Write([]byte("\n"))

   	// Validate credentials
   	if isValidCredentials(username, string(password)) {
   		// Send greeting message with colored username
   		greeting := fmt.Sprintf("Welcome \033[1;35m%s\033[0m to the cartel.\n", username)
   		term.Write([]byte(greeting))
   	} else {
   		term.Write([]byte("Invalid username or password.\n"))
   	}

   	// Close the SSH session
   	s.Close()
   }
   ```

6. Create the main function and configure the SSH server:
   ```go
   func main() {
   	// Configure SSH server
   	ssh.Handle(func(s ssh.Session) {
   		handleSession(s)
   	})

   	// Read private key
   	privateBytes, _ := ioutil.ReadFile("path_to_private_key")
   	private, _ := ssh.ParsePrivateKey(privateBytes)

   	// Configure SSH server options
   	sshConfig := &ssh.ServerConfig{
   		NoClientAuth: true,
   	}
   	sshConfig.AddHostKey(private)

   	// Start the SSH server
