                fileData, err := ioutil.ReadFile(filename)
                if err != nil {
                    term.Write([]byte(fmt.Sprintf("Failed to read file: %s\n", err)))
                } else {
                    // Write the file data and preserve ANSI escape sequences
                    writeWithANSI(term, string(fileData))
                }
            // ...
            }
        }
    // ...
    }
}

func writeWithANSI(term *terminal.Terminal, data string) {
    var coloredData string

    // Parse ANSI escape sequences and apply them to the data
    for i := 0; i < len(data); i++ {
        if data[i] == '\x1b' {
            for j := i + 1; j < len(data); j++ {
                if data[j] == 'm' {
                    term.Write([]byte(coloredData))
                    coloredData = ""
                    i = j
                    break
                } else {
                    coloredData += string(data[j])
                }
            }
        } else {
            coloredData += string(data[i])
        }
    }

    term.Write([]byte(coloredData))
}
