  }

  public static string ResizeString(string input) {
    int length = input.Length;

    // Divide the total length by 2 and round up if it is an odd number
    int resizedLength = (int)Math.Ceiling(length / 2.0);

    // Count the number of each character type in the input string
    int countU = 0;
    int countC = 0;
    foreach (char c in input) {
      if (c == 'u' || c == 'U') {
        countU++;
      } else if (c == 'c' || c == 'C') {
        countC++;
      }
    }

    // Divide the count of each character type by the total count and multiply by the resized length
    int resizedCountU = (int)Math.Ceiling((double)countU / length * resizedLength);
    int resizedCountC = (int)Math.Ceiling((double)countC / length * resizedLength);

    // Construct the resized string with the calculated counts of each character type
    string resizedString = new string('u', resizedCountU) + new string('c', resizedCountC);

    return resizedString;
  }
}
