        Apply360Limit(ref rotationAmount);

        // Apply rotation to the quaternion
        rotation *= Quaternion.Euler(0, rotationAmount, 0);

        // Apply the quaternion rotation to gameObject's transform
        transform.rotation = rotation;
    }

    private void Apply360Limit(ref float rotationAmount)
    {
        // Calculate the current rotation in euler angles
        Vector3 eulerRotation = rotation.eulerAngles;

        // Calculate the final rotation amount by adding the input
        float finalRotation = eulerRotation.y + rotationAmount;

        if (finalRotation >= 360.0f)
        {
            // If the final rotation exceeds 360 degrees, subtract 360 to wrap it around
            finalRotation -= 360.0f;
        }
        else if (finalRotation < 0.0f)
        {
            // If the final rotation is less than 0 degrees, add 360 to wrap it around
            finalRotation += 360.0f;
        }

        // Calculate the final rotation amount by subtracting the original rotation
        rotationAmount = finalRotation - eulerRotation.y;
    }
}
```

This code demonstrates how to limit the rotation to 360 degrees around the y-axis. It uses the `Apply360Limit` method to calculate the final rotation amount and wraps it around if it exceeds 360 degrees or is less than 0 degrees. The resulting rotation is applied to the `transform.rotation` property of the game object.

