private var isLinesInitialized = false // Flag to check if lines array has been initialized

func lineIndexAtPosition(_ position: Int) -> Int {
    initializeLinesIfNeeded() // Lazily initialize the lines array if needed

    guard let lines = lines else {
        NSLog("ERROR! Line array not initialized")
        return 0
    }

    // Binary search to find the line at the given position
    var low = 0
    var high = lines.count - 1

    while low <= high {
        let mid = (low + high) / 2
        let line = lines[mid]

        if position >= line.range.lowerBound && position <= line.range.upperBound {
            return mid
        } else if position < line.range.lowerBound {
            high = mid - 1
        } else {
            low = mid + 1
        }
    }

    NSLog("ERROR! Line not found")
    return 0
}

