Here is an example of how to draw a rounded rectangle in C# using the `System.Drawing` namespace:

```csharp
using System;
using System.Drawing;
using System.Windows.Forms;

namespace DrawRoundRectExample
{
    public class MainForm : Form
    {
        public MainForm()
        {
            // Set the size and title of the form
            ClientSize = new Size(400, 300);
            Text = "Draw RoundRect Example";
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);

            Graphics g = e.Graphics;
            Pen pen = new Pen(Color.Black, 2); // Set the color and thickness of the pen

            int x = 50; // X position of the top-left corner of the rectangle
            int y = 50; // Y position of the top-left corner of the rectangle
            int width = 300; // Width of the rectangle
            int height = 200; // Height of the rectangle
            int cornerRadius = 20; // Radius of the rounded corners

            // Draw the rounded rectangle
            g.DrawArc(pen, x, y, cornerRadius, cornerRadius, 180, 90); // Top-left corner
            g.DrawLine(pen, x + cornerRadius / 2, y, x + width - cornerRadius / 2, y); // Top edge
            g.DrawArc(pen, x + width - cornerRadius, y, cornerRadius, cornerRadius, 270, 90); // Top-right corner
            g.DrawLine(pen, x + width, y + cornerRadius / 2, x + width, y + height - cornerRadius / 2); // Right edge
            g.DrawArc(pen, x + width - cornerRadius, y + height - cornerRadius, cornerRadius, cornerRadius, 0, 90); // Bottom-right corner
            g.DrawLine(pen, x + cornerRadius / 2, y + height, x + width - cornerRadius / 2, y + height); // Bottom edge
            g.DrawArc(pen, x, y + height - cornerRadius, cornerRadius, cornerRadius, 90, 90); // Bottom-left corner
            g.DrawLine(pen, x, y + cornerRadius / 2, x, y + height - cornerRadius / 2); // Left edge
        }

        public static void Main()
        {
            Application.Run(new MainForm());
        }
    }
}
```

This code creates a `MainForm` class derived from `Form`. It overrides the `OnPaint` method to draw the rounded rectangle using a `Graphics` object and a `Pen` with a specified color and thickness. The position, width, height, and corner radius of the rounded rectangle are defined, and the rounded rectangle is drawn using a combination of `DrawArc` and `DrawLine` methods. Finally, `Main` method starts the application and displays the form.

