To connect controls with lines in C#, you can make use of the `Graphics` class to draw lines between their positions on a `PictureBox` or a custom control's `OnPaint` event.

Here's an example that demonstrates how to connect two controls with a line:

```csharp
using System;
using System.Drawing;
using System.Windows.Forms;

namespace ConnectControlsExample
{
    public class MainForm : Form
    {
        private Control control1;
        private Control control2;

        public MainForm()
        {
            // Create two controls
            control1 = new Button()
            {
                Location = new Point(50, 50),
                Size = new Size(100, 30),
                Text = "Control 1"
            };

            control2 = new Button()
            {
                Location = new Point(200, 150),
                Size = new Size(100, 30),
                Text = "Control 2"
            };

            // Add controls to form
            Controls.Add(control1);
            Controls.Add(control2);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);

            // Create a Graphics object
            Graphics g = e.Graphics;

            // Set the pen to draw the line
            Pen pen = new Pen(Color.Black, 2);

            // Determine the start and end points of the line
            Point startPoint = new Point(control1.Location.X + control1.Width / 2, control1.Location.Y + control1.Height / 2);
            Point endPoint = new Point(control2.Location.X + control2.Width / 2, control2.Location.Y + control2.Height / 2);

            // Draw the line connecting the controls
            g.DrawLine(pen, startPoint, endPoint);
        }

        public static void Main()
        {
            Application.Run(new MainForm());
        }
    }
}
```

In this example, two Button controls (`control1` and `control2`) are created and positioned on the form. The `OnPaint` method is overridden to draw a line between the two controls using the `Graphics.DrawLine` method. The start and end points of the line are determined by the center points of the controls. Finally, the `Main` method starts the application and displays the form.

To dynamically adjust the position of controls and connect them with lines as their position changes in C#, you can handle the `LocationChanged` event of the controls. 

Here is an example of how you can achieve this:

```csharp
using System;
using System.Drawing;
using System.Windows.Forms;

namespace DynamicControlPositionExample
{
    public class MainForm : Form
    {
        private Control control1;
        private Control control2;
        private bool areControlsConnected;

        public MainForm()
        {
            // Create two controls
            control1 = new Button()
            {
                Location = new Point(50, 50),
                Size = new Size(100, 30),
                Text = "Control 1"
            };

            control2 = new Button()
            {
                Location = new Point(200, 150),
                Size = new Size(100, 30),
                Text = "Control 2"
            };

            // Add controls to form
            Controls.Add(control1);
            Controls.Add(control2);

            // Add event handlers for the LocationChanged event of the controls
            control1.LocationChanged += Control_LocationChanged;
            control2.LocationChanged += Control_LocationChanged;
        }

        private void Control_LocationChanged(object sender, EventArgs e)
        {
            if (areControlsConnected)
            {
                // Refresh the form to trigger the OnPaint event
                Refresh();
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);

            // Create a Graphics object
            Graphics g = e.Graphics;

            // Set the pen to draw the line
            Pen pen = new Pen(Color.Black, 2);

            // Determine the start and end points of the line
            Point startPoint = new Point(control1.Location.X + control1.Width / 2, control1.Location.Y + control1.Height / 2);
            Point endPoint = new Point(control2.Location.X + control2.Width / 2, control2.Location.Y + control2.Height / 2);

            // Draw the line connecting the controls
            g.DrawLine(pen, startPoint, endPoint);
        }

        public static void Main()
        {
            Application.Run(new MainForm());
        }
    }
}
```

In this example, the `LocationChanged` event is handled for both controls. When the location of either control changes, the `Control_LocationChanged` event handler is triggered. In the event handler, if the controls are connected, the form is refreshed to trigger the `OnPaint` event and update the line connecting the controls.

The `OnPaint` event is overridden to draw the line connecting the controls using the `Graphics.DrawLine` method. The start and end points of the line are determined by the center points of the controls.

Finally, the `Main` method starts the application and displays the form.

To connect two nodes in a flowchart in C#, you can create a custom control that represents the nodes and then draw lines between those nodes using the `Graphics` class. Here's an example that demonstrates this:

```csharp
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;

namespace ConnectFlowchartNodesExample
{
    public class FlowchartNode
    {
        public Point Location { get; set; }
        public Size Size { get; set; }
        public string Text { get; set; }
    }

    public class FlowchartControl : Control
    {
        private List<FlowchartNode> nodes;
        private Pen linePen;

        public FlowchartControl()
        {
            nodes = new List<FlowchartNode>();
            linePen = new Pen(Color.Black, 2);
        }

        public void AddNode(FlowchartNode node)
        {
            nodes.Add(node);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);

            Graphics g = e.Graphics;

            foreach (FlowchartNode node in nodes)
            {
                // Draw the node as a rectangle
                g.DrawRectangle(linePen, node.Location.X, node.Location.Y, node.Size.Width, node.Size.Height);

                // Draw lines connecting the nodes
                foreach (FlowchartNode connectedNode in nodes)
                {
                    if (connectedNode != node)
                    {
                        Point startPoint = new Point(node.Location.X + node.Size.Width, node.Location.Y + node.Size.Height / 2);
                        Point endPoint = new Point(connectedNode.Location.X, connectedNode.Location.Y + connectedNode.Size.Height / 2);

                        g.DrawLine(linePen, startPoint, endPoint);
                    }
                }
            }
        }
    }

    public class MainForm : Form
    {
        private FlowchartControl flowchartControl;

        public MainForm()
        {
            flowchartControl = new FlowchartControl();
            Controls.Add(flowchartControl);

            // Create two flowchart nodes
            FlowchartNode node1 = new FlowchartNode()
            {
                Location = new Point(50, 50),
                Size = new Size(100, 50),
                Text = "Node 1"
            };
            flowchartControl.AddNode(node1);

            FlowchartNode node2 = new FlowchartNode()
            {
                Location = new Point(200, 150),
                Size = new Size(100, 50),
                Text = "Node 2"
            };
            flowchartControl.AddNode(node2);
        }

        protected override void OnSizeChanged(EventArgs e)
        {
            base.OnSizeChanged(e);

            // Resize the flowchart control to fill the form
            flowchartControl.Size = ClientSize;
        }

        public static void Main()
        {
            Application.Run(new MainForm());
        }
    }
}
```

In this example, the `FlowchartNode` class represents a single node in the flowchart. The `FlowchartControl` class is a custom control that serves as the container for the flowchart nodes. It provides methods to add nodes and handles the painting of nodes and lines. The `MainForm` class is derived from the `Form` class and contains the `FlowchartControl` instance.

When the form is resized, the `OnSizeChanged` method is overridden to resize the flowchart control to fill the form.

Run the application to see how the nodes are connected by lines. You can add more nodes by calling the `AddNode` method on the `FlowchartControl` instance.

