    @Value("${sentry.dsn}")
    private String dsn;

    @Bean
    public HandlerInterceptor sentryPerformanceInterceptor() {
        return new SentryPerformanceInterceptor();
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(sentryPerformanceInterceptor());
    }

    @Bean
    public SentryExceptionResolver sentryExceptionResolver() {
        return new SentryExceptionResolver();
    }

    @Override
    public void configureHandlerExceptionResolvers(List<HandlerExceptionResolver> resolvers) {
        resolvers.add(sentryExceptionResolver());
    }

    @PostConstruct
    public void init() {
        Sentry.init(dsn);
    }
}
