To create an animated bottom sheet with swipe-to-close functionality using React Native's native utilities, you will need to utilize the PanResponder and Animated APIs. Below is an example implementation:

First, install the required dependencies:
```
npm install react-native-gesture-handler
```

Import the necessary modules and components:
```javascript
import React, { useRef } from 'react';
import { View, Animated, PanResponder } from 'react-native';
import { PanGestureHandler } from 'react-native-gesture-handler';
```

Define the AnimatedBottomSheet component:
```javascript
const AnimatedBottomSheet = ({ children, visible }) => {
  const sheetHeight = 300; // Set the desired height of the bottom sheet
  const animateY = useRef(new Animated.Value(visible ? 0 : sheetHeight)).current;

  const panResponder = useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: () => true,
      onPanResponderMove: (_, gestureState) => {
        animateY.setValue(gestureState.dy);
      },
      onPanResponderRelease: (_, gestureState) => {
        if (gestureState.dy < -50) {
          // Swipe up to close
          Animated.timing(animateY, {
            toValue: -sheetHeight,
            duration: 300,
            useNativeDriver: false,
          }).start();
        } else if (gestureState.dy > 50) {
          // Swipe down to open
          Animated.timing(animateY, {
            toValue: 0,
            duration: 300,
            useNativeDriver: false,
          }).start();
        } else {
          // Return to original position
          Animated.spring(animateY, {
            toValue: 0,
            bounciness: 8,
            useNativeDriver: false,
          }).start();
        }
      },
    })
  ).current;

  return (
    <PanGestureHandler {...panResponder.panHandlers}>
      <Animated.View
        style={{
          position: 'absolute',
          bottom: animateY,
          left: 0,
          right: 0,
          height: sheetHeight,
        }}
      >
        <View
          style={{
            flex: 1,
            backgroundColor: 'white',
            borderTopLeftRadius: 10,
            borderTopRightRadius: 10,
            shadowColor: '#000',
            shadowOffset: { width: 0, height: -2 },
            shadowOpacity: 0.3,
            shadowRadius: 3,
            elevation: 5,
          }}
        >
          {children}
        </View>
      </Animated.View>
    </PanGestureHandler>
  );
};
```

Finally, use the AnimatedBottomSheet component in your main component:
```javascript
const App = () => {
  const [visible, setVisible] = useState(false);

  return (
    <View style={{ flex: 1 }}>
      {/* Your main content */}

      {/* Add a button or any other trigger to toggle the bottom sheet */}
      <Button title="Toggle Bottom Sheet" onPress={() => setVisible(!visible)} />

      {visible && (
        <AnimatedBottomSheet visible={visible}>
          {/* Content of the bottom sheet */}
        </AnimatedBottomSheet>
      )}
    </View>
  );
};
```

This implementation creates a bottom sheet that can be opened or closed by swiping up or down. The sheet will animate smoothly and follow the user's swipe gestures.

