import java.util.Scanner;

public class Hangman {
    private static final String[] WORDS = {"java", "programming", "computer", "hangman", "code"};
    private static final int MAX_TRIES = 6;

    private static String wordToGuess;
    private static char[] guessedLetters;
    private static int numTries;

    public static void main(String[] args) {
        wordToGuess = getRandomWord();
        guessedLetters = new char[wordToGuess.length()];
        numTries = 0;

        playGame();
    }

    public static void playGame() {
        Scanner scanner = new Scanner(System.in);

        while (numTries < MAX_TRIES) {
            System.out.print("Guess a letter: ");
            char guess = Character.toLowerCase(scanner.next().charAt(0));
            boolean isCorrectGuess = false;

            for (int i = 0; i < wordToGuess.length(); i++) {
                if (wordToGuess.charAt(i) == guess) {
                    guessedLetters[i] = guess;
                    isCorrectGuess = true;
                }
            }

            if (isCorrectGuess) {
                System.out.println("Correct guess!");
            } else {
                numTries++;
                System.out.println("Incorrect guess! You have " + (MAX_TRIES - numTries) + " tries left.");
            }

            System.out.println("Current progress: " + String.valueOf(guessedLetters));

            if (isWordGuessed()) {
                System.out.println("Congratulations! You won!");
                break;
            }
        }

        if (numTries == MAX_TRIES) {
            System.out.println("Game over! You ran out of tries. The word was: " + wordToGuess);
        }

        scanner.close();
    }

    public static String getRandomWord() {
        return WORDS[(int) (Math.random() * WORDS.length)];
    }

    public static boolean isWordGuessed() {
        return wordToGuess.equals(String.valueOf(guessedLetters));
    }
}
```

