```java
import java.util.Scanner;

public class TicTacToe3D {
    private static char[][][] board;
    private static char currentPlayer;
    private static boolean gameOver;

    public static void main(String[] args) {
        board = new char[3][3][3];
        currentPlayer = 'X';
        gameOver = false;

        initializeBoard();
        playGame();
    }

    public static void initializeBoard() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    board[i][j][k] = '-';
                }
            }
        }
    }

    public static void playGame() {
        Scanner scanner = new Scanner(System.in);

        while (!gameOver) {
            System.out.println("Player " + currentPlayer + ", enter your move (layer[1-3] row[1-3] column[1-3]): ");
            int layer = scanner.nextInt() - 1;
            int row = scanner.nextInt() - 1;
            int col = scanner.nextInt() - 1;

            if (isValidMove(layer, row, col)) {
                board[layer][row][col] = currentPlayer;
                printBoard();

                if (hasWon()) {
                    System.out.println("Player " + currentPlayer + " wins!");
                    gameOver = true;
                } else if (isBoardFull()) {
                    System.out.println("It's a draw!");
                    gameOver = true;
                } else {
                    currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
                }
            } else {
                System.out.println("Invalid move! Try again.");
            }
        }

        scanner.close();
    }

    public static boolean isValidMove(int layer, int row, int col) {
       return (layer >= 0 && layer < 3 && row >= 0 && row < 3 && col >= 0 && col < 3 && board[layer][row][col] == '-');
    }

    public static boolean hasWon() {
        for (int i = 0; i < 3; i++) {
            // Check rows and columns
            for (int j = 0; j < 3; j++) {
                if (board[i][j][0] == currentPlayer && board[i][j][1] == currentPlayer && board[i][j][2] == currentPlayer) {
                    return true;
                }
                if (board[j][i][0] == currentPlayer && board[j][i][1] == currentPlayer && board[j][i][2] == currentPlayer) {
                    return true;
                }
            }

            // Check diagonals
            if (board[i][0][0] == currentPlayer && board[i][1][1] == currentPlayer && board[i][2][2] == currentPlayer) {
                return true;
            }
            if (board[i][0][2] == currentPlayer && board[i][1][1] == currentPlayer && board[i][2][0] == currentPlayer) {
                return true;
            }
        }

        // Check layers
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                if (board[0][j][k] == currentPlayer && board[1][j][k] == currentPlayer && board[2][j][k] == currentPlayer) {
                    return true;
                }
            }
        }

        // Check diagonals in different layers
        if (board[0][0][0] == currentPlayer && board[1][1][1] == currentPlayer && board[2][2][2] == currentPlayer) {
            return true;
        }
        if (board[0][2][0] == currentPlayer && board[1][1][1] == currentPlayer && board[2][0][2] == currentPlayer) {
            return true;
        }
        if (board[0][2][2] == currentPlayer && board[1][1][1] == currentPlayer && board[2][0][0] == currentPlayer) {
            return true;
        }

        return false;
    }

    public static boolean isBoardFull() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    if (board[i][j][k] == '-') {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    public static void printBoard() {
        for (int i = 0; i < 3; i++) {
            System.out.println("Layer " + (i + 1) + ":");
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    System.out.print(board[i][j][k] + " ");
                }
                System.out.println();
            }
            System.out.println();
        }
    }
}
```

