Here are some examples of closures in JavaScript, ranging from easy to advanced:

1. Simple Closure:
```javascript
function outer() {
  var data = "Hello, ";

  function inner(name) {
    return data + name;
  }

  return inner;
}

var greet = outer(); // The 'data' variable is stored in 'greet'
console.log(greet("Alice")); // Output: Hello, Alice
console.log(greet("Bob")); // Output: Hello, Bob
```

2. Counter Using Closure:
```javascript
function counter() {
  var count = 0;

  function increment() {
    return ++count;
  }

  return increment;
}

var counter1 = counter();
console.log(counter1()); // Output: 1
console.log(counter1()); // Output: 2

var counter2 = counter();
console.log(counter2()); // Output: 1
```

3. Private Variables with Closure:
```javascript
var person = (function() {
  var name = "John";

  return {
    getName: function() {
      return name;
    },
    setName: function(newName) {
      name = newName;
    }
  };
})();

console.log(person.getName()); // Output: John
person.setName("Alice");
console.log(person.getName()); // Output: Alice
```

4. Currying using Closure:
```javascript
function multiply(a) {
  return function(b) {
    return a * b;
  };
}

var multiplyByTwo = multiply(2);
console.log(multiplyByTwo(5)); // Output: 10

var multiplyByTen = multiply(10);
console.log(multiplyByTen(5)); // Output: 50
```

5. Memoization using Closure:
```javascript
function memoize(func) {
  var cache = {};

  return function(...args) {
    var key = JSON.stringify(args);
    if (cache[key]) {
      console.log("Cache hit! Returning value from cache.");
      return cache[key];
    } else {
      console.log("Cache miss! Calculating and storing value in cache.");
      var result = func.apply(null, args);
      cache[key] = result;
      return result;
    }
  };
}

function add(a, b) {
  console.log("Calculating sum...");
  return a + b;
}

var memoizedAdd = memoize(add);
console.log(memoizedAdd(2, 3)); // Output: Calculating sum... / Cache miss! / 5
console.log(memoizedAdd(2, 3)); // Output: Cache hit! / 5
```

6. Emulating Private Members with Closure:
```javascript
function Person(name, age) {
  var privateAge = age;

  this.name = name;

  this.getAge = function() {
    return privateAge;
  };

  this.setAge = function(newAge) {
    privateAge = newAge;
  };
}

var john = new Person("John", 25);
console.log(john.name); // Output: John
console.log(john.getAge()); // Output: 25
john.setAge(30);
console.log(john.getAge()); // Output: 30
```

These examples demonstrate different use cases of closures in JavaScript.

To iterate through structure fields when fields are `boost::optional` in C++11, you can use a combination of C++11's `std::tuple` and `boost::hana`. `boost::hana` is a library that provides compile-time metaprogramming facilities to perform operations on types and values at compile-time, including iterating through `boost::optional` fields.

Here's an example code snippet illustrating how to iterate through `boost::optional` fields using `std::tuple` and `boost::hana`:

```cpp
#include <tuple>
#include <iostream>
#include <boost/hana.hpp>
#include <boost/optional.hpp>
namespace hana = boost::hana;

// A sample structure with boost::optional fields
struct MyStruct {
    int field1;
    boost::optional<int> field2;
    std::string field3;
    boost::optional<double> field4;
};

int main()
{
    // Create an instance of MyStruct
    MyStruct myStruct{42, 10, "Hello world", 3.14};

    // Create a tuple of the fields as hana::basic_types
    auto fields = std::make_tuple(hana::type_c<decltype(myStruct.field1)>, hana::type_c<decltype(myStruct.field2)>,
                                  hana::type_c<decltype(myStruct.field3)>, hana::type_c<decltype(myStruct.field4)>);

    // Iterate through the fields
    hana::for_each(fields, [&](auto field) {
        using FieldType = decltype(+field);
        std::cout << "Field type: " << hana::to<char const*>(hana::decltype_(field)) << std::endl;

        // Check if the field is boost::optional
        if constexpr(hana::is_a<boost::optional, FieldType>()) {
            FieldType optionalField = myStruct.*hana::to<FieldPtr>(field);
            if (optionalField) {
                std::cout << "Field Value: " << *optionalField << std::endl;
            }
            else {
                std::cout << "Field Value: Not set" << std::endl;
            }
        }
        else {
            FieldType regularField = myStruct.*hana::to<FieldPtr>(field);
            std::cout << "Field Value: " << regularField << std::endl;
        }
    });

    return 0;
}
```

In this example:

1. We define a `MyStruct` structure with `boost::optional` fields.
2. We create a tuple `fields` that contains the types of all the structure fields using `hana::type_c` and `std::make_tuple`.
3. We iterate through the `fields` tuple using `hana::for_each`.
4. Inside the loop, we use `hana::is_a` and `constexpr` to check if the current field is of type `boost::optional`. If so, we extract the field using `hana::to<FieldPtr>(field)` and check if the field is set using the `optionalField` object.
5. Finally, we print out the field type and the field value. For `boost::optional` fields, we print "Not set" if the field is not set.

