To create an Editor script for detecting if the inspector is locked in Unity, you need to create a script file and put it inside the "Editor" folder in your project. Here's an example of how the Editor script would look like:

```csharp
using UnityEditor;
using UnityEngine;

[InitializeOnLoad]
public class InspectorLockEditor : EditorWindow
{
    private static bool isLocked;

    static InspectorLockEditor()
    {
        // Subscribe to the Unity editor update event
        EditorApplication.update += UpdateInspectorLockStatus;
    }

    private static void UpdateInspectorLockStatus()
    {
        // Get the currently focused window
        EditorWindow focusedWindow = EditorWindow.focusedWindow;

        // Check if the focused window is the inspector window
        if (focusedWindow != null && focusedWindow.titleContent != null &&
            focusedWindow.titleContent.text.StartsWith("Inspector"))
        {
            // Get the serialized object of the inspector window
            SerializedObject serializedObject = new SerializedObject(focusedWindow);

            // Get the 'm_Locked' property of the inspector window
            SerializedProperty lockedProperty = serializedObject.FindProperty("m_Locked");

            // Get the current lock status
            bool currentLockStatus = lockedProperty.boolValue;

            // If the lock status has changed, update the isLocked variable and log the result
            if (isLocked != currentLockStatus)
            {
                isLocked = currentLockStatus;
                Debug.Log("Inspector lock status: " + (isLocked ? "locked" : "unlocked"));
            }
        }
    }
}
```

Make sure to save this script in the "Editor" folder. Now, whenever the lock status of the inspector window changes, it will log the current lock status in the Unity console.

