spring.mvc.dispatch-options-request=true
spring.web.cors.allowed-origins=*
spring.web.cors.allowed-methods=GET, POST, DELETE, PUT, OPTIONS
spring.web.cors.allowed-headers=Content-Type, Authorization
```

