Sure, here's an example of a reverse SSH proxy in Go with basic rate limiting:

```go
package main

import (
	"fmt"
	"io"
	"log"
	"net"
	"sync"
	"time"
)

// RateLimiter is a basic rate limiter to limit the number of connections per second
type RateLimiter struct {
	connections    map[string]int
	connectionsMux sync.Mutex
}

// NewRateLimiter creates a new RateLimiter instance
func NewRateLimiter() *RateLimiter {
	return &RateLimiter{
		connections: make(map[string]int),
	}
}

// Limit returns true if the rate limit is reached, false otherwise
func (rl *RateLimiter) Limit(ip string, limit int) bool {
	rl.connectionsMux.Lock()
	defer rl.connectionsMux.Unlock()

	rl.connections[ip]++
	if rl.connections[ip] > limit {
		return true
	}

	// Reset the counter every second
	time.AfterFunc(time.Second, func() {
		rl.connectionsMux.Lock()
		defer rl.connectionsMux.Unlock()

		rl.connections[ip]--
		if rl.connections[ip] == 0 {
			delete(rl.connections, ip)
		}
	})

	return false
}

func handleConnection(conn net.Conn) {
	defer conn.Close()

	// Check rate limit
	rateLimiter := NewRateLimiter()
	if rateLimiter.Limit(conn.RemoteAddr().String(), 5) {
		log.Println("Rate limit reached for", conn.RemoteAddr().String())
		return
	}

	// Forward the connection to the desired SSH server
	sshServer, err := net.Dial("tcp", "your-ssh-server-hostname:your-ssh-server-port")
	if err != nil {
		log.Printf("Error connecting to SSH server: %v\n", err)
		return
	}
	defer sshServer.Close()

	// Start copying data between the client and the SSH server
	go func() {
		_, err := io.Copy(sshServer, conn)
		if err != nil {
			log.Printf("Error copying data from client to SSH server: %v\n", err)
		}
	}()

	_, err = io.Copy(conn, sshServer)
	if err != nil {
		log.Printf("Error copying data from SSH server to client: %v\n", err)
	}
}

func main() {
	listener, err := net.Listen("tcp", ":your-reverse-proxy-port")
	if err != nil {
		log.Panicf("Error starting the reverse proxy listener: %v\n", err)
	}
	defer listener.Close()

	log.Println("Reverse SSH Proxy started on port :your-reverse-proxy-port")

	for {
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("Error accepting connection: %v\n", err)
			continue
		}

		go handleConnection(conn)
	}
}
```

This example demonstrates a basic reverse SSH proxy with rate limiting. The `RateLimiter` struct is responsible for rate limiting the number of connections per second per IP address. Adjust the rate limit value in the `Limit` function according to your requirements.

Replace `"your-ssh-server-hostname"` and `"your-ssh-server-port"` with the hostname and port of your actual SSH server. Change `"your-reverse-proxy-port"` to the port number you want the reverse proxy to listen on.

Please note that this example is for educational purposes only and may require additional error handling and security measures to be suitable for production use.

To create a firewall in Go that blocks all HTTP requests except for the ones from Cloudflare's IPs, you can use the following code as a starting point. 

Please note that this code only demonstrates the basic structure and logic of how you can implement a firewall. It may require modifications and additional validations based on your specific needs and environment.

```go
package main

import (
	"fmt"
	"net/http"
	"strings"
)

// List of Cloudflare IPs
var allowedIPs = []string{
	"103.21.244.0/22",
	"103.22.200.0/22",
	// Add more Cloudflare IPs here
}

// Middleware to check if the request is from a Cloudflare IP
func cloudflareMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ip := getIPAddress(r)
		if !isCloudflareIP(ip) {
			w.WriteHeader(http.StatusForbidden)
			return
		}

		// Pass the request to the next handler
		next.ServeHTTP(w, r)
	})
}

// Function to get the client's IP address from the request
func getIPAddress(r *http.Request) string {
	ip := r.Header.Get("CF-Connecting-IP")
	if ip == "" {
		ip = strings.Split(r.RemoteAddr, ":")[0]
	}
	return ip
}

// Function to check if the given IP is a Cloudflare IP
func isCloudflareIP(ip string) bool {
	for _, cidr := range allowedIPs {
		if isIPInCIDR(ip, cidr) {
			return true
		}
	}
	return false
}

// Function to check if an IP address is within the given CIDR range
func isIPInCIDR(ip, cidr string) bool {
	ipAddr := parseIP(ip)
	_, ipNet, _ := net.ParseCIDR(cidr)
	return ipNet.Contains(ipAddr)
}

// Function to parse the IP address string to net.IP type
func parseIP(ip string) net.IP {
	parsedIP := net.ParseIP(ip)
	if parsedIP == nil {
		parsedIP = net.ParseIP(strings.Split(ip, ":")[0])
	}
	return parsedIP
}

// Example handler to handle valid requests
func myHandler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Hello, this is a valid request!")
}

func main() {
	// Create a new router
	router := http.NewServeMux()

	// Attach the middleware
	router.Handle("/", cloudflareMiddleware(http.HandlerFunc(myHandler)))

	// Start the server
	http.ListenAndServe(":8080", router)
}
```

In this code, we define a list of Cloudflare IPs in the `allowedIPs` variable. The `cloudflareMiddleware` function is used as a middleware to check if the request's IP is from Cloudflare. If it is, the request is passed to the next handler (in this case, `myHandler`). If it's not, a `403 Forbidden` response is sent.

The `getIPAddress` function extracts the client's IP address from the request by first checking the `CF-Connecting-IP` header. If it's not present (when running locally or outside of Cloudflare), it falls back to getting the IP from the `RemoteAddr` field.

The `isCloudflareIP` function checks if the given IP is present in the list of allowed IPs.

The `isIPInCIDR` function uses the `net` package to parse the IP and CIDR strings and checks if the IP is within the CIDR range.

The `parseIP` function attempts to parse the IP address string and handles cases where the IP contains a port number.

The example `myHandler` function is a placeholder for any valid request handler logic you would like to implement.

Finally, we create a new router using `http.NewServeMux`, attach the `cloudflareMiddleware` to the root path, and start the server using `http.ListenAndServe`.

Remember to update the `allowedIPs` list with the actual Cloudflare IPs before deploying this code in a production environment.

