Конечно, вот пример программы на Arduino для ESP32 с использованием библиотеки FFT library для вывода спектра с минимальным использованием памяти для переменных:

```cpp
#include <Adafruit_NeoPixel.h>
#include <I2S.h>
#include <FFT.h>

#define LED_PIN 0
#define LED_COUNT 8

#define I2S_WS 33
#define I2S_SD 32
#define I2S_SCK 27

Adafruit_NeoPixel strip(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);
double vReal[LED_COUNT];
double vImag[LED_COUNT];

void IRAM_ATTR onSample()
{
  for (int i = 0; i < LED_COUNT; i++)
  {
    double sample = I2S.read();
    vReal[i] = sample;
    vImag[i] = 0;
  }
}

void setup()
{
  Serial.begin(115200);

  I2S.begin(I2S_PHILIPS_MODE, 8000, I2S_BITS_PER_SAMPLE_32BIT, I2S_CHANNELS_MONO, I2S_CHANNEL_FORMAT_ONLY_RIGHT, I2S_COMM_FORMAT_I2S);
  I2S.set_pin(I2S_SCK, I2S_WS, I2S_SD);

  strip.begin();
  strip.show();

  I2S.onSample(onSample);
}

void loop()
{
  FFT.Windowing(vReal, LED_COUNT, FFT_WIN_TYP_HAMMING, FFT_FORWARD);
  FFT.Compute(vReal, vImag, LED_COUNT, FFT_FORWARD);
  FFT.ComplexToMagnitude(vReal, vImag, LED_COUNT);

  strip.clear();

  for (int i = 0; i < LED_COUNT; i++)
  {
    uint8_t value = (uint8_t)(vReal[i] / 100.0);
    strip.setPixelColor(i, value, 0, 0);
  }

  strip.show();

  delay(100);
}
```

В данном примере мы подключаем библиотеки для работы с матрицей светодиодов ws2812, I2S и FFT. Создаем массивы `vReal` и `vImag` для хранения данных с микрофона. В функции `onSample` считываем аудиоданные с микрофона и сохраняем их в массивы. В `setup` инициализируем UART, I2S и матрицу светодиодов. В `loop` выполняем Фурье-преобразование на основе данных с микрофона, преобразуем комплексные числа в значения амплитуды и отображаем полученные значения на матрице светодиодов.

Убедитесь, что установлены все необходимые библиотеки перед компиляцией и загрузкой программы.

Конечно, вот пример программы на Arduino для ESP32 с использованием библиотеки FastLED и FFT library для вывода спектра на матрице ws2812 размером 8x32 с минимальным использованием памяти для переменных:

```cpp
#include <I2S.h>
#include <FFT.h>
#include <FastLED.h>

#define LED_PIN 0
#define LED_WIDTH 32
#define LED_HEIGHT 8

#define I2S_WS 33
#define I2S_SD 32
#define I2S_SCK 27

CRGB leds[LED_WIDTH * LED_HEIGHT];
double vReal[LED_WIDTH];

void IRAM_ATTR onSample()
{
  static int index = 0;

  double sample = I2S.read();
  vReal[index] = sample;

  index++;

  if (index >= LED_WIDTH)
  {
    index = 0;
    for (int i = 0; i < LED_HEIGHT; i++)
    {
      FFT.Windowing(vReal, LED_WIDTH, FFT_WIN_TYP_HAMMING, FFT_FORWARD);
      FFT.Compute(vReal, NULL, LED_WIDTH, FFT_FORWARD);
      double peak = FFT.MajorPeak(vReal, LED_WIDTH);

      int height = LED_HEIGHT * peak;
      for (int j = 0; j < LED_HEIGHT; j++)
      {
        if (j <= height)
        {
          leds[j * LED_WIDTH + i] = CRGB::Red;
        }
        else
        {
          leds[j * LED_WIDTH + i] = CRGB::Black;
        }
      }
    }

    FastLED.show();
  }
}

void setup()
{
  Serial.begin(115200);

  I2S.begin(I2S_PHILIPS_MODE, 8000, I2S_BITS_PER_SAMPLE_32BIT, I2S_CHANNELS_MONO, I2S_CHANNEL_FORMAT_ONLY_RIGHT, I2S_COMM_FORMAT_I2S);
  I2S.set_pin(I2S_SCK, I2S_WS, I2S_SD);

  FastLED.addLeds<WS2812, LED_PIN, GRB>(leds, LED_WIDTH * LED_HEIGHT);

  I2S.onSample(onSample);
}

void loop()
{
  // Ничего не делаем в основном цикле, обработка звука происходит в функции onSample
  delay(10);
}
```

В данном примере мы подключаем библиотеки для работы с I2S (микрофоном), FFT и FastLED (матрицей светодиодов). Создаем массив `vReal` для хранения данных с микрофона. В функции `onSample` считываем аудиоданные с микрофона и сохраняем их в массив `vReal`. Когда накапливается достаточное количество данных для одной горизонтальной полосы спектра на матрице, выполняем Фурье-преобразование и отображаем полученные значения на матрице светодиодов. Матрица обновляется каждую горизонтальную полосу спектра. Убедитесь, что установлены все необходимые библиотеки перед компиляцией и загрузкой программы.

