#include <driver/i2s.h>
#include <ArduinoFFT.h>
#include <FastLED.h>

#define LED_PIN 0
#define LED_WIDTH 32
#define LED_HEIGHT 8

#define I2S_WS 33
#define I2S_SD 32
#define I2S_SCK 27

CRGB leds[LED_WIDTH * LED_HEIGHT];
double vReal[LED_WIDTH];
double vImag[LED_WIDTH];

ArduinoFFT FFT = ArduinoFFT();

void IRAM_ATTR onSample()
{
  static int index = 0;

  double sample = i2s_pop_sample(I2S_NUM_0);
  vReal[index] = sample;
  vImag[index] = 0;

  index++;

  if (index >= LED_WIDTH)
  {
    index = 0;
    FFT.Windowing(vReal, LED_WIDTH, FFT_WIN_TYP_HAMMING);
    FFT.Compute(vReal, vImag, LED_WIDTH, FFT_FORWARD);
    FFT.ComplexToMagnitude(vReal, vImag, LED_WIDTH);

    for (int i = 0; i < LED_HEIGHT; i++)
    {
      double peak = vReal[i];
      int height = LED_HEIGHT * peak;

      for (int j = 0; j < LED_WIDTH; j++)
      {
        if (j < height)
        {
          leds[i * LED_WIDTH + j] = CRGB::Red;
        }
        else
        {
          leds[i * LED_WIDTH + j] = CRGB::Black;
        }
      }
    }

    FastLED.show();
  }
}

void setup()
{
