  side: string,
  maxVolume: number,
  isBestPrice: boolean,
  yPosition: number,
  cellHeight: number,
  fullWidth: number,
  dpiScale: number,
  darkMode: boolean,
) => {
  // ...

  // Проверяем, нужно ли умножать quantity на price
  if (settings.dollarsVolume) {
    // Получаем текущую цену
