```csharp
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;

static void CreateVideoFromBitmap(Bitmap bitmap, string outputPath, int frameCount)
{
    // Создание потока для записи видео в файл
    using (var stream = new FileStream(outputPath, FileMode.Create))
    {
        // Создание кодека видео на основе расширения файла
        var videoCodec = MediaCodec.CreateFromFourcc(Path.GetExtension(outputPath).TrimStart('.'));

        // Создание объекта кодировщика видео
        using (var videoEncoder = videoCodec.CreateEncoder())
        {
            // Определение параметров кодирования видео на основе первого кадра
            videoEncoder.SetPixelFormat(PixelFormat.Format24bppRgb);
            videoEncoder.SetResolution(bitmap.Width, bitmap.Height);
            videoEncoder.SetFrameRate(30);

            // Открытие кодировщика видео для записи
            videoEncoder.Open(stream);

            // Запись нескольких кадров в видео файл
            for (int i = 0; i < frameCount; i++)
            {
                // Преобразование кадра в формат, поддерживаемый кодировщиком
                var convertedBitmap = bitmap.Clone(new Rectangle(0, 0, bitmap.Width, bitmap.Height), PixelFormat.Format24bppRgb);

                // Запись кадра в видео файл
                videoEncoder.WriteFrame(convertedBitmap);

                // Освобождение ресурсов клонированного кадра
                convertedBitmap.Dispose();
            }

            // Закрытие кодировщика видео
            videoEncoder.Close();
        }
    }
}

