                }

                R.id.third_item -> {
                    true
                }

                R.id.fourth_item -> {
                    true
                }

                else -> false
            }
        }

        changeFragment(HomeFragment.newInstance()) // Перемещение фрагмента после настройки навигации
    }

    // ...

    /**
    Function for quick change of fragments
     **/
    companion object {
        @JvmStatic
        fun replaceFragment(fragment: Fragment) {
