To execute MySQL queries and display their results on the screen in a Windows Forms application, you can use the MySQL Connector/NET library. Make sure you've installed the MySQL Connector/NET NuGet package in your project.

Here's an example of C# code that creates 5 buttons and executes the MySQL queries you provided:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Windows.Forms;
using MySql.Data.MySqlClient;

namespace ButtonAndDisplayExample
{
    public class MainForm : Form
    {
        private Button[] buttons;

        private string connectionString = "your_mysql_connection_string";

        public MainForm()
        {
            this.Text = "Button and Display Example";
            this.Size = new System.Drawing.Size(400, 300);

            buttons = new Button[5];
            for (int i = 0; i < buttons.Length; i++)
            {
                buttons[i] = new Button();
                buttons[i].Text = "Button " + (i + 1);
                buttons[i].Location = new System.Drawing.Point(20, 20 + (i * 40));
                buttons[i].Click += new EventHandler(Button_Click);
                this.Controls.Add(buttons[i]);
            }       
        }

        private void Button_Click(object sender, EventArgs e)
        {
            Button button = (Button)sender;
            string query = GetQuery(button.Text);

            List<string[]> results = ExecuteQuery(query);
            DisplayResults(results);
        }

        private string GetQuery(string buttonText)
        {
            switch (buttonText)
            {
                case "Button 1":
                    return "SELECT * FROM Owners WHERE OwnerID IN (SELECT OwnerID FROM Horses GROUP BY OwnerID HAVING COUNT(*) > 1)";
                case "Button 2":
                    // Prompt user to enter the rating value
                    double ratingValue = double.Parse(Interaction.InputBox("Enter the rating value:"));
                    return $"SELECT * FROM Jockeys WHERE Rating > {ratingValue}";
                case "Button 3":
                    // Prompt user to enter the start and end dates
                    string startDate = Interaction.InputBox("Enter the start date (YYYY-MM-DD):");
                    string endDate = Interaction.InputBox("Enter the end date (YYYY-MM-DD):");
                    return $"SELECT Races.RaceName, Results.Position, Horses.HorseName, Races.Location FROM Results JOIN Races ON Results.RaceID = Races.RaceID JOIN Horses ON Results.HorseID = Horses.HorseID WHERE Races.RaceDate BETWEEN '{startDate}' AND '{endDate}'";
                case "Button 4":
                    // Prompt user to enter the location
                    string location = Interaction.InputBox("Enter the racetrack location:");
                    return $"SELECT Jockeys.JockeyName, SUM(CASE WHEN Results.Position = 'I' THEN 1 ELSE 0 END) AS FirstPlaceCount FROM Results JOIN Jockeys ON Results.JockeyID = Jockeys.JockeyID JOIN Races ON Results.RaceID = Races.RaceID WHERE Races.Location = '{location}' AND Races.RaceDate BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 MONTH) AND CURDATE() GROUP BY Jockeys.JockeyID ORDER BY FirstPlaceCount DESC LIMIT 3";
                default:
                    return string.Empty;
            }
        }

        private List<string[]> ExecuteQuery(string query)
        {
            List<string[]> results = new List<string[]>();

            using (MySqlConnection connection = new MySqlConnection(connectionString))
            {
                try
                {
                    connection.Open();
                    MySqlCommand command = new MySqlCommand(query, connection);
                    MySqlDataReader reader = command.ExecuteReader();

                    // Read the data and store it in a list of string arrays
                    while (reader.Read())
                    {
                        string[] row = new string[reader.FieldCount];
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            row[i] = reader.GetString(i);
                        }
                        results.Add(row);
                    }

                    reader.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("An error occurred: " + ex.Message);
                }
            }

            return results;
        }

        private void DisplayResults(List<string[]> results)
        {
            // Clear existing controls
            foreach (Control c in this.Controls)
            {
                if (c is Label || c is DataGridView)
                {
                    this.Controls.Remove(c);
                }
            }

            if (results.Count > 0)
            {
                // Create a label to display the query result count
                Label countLabel = new Label();
                countLabel.Text = $"Query returned {results.Count} rows.";
                countLabel.Location = new System.Drawing.Point(20, 250);
                this.Controls.Add(countLabel);

                // Create a DataGridView to show the query results
                DataGridView resultsGrid = new DataGridView();
                resultsGrid.Location = new System.Drawing.Point(20, 280);
                resultsGrid.Size = new System.Drawing.Size(350, 200);
                this.Controls.Add(resultsGrid);

                // Set up the DataGridView columns and rows
                resultsGrid.ColumnCount = results[0].Length;
                for (int i = 0; i < results[0].Length; i++)
                {
                    resultsGrid.Columns[i].HeaderText = $"Column {i + 1}";
                }
                for (int i = 0; i < results.Count; i++)
                {
                    resultsGrid.Rows.Add(results[i]);
                }
            }
            else
            {
                MessageBox.Show("Query returned no results.");
            }
        }

        [STAThread]
        static void Main()
        {
            Application.Run(new MainForm());
        }
    }
}
```

In this code, you can provide your MySQL connection string in the `connectionString` variable. When a button is clicked, the corresponding MySQL query is executed using the `ExecuteQuery` method, which returns the query results as a list of string arrays. The `DisplayResults` method creates a `Label` to show the count of rows returned by the query and a `DataGridView` to display the query results.

Please note that this code assumes you have a `Label` and a `DataGridView` control added to the main form initially to display the query results. You can change the location and size of these controls based on your requirements or modify the code to create them programmatically.

