    public String getEnvironmentMethodName(String className, String obfuscatedMethodName, String obfuscatedDescriptor) {
        Map<String, String> methodMappings = classMappings.get(className);
        return methodMappings.getOrDefault(obfuscatedMethodName + obfuscatedDescriptor, obfuscatedMethodName);
    }

