```java
private void addRoundedSquare() {
    int size = 40; // размер квадратика
    int margin = 8; // отступ между квадратиками
    int roundRadius = size / 4; // радиус скругления углов

    ShapeDrawable shape = new ShapeDrawable(new RoundRectShape(
            new float[] { roundRadius, roundRadius, roundRadius, roundRadius,
                          roundRadius, roundRadius, roundRadius, roundRadius },
            null,
            null));
    shape.getPaint().setColor(Color.RED);

    TextView title = findViewById(R.id.Title);

    int leftMargin = title.getRight() + margin;
    int topMargin = title.getTop() - margin - size;
    int rightMargin = leftMargin + size;
    int bottomMargin = topMargin + size;

    ConstraintLayout.LayoutParams params = new ConstraintLayout.LayoutParams(size, size);
    params.leftMargin = leftMargin;
    params.topMargin = topMargin;
    params.rightMargin = rightMargin;
    params.bottomMargin = bottomMargin;

