void compressByPacking0(uint8_t *out, uint8_t *in, uint32_t length) {
    static uint8_t lookup[4096];
    static const uint8_t lookup5[8] = { 0, 1, 2, 0, 3, 0, 0, 0 };

    if (lookup[0] == 0) {    
        /* initialize lookup table */
        for (int i = 0; i < 4096; i++) {
            lookup[i] = (lookup5[(i >> 0) & 7] << 0) +
                        (lookup5[(i >> 3) & 7] << 2) +
                        (lookup5[(i >> 6) & 7] << 4) +
                        (lookup5[(i >> 9) & 7] << 6);
        }
    }
    for (; length >= 4; length -= 4, in += 4, out++) {
         *out = lookup[(in[0] << 9) + (in[1] << 6) + (in[2] << 3) + (in[3] << 0)];
    }
    uint8_t last = 0;
    switch (length) {
      case 3:
        last |= lookup5[in[2]] << 4;
        /* fall through */
      case 2:
        last |= lookup5[in[1]] << 2;
        /* fall through */
      case 1:
        last |= lookup5[in[0]] << 0;
        *out = last;
        break;
    }
}

Here is the decompressor code for the provided compress code:

```cpp
void decompressByUnpacking0(uint8_t *out, uint8_t *in, uint32_t length) {
    static uint8_t lookup[4096];
    static const uint8_t lookup5[8] = { 0, 1, 2, 0, 3, 0, 0, 0 };

    if (lookup[0] == 0) {    
        /* initialize lookup table */
        for (int i = 0; i < 4096; i++) {
            lookup[i] = (lookup5[(i >> 0) & 7] << 0) +
                        (lookup5[(i >> 3) & 7] << 2) +
                        (lookup5[(i >> 6) & 7] << 4) +
                        (lookup5[(i >> 9) & 7] << 6);
        }
    }
    uint8_t last = 0;
    for (; length >= 4; length -= 4, in++, out += 4) {
        uint8_t index = *in;
        out[0] = lookup[index] >> 9;
        out[1] = (lookup[index] >> 6) & 7;
        out[2] = (lookup[index] >> 3) & 7;
        out[3] = lookup[index] & 7;
    }
    switch (length) {
        case 3:
            last = *in;
            out[2] = lookup5[last >> 4];
            out[1] = lookup5[(last >> 2) & 3];
            /* fall through */
        case 2:
            last = *in;
            out[1] = lookup5[(last >> 2) & 3];
            out[0] = lookup5[last & 3];
            /* fall through */
        case 1:
            out[0] = lookup5[*in];
            break;
    }
}
