  esp_now_register_send_cb([](uint8_t* mac, uint8_t sendStatus) {
    Serial.println("Message sent to the second ESP32");
  });

  // Set the MAC address for peer-to-peer communication
  esp_now_peer_info_t peer;
  memcpy(peer.peer_addr, sendMACAddress, 6);
  peer.channel = 0;
  peer.encrypt = false;
  if (esp_now_add_peer(&peer) != ESP_OK) {
    Serial.println("Failed to add peer");
    return;
  }

  // Set the I2C receive callback
  Wire.onReceive(receiveData);

  Serial.begin(115200);
}

void loop() {
