```cpp
#include <Ogre.h>

Ogre::Vector3 TFormVector(const Ogre::Vector3& originalVector, Ogre::SceneNode* sourceNode, Ogre::SceneNode* destNode) {
    Ogre::Vector3 transformedVector = originalVector;

    // If sourceNode is not provided or is null, use the world coordinates
    const Ogre::Vector3& sourcePosition = (sourceNode) ? sourceNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    const Ogre::Quaternion& sourceOrientation = (sourceNode) ? sourceNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // If destNode is not provided or is null, use the world coordinates
    const Ogre::Vector3& destPosition = (destNode) ? destNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    const Ogre::Quaternion& destOrientation = (destNode) ? destNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // Convert original vector to local space of sourceNode
    transformedVector = sourceOrientation.Inverse() * (originalVector - sourcePosition);

    // Convert vector from source local space to dest local space
    transformedVector = destOrientation * transformedVector;

    // Convert vector to world coordinates
    transformedVector = destPosition + transformedVector;

    return transformedVector;
}
```

