#include <esp_now.h>
#include <WiFi.h>

// Define the slave address used for I2C communication
#define SLAVE_ADDRESS 0x10

// Define the SPI pins
#define SPI_DATA_PIN 23
#define SPI_CLOCK_PIN 18
#define SPI_SELECT_PIN 5

// Define the GPIO pins
#define GPIO_PIN1 4
#define GPIO_PIN2 16

// Define the number of bytes in the buffers
#define BUFFER_SIZE 32

// Define the buffer for GPIO inputs/outputs
uint8_t gpioBuffer[2];

// Define the buffer for I2C inputs/outputs
uint8_t i2cBuffer[BYTE_AMOUNT];

// Define the buffer for SPI inputs/outputs
uint8_t spiBuffer[BYTE_AMOUNT];

// Declare the interrupt handler functions
void IRAM_ATTR gpioInterrupt1();
void IRAM_ATTR gpioInterrupt2();

// Define the interrupt pin numbers for GPIO
const int GPIO_INT_PIN1 = 19;
const int GPIO_INT_PIN2 = 21;

// Define the WiFi settings
const char* wifiSsid = "your_wifi_ssid";
const char* wifiPassword = "your_wifi_password";

// Define the threshold for ESPNow reliability
const int RESEND_THRESHOLD = 3;

// Define the structure that holds the ESPNow data
typedef struct __attribute__((packed)) {
  uint8_t retryCount;
  uint8_t buffer[BUFFER_SIZE];
} EspNowData;

// Define the callback function for ESPNow message reception
void OnDataRecv(const uint8_t* macAddr, const uint8_t* data, int dataLen) {
  // Check the data length and MAC address
  if (dataLen != sizeof(EspNowData) || macAddr == NULL) {
    return;
  }

  EspNowData* recvData = (EspNowData*)data;

  // Process the received buffer
  // Buffer type can be determined by the sender and receiver
  // For example, if 'bufferType' is 1, it's the GPIO buffer
  // If 'bufferType' is 2, it's the I2C buffer, and so on...

  int bufferType = recvData->buffer[0];

  switch (bufferType) {
    case 1: // GPIO buffer
      memcpy(gpioBuffer, recvData->buffer + 1, BUFFER_SIZE - 1);
      break;
    case 2: // I2C buffer
      memcpy(i2cBuffer, recvData->buffer + 1, BUFFER_SIZE - 1);
      break;
    case 3: // SPI buffer
      memcpy(spiBuffer, recvData->buffer + 1, BUFFER_SIZE - 1);
      break;
    default:
      break;
  }
}

void setup() {
  // Initialize GPIO pins as inputs
  pinMode(GPIO_PIN1, INPUT);
  pinMode(GPIO_PIN2, INPUT);

  // Initialize Interrupt Service Routines (ISRs)
  attachInterrupt(digitalPinToInterrupt(GPIO_INT_PIN1), gpioInterrupt1, CHANGE);
  attachInterrupt(digitalPinToInterrupt(GPIO_INT_PIN2), gpioInterrupt2, CHANGE);

  // Start ESPNow communication
  WiFi.mode(WIFI_STA);
  if (esp_now_init() != ESP_OK) {
    Serial.println("Error initializing ESPNow");
    while (true);
  }

  // Register a callback function for ESPNow message reception
  esp_now_register_recv_cb(OnDataRecv);

  // Add the master ESP32 MAC address to the peer list
  // Change the peer MAC address to the slave's MAC address
  esp_now_peer_info_t peer;
  memcpy(peer.peer_addr, byte[]{0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 6);
  peer.channel = 0;
  peer.encrypt = false;
  if (esp_now_add_peer(&peer) != ESP_OK) {
    Serial.println("Error adding ESPNow peer");
    while (true);
  }

  // Connect to WiFi network
  WiFi.begin(wifiSsid, wifiPassword);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }
  Serial.println("Connected to WiFi");
}

void loop() {
  // Check if there is any data in the buffers to be sent
  // Buffer type can be changed accordingly (1: GPIO, 2: I2C, 3: SPI)
  if (gpioBufferHasData()) {
    EspNowData data;
    data.retryCount = 0;
    data.buffer[0] = 1; // Buffer type

    memcpy(data.buffer + 1, gpioBuffer, BUFFER_SIZE - 1);

    sendBufferToSlave(data);
