// Find the best move for the AI using the Minimax algorithm
function findBestMove() {
  var bestScore = -Infinity;
  var bestMove;

  var boxes = document.getElementsByClassName("box");
  for (var i = 0; i < boxes.length; i++) {
    if (boxes[i].innerHTML === "") {
      boxes[i].innerHTML = currentPlayer;

      var score = minimax(boxes, 0, false);
      boxes[i].innerHTML = "";

      if (score > bestScore) {
        bestScore = score;
        bestMove = i;
      }
    }
  }

  return bestMove;
}

// Minimax algorithm to determine the best move for the AI
function minimax(boxes, depth, isMaximizingPlayer) {
  var scores = {
    X: -1,
    O: 1,
    tie: 0
  };

  if (checkWinner("X")) {
    return scores.X;
  }

  if (checkWinner("O")) {
    return scores.O;
  }

  if (isBoardFull(boxes)) {
    return scores.tie;
