    var bestScore = Infinity;
    for (var i = 0; i < boxes.length; i++) {
      if (boxes[i].innerHTML === "") {
        boxes[i].innerHTML = "X";
        var score = minimax(boxes, depth + 1, true);
        boxes[i].innerHTML = "";
        bestScore = Math.min(score, bestScore);
