```javascript
document.addEventListener("DOMContentLoaded", function() {
  const gameContainer = document.getElementById("game-container");
  const character = document.getElementById("character");
  let gameSpeed = 2;

  function createBlock() {
    const block = document.createElement("div");
    block.classList.add("block");
    block.style.left = Math.random() * 350 + "px";
    gameContainer.appendChild(block);

    moveBlock(block);
  }

  function moveBlock(block) {
    let blockPosition = 0;

    const blockMove = setInterval(() => {
      if (blockPosition === 400) {
        clearInterval(blockMove);
        block.remove();
      } else if (
        blockPosition >= 350 && 
        blockPosition <= 450 && 
        character.style.bottom === "40px"
      ) {
        clearInterval(blockMove);
      } else {
        blockPosition += gameSpeed;
        block.style.top = blockPosition + "px";
      }
    }, 10);
  }

  document.addEventListener("keydown", function(event) {
    if (event.code === "Space" && character.style.bottom === "0px") {
      character.style.bottom = "40px";
      setTimeout(function() {
        character.style.bottom = "0px";
      }, 300);
    }
  });

  setInterval(createBlock, 2000);
});
```

