import java.util.HashSet;

public class BeautifulArray {
    public static int minSumOfBeautifulArray(int n, int target) {
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = i + 1;
        }

        int sum = getSum(nums);

        // Check if the initial array is already beautiful
        HashSet<Integer> distinctSums = new HashSet<>();
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int currSum = nums[i] + nums[j];
                if (distinctSums.contains(currSum)) {
                    return sum;
                }
                distinctSums.add(currSum);
            }
        }

        // Iterate over the array to find a pair of elements to swap
        while (true) {
            boolean swapped = false;

            for (int i = 0; i < n - 1; i++) {
                for (int j = i + 1; j < n; j++) {
                    int currSum = nums[i] + nums[j];
                    if (currSum == target) {
                        // Swap the elements
                        int temp = nums[i];
                        nums[i] = nums[j];
                        nums[j] = temp;

                        swapped = true;
                        sum = getSum(nums);
                    } else if (!distinctSums.contains(currSum)) {
                        return sum;
                    }
                }
            }

            if (!swapped) {
                return sum;
            }
        }
    }

    public static int getSum(int[] nums) {
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        return sum;
    }

    public static void main(String[] args) {
        int n = 5;
        int target = 7;

        int minSum = minSumOfBeautifulArray(n, target);
        System.out.println("Minimum possible sum: " + minSum);
    }
}
```

