```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define STACK_SIZE 100

typedef struct {
    double* stack;
    int top;
} Stack;

void initStack(Stack* stack) {
    stack->stack = (double*) malloc(STACK_SIZE * sizeof(double));
    stack->top = -1;
}

int isStackEmpty(Stack* stack) {
    return stack->top == -1;
}

void push(Stack* stack, double value) {
    stack->stack[++(stack->top)] = value;
}

double pop(Stack* stack) {
    return stack->stack[(stack->top)--];
}

double calculateRPN(char* expression) {
    Stack stack;
    initStack(&stack);

    char* token = strtok(expression, " ");
    while (token != NULL) {
        if (strcmp(token, "+") == 0) {
            double operand2 = pop(&stack);
            double operand1 = pop(&stack);
            push(&stack, operand1 + operand2);
        } else if (strcmp(token, "-") == 0) {
            double operand2 = pop(&stack);
            double operand1 = pop(&stack);
            push(&stack, operand1 - operand2);
        } else if (strcmp(token, "*") == 0) {
            double operand2 = pop(&stack);
            double operand1 = pop(&stack);
            push(&stack, operand1 * operand2);
        } else if (strcmp(token, "/") == 0) {
            double operand2 = pop(&stack);
            double operand1 = pop(&stack);
            push(&stack, operand1 / operand2);
        } else {
            push(&stack, atof(token));
        }
        token = strtok(NULL, " ");
    }

    double result = pop(&stack);
    free(stack.stack);

    return result;
}

int main() {
    char expression[] = "4 3 + 5 +";
    double result = calculateRPN(expression);
    printf("Result: %.2f\n", result);

    return 0;
}
```

В данном примере функция calculateRPN принимает строку в обратной польской нотации и вычисляет ее значение, используя стек.

Приведенный выше пример реализует функцию calculateRPN, которая работает с обратной польской нотацией для арифметических выражений. Однако, для решения задачи построения графиков функций, задаваемых произвольными выражениями, требуется более сложное решение.

Для решения данной задачи необходимо:
1. Разбить входную строку на лексемы (операторы и операнды) и создать список лексем.
2. Преобразовать список лексем в польскую нотацию с помощью алгоритма Дейкстры.
3. Вычислить значение выражения в польской нотации.
4. Отрисовать график функции в терминале с помощью символов '*' и '.'.

Для реализации этих шагов потребуется создать дополнительные модули, такие как модуль разбора строки и модуль отрисовки графика.

Ниже приведу пример программы на языке C, реализующей данные шаги для построения графиков функций:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define GRAPH_WIDTH 80
#define GRAPH_HEIGHT 25
#define DOMAIN_START 0.0
#define DOMAIN_END 4.0 * M_PI
#define RANGE_START -1.0
#define RANGE_END 1.0
#define CENTER_X 0
#define CENTER_Y 13
#define GRAPH_CHAR '*'
#define EMPTY_CHAR '.'

typedef struct {
    char* expression;
    double x;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    ListNode* tail;
} List;

// Функции для работы со списком лексем

ListNode* createNode(char* expression, double x) {
    ListNode* node = (ListNode*) malloc(sizeof(ListNode));
    node->expression = (char*) malloc((strlen(expression) + 1) * sizeof(char));
    strcpy(node->expression, expression);
    node->x = x;
    node->next = NULL;
    return node;
}

void initList(List* list) {
    list->head = NULL;
    list->tail = NULL;
}

void appendToList(List* list, char* expression, double x) {
    ListNode* node = createNode(expression, x);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
}

void freeList(List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current->expression);
        free(current);
        current = next;
    }
}

// Функции для преобразования строки в список лексем

int isOperator(char token) {
    return token == '+' || token == '-' || token == '*' || token == '/';
}

int isDigit(char token) {
    return token >= '0' && token <= '9';
}

List tokenizeExpression(char* expression) {
    List tokenList;
    initList(&tokenList);

    int length = strlen(expression);
    char token[50];
    int tokenIndex = 0;
    for (int i = 0; i < length; i++) {
        if (isOperator(expression[i])) {
            token[tokenIndex] = '\0';
            appendToList(&tokenList, token, 0);
            token[0] = expression[i];
            token[1] = '\0';
            appendToList(&tokenList, token, 0);
            tokenIndex = 0;
        } else if (isDigit(expression[i]) || expression[i] == '.') {
            token[tokenIndex++] = expression[i];
        } else if (expression[i] != ' ') {
            printf("Invalid character: %c", expression[i]);
            freeList(&tokenList);
            exit(-1);
        }
    }

    token[tokenIndex] = '\0';
    appendToList(&tokenList, token, 0);

    return tokenList;
}

// Функции для преобразования списка лексем в польскую нотацию

int getPrecedence(char operator) {
    if (operator == '+' || operator == '-') {
        return 1;
    } else if (operator == '*' || operator == '/') {
        return 2;
    }
    return -1;
}

int isLeftAssociative(char operator) {
    return operator != '^';
}

List convertToRPN(List tokenList) {
    List rpnList;
    initList(&rpnList);

    List operatorStack;
    initList(&operatorStack);

    ListNode* current = tokenList.head;
    while (current != NULL) {
        if (isOperator(current->expression[0])) {
            while (operatorStack.head != NULL
                    && isOperator(operatorStack.head->expression[0])
                    && ((isLeftAssociative(current->expression[0])
                            && getPrecedence(current->expression[0]) <= getPrecedence(operatorStack.head->expression[0]))
                        || (!isLeftAssociative(current->expression[0])
                            && getPrecedence(current->expression[0]) < getPrecedence(operatorStack.head->expression[0])))) {
                appendToList(&rpnList, operatorStack.head->expression, 0);
                operatorStack.head = operatorStack.head->next;
            }
            appendToList(&operatorStack, current->expression, 0);
        } else {
            appendToList(&rpnList, current->expression, current->x);
        }
        current = current->next;
    }

    while (operatorStack.head != NULL) {
        appendToList(&rpnList, operatorStack.head->expression, 0);
        operatorStack.head = operatorStack.head->next;
    }

    freeList(&operatorStack);

    return rpnList;
}

// Функции для вычисления значения в польской нотации

double calculateOperator(double operand1, double operand2, char operator) {
    switch (operator) {
        case '+':
            return operand1 + operand2;
        case '-':
            return operand1 - operand2;
        case '*':
            return operand1 * operand2;
        case '/':
            return operand1 / operand2;
        default:
            return 0;
    }
}

double calculateRPN(List rpnList) {
    List operandStack;
    initList(&operandStack);

    ListNode* current = rpnList.head;
    while (current != NULL) {
        if (isOperator(current->expression[0])) {
            double operand2 = operandStack.tail->x;
            double operand1 = 0;
            if (operandStack.tail->prev != NULL) {
                operand1 = operandStack.tail->prev->x;
                operandStack.tail = operandStack.tail->prev;
            }
            double result = calculateOperator(operand1, operand2, current->expression[0]);
            operandStack.tail->x = result;
        } else {
            appendToList(&operandStack, current->expression, atof(current->expression));
        }
        current = current->next;
    }

    double result = operandStack.tail->x;
    freeList(&operandStack);

    return result;
}

// Функции для отрисовки графика

void printGraph(char graph[GRAPH_HEIGHT][GRAPH_WIDTH]) {
    for (int i = 0; i < GRAPH_HEIGHT; i++) {
        for (int j = 0; j < GRAPH_WIDTH; j++) {
            printf("%c", graph[i][j]);
        }
        printf("\n");
    }
}

void initializeGraph(char graph[GRAPH_HEIGHT][GRAPH_WIDTH]) {
    for (int i = 0; i < GRAPH_HEIGHT; i++) {
        for (int j = 0; j < GRAPH_WIDTH; j++) {
            graph[i][j] = EMPTY_CHAR;
        }
    }
}

void plotPoint(char graph[GRAPH_HEIGHT][GRAPH_WIDTH], int x, int y, char ch) {
    int graphX = CENTER_X + x * (GRAPH_WIDTH - 1) / (DOMAIN_END - DOMAIN_START);
    int graphY = CENTER_Y - y * (GRAPH_HEIGHT - 1) / (RANGE_END - RANGE_START);

    if (graphY >= 0 && graphY < GRAPH_HEIGHT && graphX >= 0 && graphX < GRAPH_WIDTH) {
        graph[graphY][graphX] = ch;
    }
}

void plotGraph(char graph[GRAPH_HEIGHT][GRAPH_WIDTH], char* expression) {
    double step = (DOMAIN_END - DOMAIN_START) / (GRAPH_WIDTH - 1);
    for (double x = DOMAIN_START; x <= DOMAIN_END; x += step) {
        double y = calculateRPN(convertToRPN(tokenizeExpression(expression)));
        plotPoint(graph, x, y, GRAPH_CHAR);
    }
}

int main() {
    char expression[] = "sin(cos(2*x))";

    char graph[GRAPH_HEIGHT][GRAPH_WIDTH];
    initializeGraph(graph);
    plotGraph(graph, expression);
    printGraph(graph);

    return 0;
}
```

Программа начинается с разбора строки выражения для получения списка лексем с помощью функции tokenizeExpression. Затем список лексем преобразуется в польскую нотацию с помощью функции convertToRPN. Далее вычисляется значение выражения в польской нотации с помощью функции calculateRPN. Наконец, график функции отрисовывается в терминале с помощью функции plotGraph и выводится с помощью функции printGraph.

