#include<stdio.h>

int fibonacci(int n) {
    if (n <= 1)
        return n;
    return fibonacci(n-1) + fibonacci(n-2);
}

int main() {
    int num_terms, i;

    printf("Enter the number of terms in the Fibonacci series: ");
