package main

import (
	"fmt"
	"net"
	"strings"
)

var clientList []net.Conn

func handleConnection(conn net.Conn) {
	fmt.Println("New client connected:", conn.RemoteAddr().String())
	clientList = append(clientList, conn)

	for {
		buffer := make([]byte, 1024)
		bytesRead, err := conn.Read(buffer)
		if err != nil {
			fmt.Println("Error reading data:", err)
			break
		}

		data := strings.TrimSpace(string(buffer[:bytesRead]))
		if data == "keep alive" {
			fmt.Println("Received keep alive from client:", conn.RemoteAddr().String())
		} else if data == "client count" {
			fmt.Println("Client count:", len(clientList))
		} else {
			fmt.Println("Received command:", data)
			// Handle the commands sent by the clients
			// Add your command processing logic here
		}
	}

	conn.Close()
	clientList = removeClient(conn)
	fmt.Println("Client disconnected:", conn.RemoteAddr().String())
}

func removeClient(conn net.Conn) []net.Conn {
	var updatedList []net.Conn
	for _, client := range clientList {
		if client != conn {
			updatedList = append(updatedList, client)
		}
	}
	return updatedList
}

func main() {
	listener, err := net.Listen("tcp", "localhost:8080")
	if err != nil {
		fmt.Println("Error starting the server:", err)
		return
	}

	defer listener.Close()
	fmt.Println("Server started. Listening on localhost:8080")

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			continue
		}

		go handleConnection(conn)
	}
}
