func keepAlive(conn net.Conn) {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		_, err := conn.Write([]byte("keep alive"))
		if err != nil {
			fmt.Println("Error sending keep alive:", err)
		}
	}
}

func handleCommands(conn net.Conn) {
	for {
		buffer := make([]byte, 1024)
		bytesRead, err := conn.Read(buffer)
		if err != nil {
			fmt.Println("Error reading data:", err)
			os.Exit(1)
		}

		data := string(buffer[:bytesRead])
		fmt.Println("Received command from server:", data)
		// Process the received command here
		// Add your command processing logic here
	}
}

func main() {
	conn, err := net.Dial("tcp", "localhost:8080")
	if err != nil {
		fmt.Println("Error connecting to server:", err)
		return
	}
	defer conn.Close()

	fmt.Println("Connected to server:", conn.RemoteAddr().String())

	go keepAlive(conn)
	handleCommands(conn)
}
