```go
package main

import (
	"fmt"
	"io"
	"net"

	"golang.org/x/crypto/ssh"
)

var clientList map[string]net.Conn

func handleConnection(newChan ssh.NewChannel, newSSHConn ssh.Conn) {
	channel, _, err := newChan.Accept()
	if err != nil {
		fmt.Println("Error accepting channel:", err)
		return
	}

	clientAddr := newSSHConn.RemoteAddr().String()
	clientList[clientAddr] = newSSHConn

	go io.Copy(channel, channel) // Echoes input from the client back to the client

	for {
		buffer := make([]byte, 1024)
		bytesRead, err := channel.Read(buffer)
		if err != nil {
			break
		}

		command := string(buffer[:bytesRead])
		fmt.Printf("Received command from client %s: %s\n", clientAddr, command)
		// Process the command
		switch command {
		case "client count":
			fmt.Printf("Client count: %d\n", len(clientList))
		default:
			fmt.Printf("Invalid command: %s\n", command)
		}
	}

	channel.Close()
	delete(clientList, clientAddr)
	fmt.Printf("Client disconnected: %s\n", clientAddr)
}

func main() {
	config := &ssh.ServerConfig{
		NoClientAuth: true, // All clients are allowed to connect without authentication
	}

	privateKey, err := ssh.ParsePrivateKey([]byte(privateKey)) // Replace "privateKey" with the actual private key content
	if err != nil {
		fmt.Println("Failed to parse private key:", err)
		return
	}
	config.AddHostKey(privateKey)

	listener, err := net.Listen("tcp", "localhost:2222") // SSH server listens on port 2222
	if err != nil {
		fmt.Println("Error starting the server:", err)
		return
	}

	defer listener.Close()
	fmt.Println("Server started. Listening on localhost:2222")

	clientList = make(map[string]net.Conn)

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			continue
		}

		sshConn, _, _, err := ssh.NewServerConn(conn, config)
		if err != nil {
			fmt.Println("Error establishing SSH connection:", err)
			continue
		}

		go handleConnection(sshConn.OpenChannel("session", nil), sshConn)
	}
}
```

