Sure! Here's an example of a client/server pair in Go where the server sends commands via TCP. The clients will connect to the server and send "keep alive" packets. The server will remove dead clients, provide a command to check the client count, and send commands to all connected clients.

Let's start with the server code:

```go
package main

import (
	"bufio"
	"fmt"
	"net"
	"strings"
)

type Client struct {
	conn   net.Conn
	reader *bufio.Reader
}

var clients []*Client

func main() {
	listener, err := net.Listen("tcp", "localhost:1234")
	if err != nil {
		fmt.Println(err)
		return
	}

	fmt.Println("Server started, waiting for clients...")

	go acceptConnections(listener)

	for {
		// Command prompt for server
		reader := bufio.NewReader(os.Stdin)
		fmt.Print("> ")
		command, _ := reader.ReadString('\n')
		command = strings.TrimSpace(command)

		switch command {
		case "clients":
			fmt.Println("Connected clients:", len(clients))
		default:
			sendCommandToClients(command)
		}
	}
}

func acceptConnections(listener net.Listener) {
	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println(err)
			continue
		}

		client := &Client{
			conn:   conn,
			reader: bufio.NewReader(conn),
		}

		clients = append(clients, client)

		go handleClient(client)
	}
}

func handleClient(client *Client) {
	for {
		message, err := client.reader.ReadString('\n')
		if err != nil {
			fmt.Println(err)
			client.conn.Close()
			removeClient(client)
			return
		}

		if strings.TrimSpace(message) == "keep alive" {
			// Handle keep alive packet
			continue
		}

		// Handle command received from client
		fmt.Println("Command received from client:", message)

		// Send response to client if needed
	}
}

func removeClient(client *Client) {
	for i, c := range clients {
		if c == client {
			clients = append(clients[:i], clients[i+1:]...)
			break
		}
	}
}

func sendCommandToClients(command string) {
	for _, client := range clients {
		_, err := client.conn.Write([]byte(command + "\n"))
		if err != nil {
			fmt.Println(err)
			client.conn.Close()
			removeClient(client)
		}
	}
}
```

