You can then start sending commands from the server to the connected clients, and the clients will listen for those commands and execute the desired actions accordingly.

Certainly! Here's an updated version of the server code that uses switch cases to handle different commands:

```go
package main

import (
	"bufio"
	"fmt"
	"net"
	"os"
	"strings"
)

type Client struct {
	conn   net.Conn
	reader *bufio.Reader
}

var clients []*Client

func main() {
	listener, err := net.Listen("tcp", "localhost:1234")
	if err != nil {
		fmt.Println(err)
		return
	}

	fmt.Println("Server started, waiting for clients...")

	go acceptConnections(listener)

	for {
		// Command prompt for server
		reader := bufio.NewReader(os.Stdin)
		fmt.Print("> ")
		command, _ := reader.ReadString('\n')
		command = strings.TrimSpace(command)

		switch command {
		case "clients":
			fmt.Println("Connected clients:", len(clients))
		case "send":
			sendCommandToClients("This is a sample command")
		default:
			fmt.Println("Invalid command")
		}
	}
}

func acceptConnections(listener net.Listener) {
	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println(err)
			continue
		}

		client := &Client{
			conn:   conn,
			reader: bufio.NewReader(conn),
		}

		clients = append(clients, client)

		go handleClient(client)
	}
}

func handleClient(client *Client) {
	for {
		message, err := client.reader.ReadString('\n')
		if err != nil {
			fmt.Println(err)
			client.conn.Close()
			removeClient(client)
			return
		}

		if strings.TrimSpace(message) == "keep alive" {
			// Handle keep alive packet
			continue
		}

		// Handle command received from client
		fmt.Println("Command received from client:", message)

		// Send response to client if needed
	}
}

func removeClient(client *Client) {
	for i, c := range clients {
		if c == client {
			clients = append(clients[:i], clients[i+1:]...)
			break
		}
	}
}

func sendCommandToClients(command string) {
	for _, client := range clients {
		_, err := client.conn.Write([]byte(command + "\n"))
		if err != nil {
			fmt.Println(err)
			client.conn.Close()
			removeClient(client)
		}
	}
}
```

In this updated server code, we've added two sample commands: "clients" and "send". You can modify these commands and add more as needed in the switch case.

When the server receives the "clients" command, it will print the number of connected clients. When it receives the "send" command, it will send the specified sample command ("This is a sample command") to all connected clients.

Feel free to customize the server code according to your requirements and desired commands.

