public void FFT(TComplex[] D, TComplex[] TableExp) {
    int I, J, NChIndex, TableExpIndex, Len, StartIndex, LenBlock, HalfBlock;
    TComplex TempBn;
    Len = D.length;
    LenBlock = 2;
    HalfBlock = 1;
    while (LenBlock <= Len) {
        I = 0;
        NChIndex = HalfBlock;
        StartIndex = 0;
        TableExpIndex = HalfBlock;
        HalfBlock--;
        while (I < Len) {
            for (J = 0; J <= HalfBlock; J++) {
                TempBn = D[NChIndex].multiply(TableExp[TableExpIndex + J]);
                D[NChIndex] = D[StartIndex].subtract(TempBn);
                D[StartIndex] = D[StartIndex].add(TempBn);
                NChIndex++;
                StartIndex++;
            }
            I = I + LenBlock;
            NChIndex = I + HalfBlock + 1;
            StartIndex = I;
        }
        HalfBlock = LenBlock;
        LenBlock = LenBlock << 1;
    }
}
