func encrypt(str string) string {
	// 1. Reverse the string
	reversed := reverseString(str)

	// 2. Apply char map and put it into binary
	encrypted := ""
	for _, char := range reversed {
		encrypted += strconv.FormatInt(int64(charMap(string(char))), 2)
	}

	return encrypted
}

func decrypt(encrypted string) string {
	// 1. Reverse the binary string
	reversedBinary := reverseString(encrypted)

	// 2. Apply reverse char map and reverse the output
	decrypted := ""
	for i := 0; i < len(reversedBinary); i += 7 {
		binaryChar := reversedBinary[i : i+7]
		decrypted += string(reverseCharMap(binaryToDecimal(binaryChar)))
	}

	return reverseString(decrypted)
}

