```go
package main

import (
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"

	"github.com/bwmarrin/discordgo"
)

func main() {
	// Create a new Discord session using the provided bot token
	token := "YOUR_BOT_TOKEN"
	dg, err := discordgo.New("Bot " + token)
	if err != nil {
		fmt.Println("Error creating Discord session:", err)
		return
	}

	// Register messageCreate as the callback for MessageCreate events
	dg.AddHandler(messageCreate)

	// Open a websocket connection to Discord and begin listening
	err = dg.Open()
	if err != nil {
		fmt.Println("Error opening connection:", err)
		return
	}

	// Wait for a termination signal and close the Discord connection properly
	fmt.Println("Bot is now running. Press Ctrl-C to exit.")
	sc := make(chan os.Signal, 1)
	signal.Notify(sc, syscall.SIGINT, syscall.SIGTERM, os.Interrupt, os.Kill)
	<-sc
	dg.Close()
}

func messageCreate(s *discordgo.Session, m *discordgo.MessageCreate) {
	// Ignore messages sent by the bot itself
	if m.Author.ID == s.State.User.ID {
		return
	}

	// Handle the commands based on the message content
	content := strings.ToLower(m.Content)
	switch {
	case strings.HasPrefix(content, "!hello"):
		handleHelloCommand(s, m)
	case strings.HasPrefix(content, "!ping"):
		handlePingCommand(s, m)
	}
}

func handleHelloCommand(s *discordgo.Session, m *discordgo.MessageCreate) {
	// Reply with a hello message
	response := "Hello, " + m.Author.Username + "!"
	_, _ = s.ChannelMessageSend(m.ChannelID, response)
}

func handlePingCommand(s *discordgo.Session, m *discordgo.MessageCreate) {
	// Reply with a pong message
	response := "Pong!"
	_, _ = s.ChannelMessageSend(m.ChannelID, response)
}
