	"fmt"
	"log"
	"net"
	"strings"
	"time"
)

func main() {
	// Start the server on port 8080
	ln, err := net.Listen("tcp", ":8080")
	if err != nil {
		log.Fatal("Error starting the server:", err)
		return
	}
	defer ln.Close()

	log.Println("Server is now running. Listening on port 8080...")

	for {
		// Accept new client connections
		conn, err := ln.Accept()
		if err != nil {
			log.Printf("Error accepting connection: %v\n", err)
			continue
		}

		// Handle incoming client requests concurrently
		go handleConnection(conn)
	}
}

func handleConnection(conn net.Conn) {
	log.Printf("New client connected: %s\n", conn.RemoteAddr().String())

	// Set a read deadline to detect connection timeout
	err := conn.SetReadDeadline(time.Now().Add(10 * time.Second))
	if err != nil {
		log.Printf("Error setting read deadline: %v\n", err)
		conn.Close()
		return
	}

	reader := bufio.NewReader(conn)

	for {
		// Read incoming messages from the client
		msg, err := reader.ReadString('\n')
		if err != nil {
			if strings.Contains(err.Error(), "i/o timeout") {
				// Connection timed out
				log.Printf("Connection timed out: %s\n", conn.RemoteAddr().String())
				break
			}
			log.Printf("Error reading message: %v\n", err)
			break
		}

		msg = strings.TrimSpace(msg)
		log.Printf("Received message from %s: %s\n", conn.RemoteAddr().String(), msg)

		// Process client's keep-alive message
		if msg == "keep-alive" {
			// Reset read deadline
			err = conn.SetReadDeadline(time.Now().Add(10 * time.Second))
			if err != nil {
				log.Printf("Error setting read deadline: %v\n", err)
				break
			}

			// Send command to client
			response := "COMMAND"
			_, err = conn.Write([]byte(response + "\n"))
			if err != nil {
				log.Printf("Error sending message: %v\n", err)
				break
			}
		}
	}

	// Close the connection when done
	conn.Close()
	log.Printf("Connection closed: %s\n", conn.RemoteAddr().String())
}
