Here's an updated version of the Go TCP listener that incorporates TCP keep-alive packets:

```go
package main

import (
	"fmt"
	"log"
	"net"
	"time"
)

const (
	HOST           = "localhost"
	PORT           = 3336
	KeepAliveDelay = 3 * time.Minute // Set the keep-alive interval as per your requirement
)

func handleConnection(conn net.Conn) {
	fmt.Printf("New connection from %s\n", conn.RemoteAddr().String())
	defer conn.Close()

	// Enable TCP keep-alive for the connection
	if tcpConn, ok := conn.(*net.TCPConn); ok {
		tcpConn.SetKeepAlive(true)
		tcpConn.SetKeepAlivePeriod(KeepAliveDelay)
	}

	buffer := make([]byte, 1024)
	for {
		// Set a read deadline based on the keep-alive interval
		conn.SetReadDeadline(time.Now().Add(KeepAliveDelay))

		// Read data from the client
		n, err := conn.Read(buffer)
		if err != nil {
			// Handle read timeout or other read error
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				log.Printf("Connection with %s timed out\n", conn.RemoteAddr().String())
			} else {
				log.Printf("Error reading data: %s\n", err.Error())
			}
			return
		}

		// Print the received data
		fmt.Printf("Received: %s\n", string(buffer[:n]))

		// Break the loop if no more data is received
		if n == 0 {
			break
		}
	}

	fmt.Printf("Connection with %s closed\n", conn.RemoteAddr().String())
}

func main() {
	// Start listening for incoming connections
	listener, err := net.Listen("tcp", fmt.Sprintf("%s:%d", HOST, PORT))
	if err != nil {
		log.Fatalf("Failed to start TCP listener: %s\n", err.Error())
	}
	defer listener.Close()

	fmt.Printf("TCP listener started on port %d...\n", PORT)

	for {
		// Accept a new connection
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("Failed to accept connection: %s\n", err.Error())
			continue
		}

		// Handle the connection in a separate goroutine
		go handleConnection(conn)
	}
}
```

In this updated code, we set TCP keep-alive options using `SetKeepAlive(true)` and `SetKeepAlivePeriod(KeepAliveDelay)` on the `*net.TCPConn` object. This enables TCP keep-alive, and the keep-alive packets will be sent periodically at the specified interval (`KeepAliveDelay`).

By setting a read deadline on the connection using `SetReadDeadline`, we ensure that if no data is received for the duration of the keep-alive interval, the `Read` operation will timeout, allowing us to detect inactivity or broken connections.

With this implementation, the listener will continue to actively check for connectivity with the remote party using keep-alive packets, and appropriate actions can be taken if the connection becomes inactive or broken.

