In TCP, there is no built-in mechanism for keeping connections alive and acknowledging packets. However, you can implement your own keep-alive system using TCP Keep-Alive mechanism or by periodically sending heartbeat packets from the client to the server.

To implement a keep-alive system in Go, you can utilize the `net` package and some added logic. Here's an example that demonstrates how you can achieve this:

TCP Server (Listener):

```go
package main

import (
	"fmt"
	"net"
	"sync"
	"time"
)

type Connection struct {
	conn     net.Conn
	lastSeen time.Time
}

var (
	connections = make(map[string]*Connection)
	lock        sync.Mutex
)

func main() {
	listener, err := net.Listen("tcp", "localhost:8080")
	if err != nil {
		fmt.Println("Error creating listener:", err)
		return
	}
	fmt.Println("TCP listener started on port 8080")

	defer listener.Close()

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			return
		}

		lock.Lock()

		// Store the connection in the map
		connections[conn.RemoteAddr().String()] = &Connection{
			conn:     conn,
			lastSeen: time.Now(),
		}

		lock.Unlock()

		// Start a goroutine to handle the connection
		go handleConnection(conn)
	}
}

func handleConnection(conn net.Conn) {
	buffer := make([]byte, 1024)

	for {
		// Set a read deadline to implement an idle timeout
		conn.SetReadDeadline(time.Now().Add(10 * time.Second))

		// Read data from the connection
		bytesRead, err := conn.Read(buffer)
		if err != nil {
			fmt.Println("Error reading data:", err)

			lock.Lock()

			// Remove connection from the map on error or disconnection
			delete(connections, conn.RemoteAddr().String())

			lock.Unlock()

			conn.Close()
			return
		}

		data := string(buffer[:bytesRead])
		fmt.Println("Received data:", data)

		lock.Lock()

		// Update lastSeen timestamp of connection to keep it alive
		connections[conn.RemoteAddr().String()].lastSeen = time.Now()

		lock.Unlock()
	}
}
```

TCP Client:

```go
