	fmt.Println("TCP listener started on port 8081")

	defer conn.Close()

	for {
		clientConn, err := conn.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err.Error())
			return
		}

		// Start a goroutine to handle receiving and printing data from the server
		go handleServerMessages(clientConn)
	}
}

func handleServerMessages(conn net.Conn) {
	buffer := make([]byte, 1024)

	for {
		// Read the data from the connection
		bytesRead, err := conn.Read(buffer)
		if err != nil {
			fmt.Println("Error reading data:", err.Error())
			return
		}

		// Print the received data
		fmt.Println("Received data:", string(buffer[:bytesRead]))
	}
}
```

