```java
public class FastFourierTransform {

    // Расчет массива exp множителей
    private Complex[] calculateExpMultiplier(int n, boolean inverse) {
        Complex[] expMultiplier = new Complex[n];
        double sign = inverse ? 1 : -1;
        for (int i = 0; i < n; i++) {
            double angle = 2 * Math.PI * i / n;
            expMultiplier[i] = new Complex(Math.cos(angle), sign * Math.sin(angle));
        }
        return expMultiplier;
    }

    // Расчет массива индексов для БПФ
    private int[] calculateIndices(int n) {
        int[] indices = new int[n];
        for (int i = 0; i < n; i++) {
            indices[i] = Integer.reverse(i) >>> (32 - Integer.bitCount(n));
        }
        return indices;
    }

    // Быстрое преобразование Фурье
    public Complex[] fft(Complex[] x, boolean inverse) {
        int n = x.length;
        int[] indices = calculateIndices(n);
        Complex[] expMultiplier = calculateExpMultiplier(n, inverse);

        Complex[] result = new Complex[n];
        System.arraycopy(x, 0, result, 0, n);

        for (int size = 1; size < n; size *= 2) {
            for (int i = 0; i < n; i += 2 * size) {
                for (int j = 0; j < size; j++) {
                    Complex oddTermMultiplier = result[i + j + size].multiply(expMultiplier[indices[j + size]]);
                    result[i + j + size] = result[i + j].subtract(oddTermMultiplier);
                    result[i + j] = result[i + j].add(oddTermMultiplier);
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                result[i] = result[i].divide(n);
            }
        }

        return result;
    }
}
