```java
public class FastFourierTransform {

    // Преобразование Фурье
    public Complex[] fft(Complex[] x, boolean inverse) {
        int n = x.length;
        int[] indices = calculateIndices(n);
        Complex[] result = calculateFFT(x, indices, inverse);
        if (inverse) {
            for (int i = 0; i < n; i++) {
                result[i] = result[i].divide(n);
            }
        }
        return result;
    }

    // Расчет массива индексов для БПФ
    private int[] calculateIndices(int n) {
        int[] indices = new int[n];
        for (int i = 0; i < n; i++) {
            indices[i] = Integer.reverse(i) >>> (32 - Integer.bitCount(n));
        }
        return indices;
    }

    // Выполнение Быстрого преобразования Фурье рекурсивно
    private Complex[] calculateFFT(Complex[] x, int[] indices, boolean inverse) {
        int n = x.length;

        if (n == 1) {
            return x;
        }

        Complex[] even = new Complex[n / 2];
        Complex[] odd = new Complex[n / 2];

        for (int i = 0; i < n / 2; i++) {
            int evenIndex = indices[2 * i];
            int oddIndex = indices[2 * i + 1];
            even[i] = x[evenIndex];
            odd[i] = x[oddIndex];
        }

        Complex[] evenResult = calculateFFT(even, indices, inverse);
        Complex[] oddResult = calculateFFT(odd, indices, inverse);

        Complex[] result = new Complex[n];
        Complex expMultiplier = new Complex(Math.cos(2 * Math.PI / n), Math.sin(2 * Math.PI / n));
        Complex current = new Complex(1, 0);

        for (int i = 0; i < n / 2; i++) {
            result[i] = evenResult[i].add(current.multiply(oddResult[i]));
            result[i + n / 2] = evenResult[i].subtract(current.multiply(oddResult[i]));
            if (inverse) {
                result[i] = result[i].divide(2);
                result[i + n / 2] = result[i + n / 2].divide(2);
            }
            current = current.multiply(expMultiplier);
        }

        return result;
    }
}
