```javascript
const multer = require('multer');

// Configure storage options for Multer
const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, 'uploads/') // Specify the directory where files will be saved
  },
  filename: function (req, file, cb) {
    cb(null, Date.now() + '-' + file.originalname) // Rename the uploaded file
  }
});

// Define file filter function to only allow CSV files
const fileFilter = function (req, file, cb) {
  // Accept only CSV files
  if (file.mimetype === 'text/csv') {
    cb(null, true);
  } else {
    cb(new Error('Only CSV files are allowed'), false);
  }
};

// Create the Multer middleware instance
const upload = multer({ storage: storage, fileFilter: fileFilter });

module.exports = upload;
```

In this code, we configure Multer to use a disk storage engine and specify the destination folder where the files will be saved. We also provide a filename function to rename the uploaded file. Additionally, we define a fileFilter function that checks if the uploaded file has a `text/csv` mimetype. If it doesn't match, an error is passed to the callback.

