```javascript
const multer = require('multer');
const csv = require('csv-parser');

// Multer middleware for handling CSV files
const upload = multer({ storage: multer.memoryStorage() }).single('csvFile');

// Express route handler for processing uploaded CSV file
function processCSV(req, res) {
  upload(req, res, (err) => {
    if (err) {
      return res.status(400).json({ error: err.message });
    }

    if (!req.file || !req.file.buffer) {
      return res.status(400).json({ error: 'No CSV file uploaded' });
    }

    const csvResults = [];

    // Process the CSV in memory
    csv.parse(req.file.buffer)
      .on('error', (error) => {
        return res.status(500).json({ error: 'Failed to process CSV file' });
      })
      .on('data', (row) => {
        csvResults.push(row);
      })
      .on('end', () => {
        // Do something with the parsed CSV data
        console.log(csvResults);

        return res.status(200).json({ success: 'CSV file processed successfully' });
      });
  });
}

module.exports = processCSV;
```

