const handleCheckClick = () => {
  const orderQuantity: PreparedOrderQuantity = { quantity: quantitySelected, unit: volumeAsDollarsCheck ? "usd" : "coin" };

  const savedQuantities = localStorage.getItem("preparedQuantities");

  if (savedQuantities) {
    const parsedQuantities = JSON.parse(savedQuantities);
    if (parsedQuantities.hasOwnProperty(symbol)) {
      const existingQuantities = parsedQuantities[symbol];
      const existingOrderQuantity = existingQuantities.find((quantity: PreparedOrderQuantity) => 
        quantity.quantity === orderQuantity.quantity && quantity.unit === orderQuantity.unit);

      if (existingOrderQuantity) {
        // orderQuantity уже существует в preparedQuantities, ничего не делаем
        return;
      } else {
        // добавляем orderQuantity в existingQuantities
        existingQuantities.push(orderQuantity);

        // обновляем preparedQuantities в localStorage
        localStorage.setItem("preparedQuantities", JSON.stringify(parsedQuantities));
      }
    } else {
      // символ не найден в preparedQuantities, добавляем его с orderQuantity
      parsedQuantities[symbol] = [orderQuantity];
      localStorage.setItem("preparedQuantities", JSON.stringify(parsedQuantities));
    }
  } else {
    // нет ранее сохраненных preparedQuantities, создаем новый объект и добавляем в localStorage
    const newQuantities = { [symbol]: [orderQuantity] };
    localStorage.setItem("preparedQuantities", JSON.stringify(newQuantities));
  }

  dispatch(addPreparedQuantity({
    key: symbol,
    quantity: orderQuantity,
  }));

  setQuantity(orderQuantity);
  setShowQuantitySettings(false);
  setVolumeAsDollars(volumeAsDollarsCheck);
};
