void createIndirectContext() {
    display = XOpenDisplay(NULL);  // Open the display
    if (!display) {
        printf("Error: unable to open X display.\n");
        exit(1);
    }

    Window root = DefaultRootWindow(display);  // Get the root window

    // Set up attributes for the OpenGL visual
    static int visualAttributes[] = {
        GLX_RGBA,
        GLX_DOUBLEBUFFER,
        GLX_DEPTH_SIZE, 24,
        None
    };

    XVisualInfo* visualInfo = glXChooseVisual(display, 0, visualAttributes);  // Choose a visual
    if (!visualInfo) {
        printf("Error: failed to find a suitable visual.\n");
        exit(1);
    }

    colormap = XCreateColormap(display, root, visualInfo->visual, AllocNone);  // Create a colormap

    XSetWindowAttributes windowAttributes;
    windowAttributes.colormap = colormap;
    windowAttributes.event_mask = ExposureMask | KeyPressMask;  // Set the event mask

    window = XCreateWindow(display, root, 0, 0, 800, 600, 0, visualInfo->depth, InputOutput, visualInfo->visual, CWColormap | CWEventMask, &windowAttributes);  // Create the window

    XMapWindow(display, window);  // Map the window to the screen

    glxContext = glXCreateContext(display, visualInfo, NULL, GL_TRUE);  // Create an OpenGL context
    glXMakeCurrent(display, window, glxContext);  // Make the context current
}

void destroyIndirectContext() {
    glXDestroyContext(display, glxContext);  // Destroy the OpenGL context
    XDestroyWindow(display, window);  // Destroy the window
