    glLoadIdentity();
    gluLookAt(0.0, 0.0, 5.0,  // Camera position
              0.0, 0.0, 0.0,  // Look at point
              0.0, 1.0, 0.0);  // Up direction

    // Render 3D objects here
    glColor3f(1.0, 1.0, 1.0);  // Set color to white
    glutWireSphere(1.0, 20, 20);  // Render a wireframe sphere

    glFlush();  // Flush drawing commands
    glXSwapBuffers(display, window);  // Swap the buffers
}

void reshape(int width, int height) {
    glViewport(0, 0, width, height);  // Set the viewport dimensions
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluPerspective(45.0, (double)width / height, 1.0, 100.0);  // Set perspective projection
}

int main(int argc, char** argv) {
