// Sample class representing an item with field X and probability
class Item
{
    public int FieldX { get; set; }
    public double Probability { get; set; }
}

// Sample list of items
List<Item> items = new List<Item>
{
    new Item { FieldX = 5, Probability = 0.2 },
    new Item { FieldX = 10, Probability = 0.8 },
    new Item { FieldX = 3, Probability = 0.5 },
    new Item { FieldX = 8, Probability = 0.3 }
};

// Order the list based on field X with probabilities
var orderedItems = items.OrderByDescending(item => item.Probability).ThenBy(item => item.FieldX);

// Print the ordered list
foreach (var item in orderedItems)
{
    Console.WriteLine($"FieldX: {item.FieldX}, Probability: {item.Probability}");
}
```

