To create a new table to display the data, you can use the `<table>` HTML element and its related tags (`<thead>`, `<tbody>`, `<tr>`, `<th>`, `<td>`). Here's an example of how you can modify the code to create the table:

1. Import the required React and HTML elements:
```javascript
import React, { useState, useEffect } from 'react';
```

2. Add a new state variable to store the big orders data:
```javascript
const [bigOrders, setBigOrders] = useState<any[]>([]);
```

3. Update the `Cup` component to subscribe to the big orders WebSocket connection and handle the received data:
```javascript
const Cup = ({ workerRef, symbol }: CupProps) => {
  // ...

  useEffect(() => {
    // ...

    const handleBigOrder = (bigOrder: any) => {
      const tradeSymbol = bigOrder.BigOrder.exchange.replace("FT:", "").toUpperCase();

      if (tradeSymbol === symbol) {
        const updatedBigOrders = [...bigOrders, bigOrder];
        setBigOrders(updatedBigOrders);
      }
    };

    const subscribeToBigOrders = () => {
      workerRef.current?.postMessage(JSON.stringify({ type: "subscribe_big_orders", symbol }));
    };

    const unsubscribeFromBigOrders = () => {
      workerRef.current?.postMessage(JSON.stringify({ type: "unsubscribe_big_orders" }));
    };

    workerRef.current?.addEventListener("message", (event: MessageEvent<any>) => {
      const data = JSON.parse(event.data);

      if (data.type === "big_order") {
        handleBigOrder(data.big_order);
      }
    });

    subscribeToBigOrders();

    return () => {
      unsubscribeFromBigOrders();
      workerRef.current?.removeEventListener("message", handleBigOrder);
    };
  }, [symbol]);

  // ...

  return (
    <div>
      {/* Render the table */}
      <table>
        <thead>
          <tr>
            <th>Symbol</th>
            <th>Price</th>
            <th>Quantity</th>
          </tr>
        </thead>
        <tbody>
          {bigOrders.map((order, index) => (
            <tr key={index}>
              <td>{order.BigOrder.exchange}</td>
              <td>{order.BigOrder.price}</td>
              <td>{order.BigOrder.quantity}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {/* ... */}
    </div>
  );
};

export default Cup;
```

