function extractXML($url) {
    $xmlContent = file_get_contents($url);
    $xmlDoc = new DOMDocument();
    $xmlDoc->loadXML($xmlContent);
    $imgURL = $xmlDoc->getElementsByTagName("url")[0]->nodeValue;
    openURL($imgURL);
