```csharp
private void CloseWindowIfItItemContainer(int itemContainerInstanceID)
{
    if (!inventoryItemService.TryGetItemTableInventoryItem(itemContainerInstanceID, out ItemTable itemTable) ||
        !(itemTable.InventoryMetadata is ContainerMetadata containerMetadata))
    {
        return;
    }

    CloseWindow(itemTable);

    foreach (var gridTable in containerMetadata.GridsInventory)
    {
        foreach (var itemTableInContainer in gridTable.GetAllItemsFromGrid())
        {
            CloseWindowRecursive(itemTableInContainer);
        }
    }
}

private void CloseWindowRecursive(ItemTable itemTable)
{
    if (itemTable.InventoryMetadata is ContainerMetadata containerMetadata)
    {
        CloseWindow(itemTable);

        foreach (var gridTable in containerMetadata.GridsInventory)
        {
            foreach (var itemTableInContainer in gridTable.GetAllItemsFromGrid())
            {
                CloseWindowRecursive(itemTableInContainer);
            }
        }
    }
    else
    {
        CloseWindow(itemTable);
    }
}

private void CloseWindow(ItemTable itemTable)
{
    windowContainerChangeStateEventChannelSo.RaiseEvent(itemTable, WindowUpdateState.Close);
}
```

В данном коде мы используем рекурсивную функцию `CloseWindowRecursive`, которая проверяет, является ли предмет контейнером, и, если да, то рекурсивно вызывает себя для обработки вложенных контейнеров. Это позволяет избежать повторного кода и сократить количество итераций циклов.

