#include <esp_now.h>

void onDataReceived(const uint8_t *mac, const uint8_t *data, int len) {
  // Forward the received data to the I2C bus
  Wire.beginTransmission(I2C_ADDRESS);
  for (int i = 0; i < len; i++) {
    Wire.write(data[i]);
  }
  Wire.endTransmission();
}

void setup() {
  Wire.begin(I2C_ADDRESS); // Set the receiver's I2C address
  Wire.onReceive([](int) { 
    while (Wire.available()) {
      // Read and discard received data to keep I2C bus buffers clear
      Wire.read();
    }
  });

  esp_now_init();
  esp_now_register_recv_cb(onDataReceived);
}

void loop() {
  // Any additional logic can be added here
}
```

