#define DATA_LENGTH 32
#define DELAY_MS 1000

void onDataReceived(const uint8_t *mac, const uint8_t *data, int len) {
  // Forward the received data to the I2C bus
  Wire.beginTransmission(I2C_ADDRESS);
  for (int i = 0; i < len; i++) {
    Wire.write(data[i]);
  }
  Wire.endTransmission();
}

void setup() {
  Wire.begin(); // Start the transmitter's I2C bus

  if(esp_now_init() != ESP_OK) {
    Serial.println("Error initializing ESP-NOW");
    return;
  }

  esp_now_register_send_cb([](const uint8_t*, esp_now_send_status_t) {});
}

void loop() {
  // Read data from the I2C bus
  Wire.requestFrom(I2C_ADDRESS, DATA_LENGTH);
  uint8_t data[DATA_LENGTH];
  uint8_t dataLen = 0;
  while (Wire.available()) {
    data[dataLen++] = Wire.read();
