Here's an example of P5.js code that emulates a simple version of Doom using basic shapes:

```javascript
// Define player variables
let playerX;
let playerY;
let playerAngle;
let playerSpeed;

// Define enemy variables
let enemyX;
let enemyY;

function setup() {
  createCanvas(800, 400);

  // Initialize player variables
  playerX = width / 2;
  playerY = height / 2;
  playerAngle = 0;
  playerSpeed = 3;

  // Initialize enemy variables
  enemyX = random(width);
  enemyY = random(height);
}

function draw() {
  background(0);

  // Move and draw the player
  movePlayer();
  drawPlayer();

  // Move and draw the enemy
  moveEnemy();
  drawEnemy();

  // Detect collision between player and enemy
  if (checkCollision(playerX, playerY, enemyX, enemyY)) {
    endGame();
  }
}

// Move player based on input
function movePlayer() {
  if (keyIsDown(LEFT_ARROW)) {
    playerAngle -= 0.1;
  }
  if (keyIsDown(RIGHT_ARROW)) {
    playerAngle += 0.1;
  }
  if (keyIsDown(UP_ARROW)) {
    playerX += playerSpeed * cos(playerAngle);
    playerY += playerSpeed * sin(playerAngle);
  }
  if (keyIsDown(DOWN_ARROW)) {
    playerX -= playerSpeed * cos(playerAngle);
    playerY -= playerSpeed * sin(playerAngle);
  }
}

// Draw the player as a triangle
function drawPlayer() {
  push();
  translate(playerX, playerY);
  rotate(playerAngle + PI / 2);
  fill(255);
  triangle(-10, 15, 10, 15, 0, -15);
  pop();
}

// Move enemy randomly
function moveEnemy() {
  enemyX += random(-3, 3);
  enemyY += random(-3, 3);
}

// Draw the enemy as a square
function drawEnemy() {
  fill(255, 0, 0);
  rect(enemyX, enemyY, 20, 20);
}

// Check collision between two circles
function checkCollision(x1, y1, x2, y2) {
  let distance = dist(x1, y1, x2, y2);
  return distance < 15;
}

// Game over logic
function endGame() {
  noLoop(); // Stop game loop
  background(255, 0, 0); // Show red background
  textSize(32);
  fill(255);
  textAlign(CENTER, CENTER);
  text("Game Over", width / 2, height / 2);
}
```

In this code, we define the player and enemy variables and initialize their positions. The `setup()` function sets up the canvas, and the `draw()` function is called repeatedly to update the game state and redraw everything on the screen.

The `movePlayer()` function moves the player based on keyboard input, and the `drawPlayer()` function draws the player as a triangle. Similarly, the `moveEnemy()` function moves the enemy randomly and the `drawEnemy()` function draws the enemy as a square.

The `checkCollision()` function checks if the player and enemy collide. In this case, we consider them as circles with a radius of 15. If a collision is detected, the `endGame()` function is called to stop the game loop and display a "Game Over" message.

