4. Set up the ESP-NOW sender and receiver:

```cpp
struct __attribute__((packed)) DataPacket {
  uint32_t counter;
};

DataPacket receivedData;

void OnDataRecv(const uint8_t *mac_addr, const uint8_t *data, int data_len) {
  memcpy(&receivedData, data, sizeof(receivedData));
  Serial.print("Received data: ");
  Serial.println(receivedData.counter);
}

void sendData() {
  static uint32_t counter = 0;
  DataPacket data;
  data.counter = counter;

  esp_now_send(NULL, (const uint8_t *)&data, sizeof(data));
  Serial.print("Sent data: ");
  Serial.println(counter);

  counter++;
}

void setup() {
  Serial.begin(115200);

  // Initialize I2C communication for OLED display
  Wire.begin();
  display.begin(SSD1306_SWITCHCAPVCC, I2C_DEV_ADDR);

  esp_err_t result = esp_now_init();
  if (result != ESP_OK) {
    Serial.println("Error initializing ESP-NOW");
    return;
  }

  esp_now_register_recv_cb(OnDataRecv);

  // Set up WiFi mode and channel
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  uint8_t broadcastAddress[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};
  esp_now_peer_info_t peerInfo;
  memcpy(peerInfo.peer_addr, broadcastAddress, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;

  // Add the peer to ESP-NOW
  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Failed to add peer");
    return;
  }

  // Start sending data every second
  setInterval(1000, sendData);
}

void loop() {
  esp_now_poll();
  displayData();
}

