To create an API using C#, you can make use of the ASP.NET Core framework. Here is a simple step-by-step guide with examples:

Step 1: Create a new ASP.NET Core Web API project in Visual Studio.

Step 2: Define the model or data structure for your API.

```csharp
public class Book
{
    public int Id { get; set; }
    public string Title { get; set; }
    public string Author { get; set; }
}
```

Step 3: Define a controller to handle API requests and responses.

```csharp
[ApiController]
[Route("api/[controller]")]
public class BooksController : ControllerBase
{
    private List<Book> books = new List<Book>
    {
        new Book { Id = 1, Title = "Book 1", Author = "Author 1" },
        new Book { Id = 2, Title = "Book 2", Author = "Author 2" },
        new Book { Id = 3, Title = "Book 3", Author = "Author 3" }
    };

    [HttpGet]
    public IActionResult GetAllBooks()
    {
        return Ok(books);
    }

    [HttpGet("{id}")]
    public IActionResult GetBookById(int id)
    {
        var book = books.FirstOrDefault(b => b.Id == id);
        if (book == null)
            return NotFound();
        return Ok(book);
    }

    [HttpPost]
    public IActionResult AddBook([FromBody] Book book)
    {
        books.Add(book);
        return CreatedAtAction(nameof(GetBookById), new { id = book.Id }, book);
    }

    [HttpPut("{id}")]
    public IActionResult UpdateBook(int id, [FromBody] Book book)
    {
        var existingBook = books.FirstOrDefault(b => b.Id == id);
        if (existingBook == null)
            return NotFound();
        existingBook.Title = book.Title;
        existingBook.Author = book.Author;
        return NoContent();
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteBook(int id)
    {
        var book = books.FirstOrDefault(b => b.Id == id);
        if (book == null)
            return NotFound();
        books.Remove(book);
        return NoContent();
    }
}
```

