        <div id="gallery"></div>
        <button id="updateButton" onclick="manualUpdate()">Manual Update</button>
        <label for="autoUpdate">Auto-Update:</label>
        <input type="checkbox" id="autoUpdate" onchange="toggleAutoUpdate()" />
    </div>

