#include <iostream>
#include <arrayfire.h>

using namespace af;

// Compute the frequency representation of the input image
array computeSpectrum(const array& input) {
    array img = cast<float>(input);
    array imgFFT = fftR2C<2>(img, 0.0);
    return imgFFT;
}

// Compute the inverse Fourier transform of the frequency representation
array computeInverseSpectrum(const array& spectrum) {
    array imgIFFT = fftC2R<2>(spectrum, 0.0);
    return imgIFFT;
}

// Perform periodic plus smooth image decomposition
std::array<array, 2> psDecomposition(const array& input, float lambda, int numIterations) {
    // Compute the FFT of the input image
    array spectrum = computeSpectrum(input);

    // Initialize the periodic and smooth components
    array periodic = constant(0, input.dims());
    array smooth = constant(0, input.dims());

    // Perform alternating projections
    for (int i = 0; i < numIterations; i++) {
        // Calculate the residual between input and smooth components
        array residual = input - smooth;

        // Compute FFT of the residual
        array residualFFT = computeSpectrum(residual);

        // Compute the new periodic component
        array oldPeriodic = periodic.copy();
        periodic = computeInverseSpectrum(spectrum + residualFFT);

        // Compute the new smooth component
        array oldSmooth = smooth.copy();
        array difference = input - periodic;
        smooth = max(difference, -lambda) + min(difference, lambda);

        // Check convergence by measuring change in periodic and smooth components
        float periodicDiff = max<float>(abs(periodic - oldPeriodic));
        float smoothDiff = max<float>(abs(smooth - oldSmooth));

        if (periodicDiff < 1e-4 && smoothDiff < 1e-4) {
            std::cout << "Converged after " << i + 1 << " iterations." << std::endl;
            break;
        }
    }

    return {periodic, smooth};
}

