    std::array<array, 2> decomposition = psDecomposition(input, 40.0f, 100);

    // Save the periodic and smooth components as PGM files
    saveImage("periodic.pgm", decomposition[0]);
    saveImage("smooth.pgm", decomposition[1]);

    return 0;
}
