using System;
using System.Speech.Synthesis;
using System.Speech.Recognition;
using System.Windows.Forms;

namespace BonziAssistant
{
    public partial class MainForm : Form
    {
        private SpeechSynthesizer synthesizer;
        private SpeechRecognitionEngine recognizer;

        public MainForm()
        {
            InitializeComponent();
            InitializeAssistant();
        }

        private void InitializeAssistant()
        {
            synthesizer = new SpeechSynthesizer();
            recognizer = new SpeechRecognitionEngine();

            // Add commands or grammar rules
            Choices commands = new Choices();
            commands.Add(new string[] { "hello", "what's your name", "how are you" });

            GrammarBuilder grammarBuilder = new GrammarBuilder();
            grammarBuilder.Append(commands);

            Grammar grammar = new Grammar(grammarBuilder);

            recognizer.LoadGrammar(grammar);
            recognizer.SpeechRecognized += Recognizer_SpeechRecognized;
            recognizer.SetInputToDefaultAudioDevice();
            recognizer.RecognizeAsync(RecognizeMode.Multiple);
        }

        private void Recognizer_SpeechRecognized(object sender, SpeechRecognizedEventArgs e)
        {
            string spokenText = e.Result.Text.ToLower();

            if (spokenText.Contains("hello"))
            {
                Speak("Hello! How can I assist you?");
            }
            else if (spokenText.Contains("what's your name"))
            {
                Speak("I am Bonzi, your personal desktop assistant.");
            }
            else if (spokenText.Contains("how are you"))
            {
                Speak("I am doing great, thank you for asking!");
            }
        }

        private void Speak(string text)
        {
            synthesizer.Speak(text);
        }
    }
}
