#include <iostream>
#include <vector>

bool canObtainWinningSequence(const std::vector<int>& joeSequence, const std::vector<int>& winningSequence) {
    int n = joeSequence.size();
    int l = 0, r = 0;

    while (l < n && joeSequence[l] == winningSequence[l]) {
        l++;
    }

    while (r < n && joeSequence[n - r - 1] == winningSequence[n - r - 1]) {
        r++;
    }

    if (l >= n || r >= n) {
        return true;
    }

    if (joeSequence[l] <= winningSequence[n - r - 1] && joeSequence[n - r - 1] <= winningSequence[l]) {
        return true;
    } else {
        return false;
    }
}

