To optimize the performance and prevent the overheating issue caused by continuous looping and redrawing of images in the handleResize() function, you can make the following changes to debounce the function calls:

1. Add a flag `isResizing` to prevent multiple concurrent calls to the handleResize() function:
```javascript
let isResizing = false;
```

2. Modify the handleResize() function to handle the resizing logic within a requestAnimationFrame() callback to debounce the function calls:
```javascript
function handleResize() {
  if (isResizing) return;
  isResizing = true;

  requestAnimationFrame(() => {
    const container = document.querySelector('.canvas-container');
    const canvas = document.getElementById('imageCanvas');
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;
    const aspectRatio = canvas.width / canvas.height;

    let canvasWidth = containerWidth;
    let canvasHeight = containerWidth / aspectRatio;
    if (canvasHeight > containerHeight) {
      canvasHeight = containerHeight;
      canvasWidth = canvasHeight * aspectRatio;
    }

    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    galleryArray.forEach((image) => {
      const imageWidth = image.naturalWidth;
      const imageHeight = image.naturalHeight;
      const aspectRatio = imageWidth / imageHeight;

      let canvasImageWidth = canvasWidth;
      let canvasImageHeight = canvasWidth / aspectRatio;
      if (canvasImageHeight > canvasHeight) {
        canvasImageHeight = canvasHeight;
        canvasImageWidth = canvasHeight * aspectRatio;
      }

      const x = (canvas.width - canvasImageWidth) / 2;
      const y = (canvas.height - canvasImageHeight) / 2;
      ctx.drawImage(image, x, y, canvasImageWidth, canvasImageHeight);
    });

    isResizing = false;
  });
}

document.addEventListener('DOMContentLoaded', function() {
  handleResize();
});
```

By adding the `isResizing` flag, you ensure that only one instance of the handleResize() function can run at a time. Additionally, using the requestAnimationFrame() callback ensures that the function is only called once per frame, reducing unnecessary function calls during rapid resizing events.

