using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class SnakeController : MonoBehaviour
{
    public GameObject segmentPrefab;
    public int numSegments = 5;
    public float segmentDistance = 0.3f;
    public float movementSpeed = 5f;

    private List<Transform> segments = new List<Transform>();

    private void Start()
    {
        // Create the initial segments of the snake
        for (int i = 0; i < numSegments; i++)
        {
            AddSegment();
        }
    }

    private void Update()
    {
        // Get the mouse position in the world
        Vector3 mousePos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mousePos.z = 0f;

        // Rotate the head segment towards the mouse position
        Transform headSegment = segments[0];
        Vector3 direction = mousePos - headSegment.position;
        float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
        headSegment.rotation = Quaternion.AngleAxis(angle, Vector3.forward);

        // Move the head segment towards the mouse position
        headSegment.position = Vector3.MoveTowards(headSegment.position, mousePos, movementSpeed * Time.deltaTime);

        // Update the position of each segment in relation to the previous segment
        for (int i = 1; i < segments.Count; i++)
        {
            Transform currentSegment = segments[i];
            Transform previousSegment = segments[i - 1];

            // Calculate the target position for the current segment
            Vector3 targetPos = previousSegment.position - (previousSegment.up * segmentDistance);
            currentSegment.position = Vector3.MoveTowards(currentSegment.position, targetPos, movementSpeed * Time.deltaTime);
        }
    }

    private void AddSegment()
    {
        // Create a new segment
        GameObject segment = Instantiate(segmentPrefab, transform.position, Quaternion.identity);
        segments.Add(segment.transform);

        // Set the parent of the segment to this snake controller
        segment.transform.parent = transform;

        // Calculate the position of the new segment
        int numSegments = segments.Count;
        Vector3 position = transform.position - (transform.up * segmentDistance * numSegments);
        segment.transform.position = position;
    }
}
