Here is the code for the CastingOverloading class with the specified methods:

```java
public class CastingOverloading {
    public static int oneOrZero() {
        return (int) (Math.random() * 2); // Casting the result of Math.random() to int will give 0 or 1
    }

    public static int zeroTo99I() {
        return (int) (Math.random() * 100); // Casting the result of Math.random() to int will give a random integer between 0 and 99
    }

    public static double zeroTo99D() {
        return Math.random() * 100.0; // Math.random() returns a random double between 0.0 and 1.0, multiplying it by 100.0 gives a random double between 0.0 and 99.9
    }

    public static int zeroToN(int n) {
        return (int) (Math.random() * (n + 1)); // Casting the result of Math.random() * (n + 1) to int will give a random integer between 0 and n
    }

    public static double zeroToN(double n) {
        return Math.random() * n; // Math.random() * n returns a random double between 0.0 and n
    }

    public static int minToMax(int min, int max) {
        return (int) (Math.random() * (max - min) + min); // Casting the result of Math.random() * (max - min) + min to int will give a random integer between min and max (exclusive)
    }

    public static double minToMax(double min, double max) {
        return Math.random() * (max - min) + min; // Math.random() * (max - min) + min returns a random double between min and max (exclusive)
    }
}
