using System.IO.Compression;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        // Set the file name and destination path
        string fileName = "compressedFile.zip";
        string destinationPath = "extractedFiles";

        // Get the compressed file stream from the program resources
        using (Stream compressedFileStream = typeof(Program).Assembly.GetManifestResourceStream(fileName))
        {
            // Create the destination directory if it doesn't exist
            if (!Directory.Exists(destinationPath))
                Directory.CreateDirectory(destinationPath);

            // Decompress each entry in the compressed file asynchronously
            using (ZipArchive archive = new ZipArchive(compressedFileStream, ZipArchiveMode.Read))
            {
                foreach (ZipArchiveEntry entry in archive.Entries)
                {
                    string entryDestinationPath = Path.Combine(destinationPath, entry.FullName);
                    await DecompressEntryAsync(entry, entryDestinationPath);
                }
            }
        }

        Console.WriteLine("Decompression completed!");
    }

    static async Task DecompressEntryAsync(ZipArchiveEntry entry, string destinationPath)
    {
        // Create the destination directory if it doesn't exist
        Directory.CreateDirectory(Path.GetDirectoryName(destinationPath));

        // Open the entry stream asynchronously
        using (Stream entryStream = entry.Open())
        {
            // Create and open the destination file asynchronously
            using (FileStream destinationStream = File.Open(destinationPath, FileMode.Create))
            {
                // Copy the entry stream to the destination file asynchronously
                await entryStream.CopyToAsync(destinationStream);
            }
        }
    }
}
