    }
}

void Resolver::getEvent(GameEvent* event) noexcept
{
    if (!event || !localPlayer || interfaces->engine->isHLTV())
        return;

    const std::string eventName = event->getName();
    const int attackerUserID = event->getInt("attacker");
    const int playerUserID = localPlayer->getUserId();

    if (eventName == "round_start")
    {
        // Reset all players' misses and clear snapshots
        auto players = Animations::setPlayers();
        if (players->empty())
            return;

        for (auto& player : *players)
        {
            player.misses = 0;
        }

        snapshots.clear();
    }
    else if (eventName == "player_death")
    {
        // Reset player's misses based on userID
        const int userID = event->getInt("userid");
        if (userID == playerUserID)
            return;

        const int index = interfaces->engine->getPlayerForUserID(userID);
        Animations::setPlayer(index)->misses = 0;
    }
    else if (eventName == "player_hurt")
    {
        if (snapshots.empty())
            return;

        if (attackerUserID != playerUserID)
            return;

        const int hitGroup = event->getInt("hitgroup");
        if (hitGroup < HitGroup::Generic || hitGroup > HitGroup::RightLeg)
            return;

        snapshots.pop_front(); // Hit somebody, so don't calculate
    }
    else if (eventName == "bullet_impact")
    {
        if (snapshots.empty())
            return;

        if (event->getInt("userid") != playerUserID)
