```csharp
private void dataGridView1_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
{
    if (dataGridView1.Columns[e.ColumnIndex] is DataGridViewCheckBoxColumn && e.RowIndex >= 0)
    {
        e.Paint(e.CellBounds, DataGridViewPaintParts.All);

        var checkbox = new CheckBox();
        checkbox.Size = new Size(14, 14);
        checkbox.Location = new Point(e.CellBounds.X + (e.CellBounds.Width - checkbox.Size.Width) / 2, e.CellBounds.Y + (e.CellBounds.Height - checkbox.Size.Height) / 2);

        checkbox.Checked = (bool)e.Value;
        checkbox.Enabled = dataGridView1.Rows[e.RowIndex].Cells[e.ColumnIndex].ReadOnly ? false : true;

        using (var bmp = new Bitmap(e.CellBounds.Width, e.CellBounds.Height))
        {
            checkbox.DrawToBitmap(bmp, new Rectangle(0, 0, checkbox.Width, checkbox.Height));

            e.Graphics.DrawImage(bmp, new Point(e.CellBounds.X, e.CellBounds.Y));
        }

        e.Handled = true;
    }
}
