class Program
{
    static void Main()
    {
        string sourceFolder = "C:\\path\\to\\sourceFolder";
        string destinationFolder = "C:\\path\\to\\destinationFolder";

        try
        {
            // Create the destination folder if it doesn't exist
            if (!Directory.Exists(destinationFolder))
            {
                Directory.CreateDirectory(destinationFolder);
            }

            // Copy files
            foreach (string filePath in Directory.GetFiles(sourceFolder))
            {
                string fileName = Path.GetFileName(filePath);
                string destinationPath = Path.Combine(destinationFolder, fileName);
                File.Copy(filePath, destinationPath);
            }

            // Copy sub-folders recursively
            foreach (string subDirectoryPath in Directory.GetDirectories(sourceFolder))
            {
                string subDirectoryName = Path.GetFileName(subDirectoryPath);
                string destinationPath = Path.Combine(destinationFolder, subDirectoryName);
                CopyFolder(subDirectoryPath, destinationPath);
            }

            Console.WriteLine("Folder copied successfully.");
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }

    static void CopyFolder(string sourceFolder, string destinationFolder)
    {
        // Create the destination folder if it doesn't exist
        if (!Directory.Exists(destinationFolder))
        {
            Directory.CreateDirectory(destinationFolder);
        }

        // Copy files
        foreach (string filePath in Directory.GetFiles(sourceFolder))
        {
            string fileName = Path.GetFileName(filePath);
            string destinationPath = Path.Combine(destinationFolder, fileName);
            File.Copy(filePath, destinationPath);
        }

        // Copy sub-folders recursively
        foreach (string subDirectoryPath in Directory.GetDirectories(sourceFolder))
        {
            string subDirectoryName = Path.GetFileName(subDirectoryPath);
            string destinationPath = Path.Combine(destinationFolder, subDirectoryName);
            CopyFolder(subDirectoryPath, destinationPath);
        }
    }
}
