using (SQLiteCommand command = new SQLiteCommand(sqliteConn))
{
    // Create a SELECT query for the original table
    command.CommandText = "SELECT * FROM OriginalTable";
    using (SQLiteDataReader reader = command.ExecuteReader())
    {
        // Create a DataTable to store the records from the original table
        DataTable originalTable = new DataTable();
        originalTable.Load(reader);

        // Create a SELECT query for the imported table
