            importedTable.Load(importedReader);

            // Compare the two tables by checking if the row count and values are the same
            bool tablesAreEqual = originalTable.Rows.Count == importedTable.Rows.Count;

            // Compare each row and column value
            for (int i = 0; i < originalTable.Rows.Count && tablesAreEqual; i++)
            {
                for (int j = 0; j < originalTable.Columns.Count && tablesAreEqual; j++)
