import javax.sql.RowSet;
import javax.sql.rowset.RowSetWriter;

public class TransactionalWriter implements RowSetWriter {
    private final Connection connection;

    public TransactionalWriter(Connection connection) {
        this.connection = connection;
    }

    @Override
    public boolean writeData(RowSetInternal caller) throws SQLException {
        try {
            connection.setAutoCommit(false); // Start a transaction

            // Get the RowSet's data and metadata
            ResultSetMetaData metaData = caller.getMetaData();
            Object[][] data = getDataFromRowSet(caller);

            // Prepare the SQL INSERT statement
            StringBuilder sqlBuilder = new StringBuilder("INSERT INTO ");
            sqlBuilder.append(caller.getTableName()).append(" (");
            for (int i = 1; i <= metaData.getColumnCount(); i++) {
                if (i > 1) sqlBuilder.append(","); // Add comma separator
                sqlBuilder.append(metaData.getColumnName(i));
            }
            sqlBuilder.append(") VALUES (");
            for (int i = 1; i <= metaData.getColumnCount(); i++) {
                if (i > 1) sqlBuilder.append(","); // Add comma separator
                sqlBuilder.append("?");
            }
            sqlBuilder.append(")");

            // Create a prepared statement
            PreparedStatement preparedStatement = connection.prepareStatement(sqlBuilder.toString());

            // Insert each row of data into the database
            for (Object[] row : data) {
                for (int i = 0; i < metaData.getColumnCount(); i++) {
                    preparedStatement.setObject(i + 1, row[i]);
                }
                preparedStatement.addBatch();
            }

            // Execute the batch insert
            int[] batchUpdateCounts = preparedStatement.executeBatch();
            connection.commit(); // Commit the transaction

            // Check if all rows were successfully inserted
            for (int count : batchUpdateCounts) {
                if (count <= 0) {
                    return false; // At least one row failed to be inserted
                }
            }

            return true; // All rows inserted successfully
        } catch (SQLException e) {
            connection.rollback(); // Rollback the transaction in case of failure
            throw e;
        } finally {
            connection.setAutoCommit(true); // Reset autocommit to true
            // Cleanup code: close the prepared statement, connection, etc.
        }
    }

    private Object[][] getDataFromRowSet(RowSet rowSet) throws SQLException {
        List<Object[]> rows = new ArrayList<>();
        rowSet.beforeFirst(); // Move cursor to before the first row
        while (rowSet.next()) {
            ResultSetMetaData metaData = rowSet.getMetaData();
            Object[] row = new Object[metaData.getColumnCount()];
            for (int i = 1; i <= metaData.getColumnCount(); i++) {
                row[i - 1] = rowSet.getObject(i);
            }
            rows.add(row);
        }
        return rows.toArray(new Object[0][]);
    }
}
