import javax.sql.rowset.JdbcRowSet;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class RowSetWriterExample {
    public static void main(String[] args) {
        try (Connection connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "username", "password")) {

            // Create a RowSet and set up the connection
            JdbcRowSet rowSet = RowSetProvider.newFactory().createJdbcRowSet();
            rowSet.setUrl("jdbc:mysql://localhost:3306/mydb");
            rowSet.setUsername("username");
            rowSet.setPassword("password");
            rowSet.setCommand("SELECT * FROM mytable");
            rowSet.execute();

            // Move rows from RowSet to the database using PreparedStatement
            try (PreparedStatement preparedStatement = connection.prepareStatement("INSERT INTO mytable (col1, col2) VALUES (?, ?)")) {
                while (rowSet.next()) {
                    preparedStatement.setInt(1, rowSet.getInt("col1"));
                    preparedStatement.setString(2, rowSet.getString("col2"));
                    preparedStatement.executeUpdate();
                }
                connection.commit();
            } catch (SQLException e) {
                connection.rollback();
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
