public decimal CalculateIncome(int? year, bool includeNotCompletedRentals)
{
    decimal totalIncome = 0;

    // Filter the rented scooters list based on the year parameter
    var rentedScooters = _rentedScooterList;
    if (year.HasValue)
    {
        rentedScooters = rentedScooters.Where(s => s.RentStart.Year == year.Value).ToList();
    }

    // Calculate the income for each rented scooter
    foreach (var rentedScooter in rentedScooters)
    {
        var scooter = _scooterService.GetScooterById(rentedScooter.Id);

        // Calculate the rental duration in minutes
        var rentalDuration = (rentedScooter.RentEnd.HasValue ? rentedScooter.RentEnd.Value : DateTime.Now) - rentedScooter.RentStart;

        // Calculate the total price of the rental
        decimal totalPrice = CalculateRentalPrice(scooter, rentalDuration.TotalMinutes);

        totalIncome += totalPrice;
    }

    // Update the total income if includeNotCompletedRentals is true
    if (includeNotCompletedRentals)
    {
        totalIncome += CalculateNotCompletedRentalsIncome(year);
    }

    return totalIncome;
}

private decimal CalculateRentalPrice(Scooter scooter, double rentalDurationMinutes)
{
    decimal totalPrice = 0;
    int currentDay = 0;

    // Calculate the total price considering the price per minute
    while (rentalDurationMinutes > 0)
    {
        decimal pricePerMinute = currentDay < 1 ? scooter.PricePerMinute : scooter.PricePerMinute * 0.5m;

        int minutesInCurrentDay = (int)Math.Min(rentalDurationMinutes, (24 * 60) - (currentDay * 24 * 60));
        decimal priceForCurrentDay = pricePerMinute * minutesInCurrentDay;
        totalPrice += priceForCurrentDay;

        rentalDurationMinutes -= minutesInCurrentDay;
        currentDay++;
    }

    return totalPrice;
}

private decimal CalculateNotCompletedRentalsIncome(int? year)
{
    decimal totalIncome = 0;

    // Filter the rented scooters list to include only not completed rentals
    var notCompletedRentals = _rentedScooterList.Where(s => !s.RentEnd.HasValue);

    // Calculate the income for each not completed rental
    foreach (var rental in notCompletedRentals)
    {
        var scooter = _scooterService.GetScooterById(rental.Id);
        var rentalStart = rental.RentStart;
        var rentalEnd = DateTime.Now;

        // If year is specified, filter rentals based on the year
        if (year.HasValue && rentalStart.Year != year)
        {
            continue;
        }

        // Calculate the rental duration in minutes
        var rentalDuration = (rentalEnd - rentalStart).TotalMinutes;

        // Calculate the total price of the rental
        decimal totalPrice = CalculateRentalPrice(scooter, rentalDuration);

        totalIncome += totalPrice;
    }

    return totalIncome;
}
