#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

// Function to apply Gaussian Blur
void applyGaussianBlur(uint8_t* image, int width, int height) {
    // Gaussian Kernel
    float kernel[5][5] = {
        { 1,  4,   6,  4, 1 },
        { 4, 16,  24, 16, 4 },
        { 6, 24,  36, 24, 6 },
        { 4, 16,  24, 16, 4 },
        { 1,  4,   6,  4, 1 }
    };

    // Create temporary image to store blurred values
    uint8_t* tempImage = malloc(width * height);

    // Apply Gaussian Blur
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float sum = 0;

            for (int ky = -2; ky <= 2; ky++) {
                for (int kx = -2; kx <= 2; kx++) {
                    int xx = x + kx;
                    int yy = y + ky;

                    // Apply kernel to each pixel
                    if (xx >= 0 && xx < width && yy >= 0 && yy < height) {
                        int pixel = image[yy * width + xx];
                        float weight = kernel[kx + 2][ky + 2];
                        sum += pixel * weight;
                    }
                }
            }

            // Store the blurred value in the temporary image
            tempImage[y * width + x] = (uint8_t)round(sum / 256.0);
        }
    }

    // Copy the blurred values back to the original image
    for (int i = 0; i < width * height; i++) {
        image[i] = tempImage[i];
    }

    // Free temporary image memory
    free(tempImage);
}

int main() {
