                if (kx >= 0 && kx < width) {
                    sum += inputImage[y][kx] * kernel[i];
                }
            }

            intermediateImage[y][x] = sum;
        }
    }

    // Create the output image
    float** outputImage = malloc(height * sizeof(float*));
    for (int y = 0; y < height; y++) {
        outputImage[y] = malloc(width * sizeof(float));
