```C#
using UnityEngine;

public class SurfaceTangent : MonoBehaviour
{
    public MeshFilter meshFilter;

    void Start()
    {
        if (meshFilter == null)
        {
            meshFilter = GetComponent<MeshFilter>(); // Get the MeshFilter component of the object if not assigned
        }

        CalculateSurfaceTangent();
    }

    void CalculateSurfaceTangent()
    {
        if (meshFilter == null || meshFilter.sharedMesh == null)
        {
            Debug.LogError("Mesh or MeshFilter not found.");
            return;
        }

        Mesh mesh = meshFilter.sharedMesh;
        Vector3[] vertices = mesh.vertices;
        Vector3[] normals = mesh.normals;
        int[] triangles = mesh.triangles;

        // Calculate tangent for each triangle
        for (int i = 0; i < triangles.Length; i += 3)
        {
            Vector3 vertexA = vertices[triangles[i]];
            Vector3 vertexB = vertices[triangles[i + 1]];
            Vector3 vertexC = vertices[triangles[i + 2]];

            Vector3 normalA = normals[triangles[i]];
            Vector3 normalB = normals[triangles[i + 1]];
            Vector3 normalC = normals[triangles[i + 2]];

            // Calculate tangent using the three vertices and their respective normals
            Vector3 tangent = CalculateTangent(vertexA, vertexB, vertexC, normalA, normalB, normalC);

            // Use the tangent value for further calculations or processing
            Debug.Log("Tangent for triangle " + (i / 3 + 1) + ": " + tangent);
        }
    }

    Vector3 CalculateTangent(Vector3 vertexA, Vector3 vertexB, Vector3 vertexC, Vector3 normalA, Vector3 normalB, Vector3 normalC)
    {
        Vector3 side1 = vertexB - vertexA;
        Vector3 side2 = vertexC - vertexA;

        Vector3 normal = (normalA + normalB + normalC).normalized;

        return Vector3.Cross(side1, side2).normalized;
    }
}
```

