Sure! Here's an example of how you can create a multi-level menu in Kotlin, with separate classes for the menu logic and storage of archives and documents.

```kotlin
// Define the Document class that represents a document
data class Document(val name: String, val text: String)

// Define the Archive class that represents an archive containing multiple documents
data class Archive(val name: String, val documents: List<Document>)

// Define the Menu class that handles the menu logic and storage of archives
class Menu {
    private val archives = mutableListOf<Archive>()

    // Function to add a new archive with documents
    fun addArchive(archive: Archive) {
        archives.add(archive)
    }

    // Function to display the archives
    fun showArchives() {
        println("Archives:")
        archives.forEachIndexed { index, archive ->
            println("${index + 1}. ${archive.name}")
        }
    }

    // Function to display the documents in a selected archive
    fun showDocuments(archiveIndex: Int) {
        if (archiveIndex >= 0 && archiveIndex < archives.size) {
            val archive = archives[archiveIndex]
            println("Documents in ${archive.name}:")
            archive.documents.forEachIndexed { index, document ->
                println("${index + 1}. ${document.name}")
            }
        } else {
            println("Invalid archive index!")
        }
    }

    // Function to display the text of a selected document
    fun showDocumentText(archiveIndex: Int, documentIndex: Int) {
        if (archiveIndex >= 0 && archiveIndex < archives.size) {
            val archive = archives[archiveIndex]
            if (documentIndex >= 0 && documentIndex < archive.documents.size) {
                val document = archive.documents[documentIndex]
                println("Text of ${document.name}:\n${document.text}")
            } else {
                println("Invalid document index!")
            }
        } else {
            println("Invalid archive index!")
        }
    }
}

fun main() {
    val menu = Menu()

    // Create and add some archives to the menu
    val archive1 = Archive("Archive 1", listOf(
        Document("Document 1.1", "Text of Document 1.1"),
        Document("Document 1.2", "Text of Document 1.2")
    ))
    menu.addArchive(archive1)

    val archive2 = Archive("Archive 2", listOf(
        Document("Document 2.1", "Text of Document 2.1"),
        Document("Document 2.2", "Text of Document 2.2"),
        Document("Document 2.3", "Text of Document 2.3")
    ))
    menu.addArchive(archive2)

    // Display the menu and perform actions
    menu.showArchives()
    println("Select an archive:")
    val archiveIndex = readLine()?.toIntOrNull()?.minus(1) ?: -1
    menu.showDocuments(archiveIndex)
    println("Select a document:")
    val documentIndex = readLine()?.toIntOrNull()?.minus(1) ?: -1
    menu.showDocumentText(archiveIndex, documentIndex)
}
```

In this example, the `Menu` class handles the logic for adding archives, displaying archives and their documents, and displaying the text of a selected document. The `Archive` class represents an archive that contains a list of `Document` objects. Each `Document` has a name and text.

In the `main` function, we create a `Menu` object and add some sample archives. Then, we prompt the user to select an archive and a document, and display the text of the selected document using the `Menu` methods.

