// Function to export registry values from the specified path
void ExportRegistryValues(const std::string& registryPath, const std::string& exportFilePath) {
    // Open the registry key
    HKEY hKey;
    LONG lResult = RegOpenKeyExA(HKEY_CURRENT_USER, registryPath.c_str(), 0, KEY_READ, &hKey);
    if (lResult != ERROR_SUCCESS) {
        std::cerr << "Failed to open registry key! Error code: " << lResult << std::endl;
        return;
    }

    // Retrieve the registry values
    DWORD valueCount;
    RegQueryInfoKeyA(hKey, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &valueCount, nullptr, nullptr, nullptr, nullptr);

    // Open/create the export file
    std::ofstream exportFile(exportFilePath);
    if (!exportFile.is_open()) {
        std::cerr << "Failed to open/create export file!" << std::endl;
        return;
    }

    // Iterate through each registry value and write to the export file
    for (DWORD i = 0; i < valueCount; ++i) {
        DWORD valueNameSize = 256;
        CHAR valueName[256];
        DWORD valueType;
        BYTE data[1024];
        DWORD dataSize = sizeof(data);

        // Retrieve the registry value information
        RegEnumValueA(hKey, i, valueName, &valueNameSize, nullptr, &valueType, data, &dataSize);

        // Write the value information to the export file
        exportFile << "Value Name: " << valueName << std::endl;
        exportFile << "Value Type: " << valueType << std::endl;

        if (valueType == REG_SZ) {
            exportFile << "Value Data: " << reinterpret_cast<const char*>(data) << std::endl;
        }
        else if (valueType == REG_DWORD) {
            exportFile << "Value Data: " << *reinterpret_cast<ULONG*>(data) << std::endl;
        }
        else {
            // Handle other value types if needed
        }

        exportFile << "-----------" << std::endl;
    }

    // Close the registry key
    RegCloseKey(hKey);

    // Close the export file
    exportFile.close();
}

