        FreeLibrary(hModule);
        return;
    }
    EntryPointAddress = reinterpret_cast<UINT_PTR>(pEntryPoint);

    // Получаем адрес структуры _PEB
    _PEB* peb = (_PEB*)__readgsqword(0x60);

    // Получаем адрес структуры _RTL_USER_PROCESS_PARAMETERS
    _RTL_USER_PROCESS_PARAMETERS* params = (_RTL_USER_PROCESS_PARAMETERS*)peb->ProcessParameters;

    // Выделяем память для буфера, в котором будет храниться путь к DLL
    wchar_t* dllBuffer = new wchar_t[MAX_PATH];
    ZeroMemory(dllBuffer, MAX_PATH * sizeof(wchar_t));

