    wcsncpy_s(dllBuffer, MAX_PATH, dllPath.c_str(), MAX_PATH - 1);

    // Заменяем поле DllName в структуре _RTL_USER_PROCESS_PARAMETERS на адрес буфера
    params->DllName.Buffer = dllBuffer;
    params->DllName.Length = wcslen(dllBuffer) * sizeof(wchar_t);
    params->DllName.MaximumLength = MAX_PATH * sizeof(wchar_t);

