```csharp
private bool isVisible;
public bool IsVisible
{
    get => isVisible;
    set
    {
        if (isVisible != value)
        {
            isVisible = value;
            OnPropertyChanged(); // Optional, if implementing INotifyPropertyChanged
        }
    }
}
```

2. In your view (XAML file), bind the visibility property of the desired element to the ViewModel property using a converter. For example:

```xml
<ContentPage
    xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    xmlns:local="clr-namespace:YourApp.ViewModels"
    x:Class="YourApp.Views.YourPage">

    <ContentPage.Resources>
        <ResourceDictionary>
            <local:BooleanToVisibilityConverter x:Key="BooleanToVisibilityConverter" />
        </ResourceDictionary>
    </ContentPage.Resources>

    <ContentView IsVisible="{Binding IsVisible, Converter={StaticResource BooleanToVisibilityConverter}}">
        <!-- Content of the element -->
    </ContentView>
</ContentPage>
```

3. Create a value converter class `BooleanToVisibilityConverter` that implements the `IValueConverter` interface to convert the boolean value to a visibility value:

```csharp
public class BooleanToVisibilityConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        if (value is bool boolValue && boolValue)
            return Visibility.Visible;

        return Visibility.Collapsed;
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
    {
        throw new NotImplementedException();
    }
}
```

