    ctx.fillText(
      `${tck / 10}`,
      currentX + cupOptions().cell.paddingX * dpiScale,
      yPosition + cellHeight / 2,
    );

    if (currentX - marginForOrders > maxTextWidth) {
      break; // Прервать цикл, если ширина текста превышает maxTextWidth
    }
  }
},
