Certainly! Here's an example implementation of a text-prompt app in Kotlin that allows users to create archives and notes and navigate through menus using numbers:

```kotlin
import java.util.Scanner

data class Archive(val name: String, val notes: MutableList<Note> = mutableListOf())

data class Note(val name: String, var content: String = "")

class TextPromptApp(private val scanner: Scanner) {
    private val archives: MutableList<Archive> = mutableListOf()

    private fun displayMenu() {
        println("=== Text-Prompt App ===")
        println("1. View Archives")
        println("2. Create Archive")
        println("3. Exit")
        print("Enter your choice: ")
    }

    private fun displayArchives() {
        println("=== Archives ===")
        archives.forEachIndexed { index, archive ->
            println("$index. ${archive.name}")
        }
    }

    private fun displayNotes(archiveIndex: Int) {
        val archive = archives[archiveIndex]
        println("=== Notes in ${archive.name} Archive ===")
        archive.notes.forEachIndexed { index, note ->
            println("$index. ${note.name}")
        }
    }

    private fun createArchive() {
        print("Enter the name for the new archive: ")
        val name = scanner.nextLine()
        archives.add(Archive(name))
        println("Archive '$name' created.")
    }

    private fun createNote(archiveIndex: Int) {
        val archive = archives[archiveIndex]
        print("Enter the name for the new note: ")
        val name = scanner.nextLine()
        val note = Note(name)
        archive.notes.add(note)
        println("Note '$name' created in ${archive.name} archive.")
        editNoteContent(note)
    }

    private fun editNoteContent(note: Note) {
        println("Enter the content for '${note.name}' (enter 'q' to exit): ")
        val content = StringBuilder()
        var line: String?
        do {
            line = scanner.nextLine()
            if (line != "q") {
                content.appendLine(line)
            }
        } while (line != "q")
        note.content = content.toString()
    }

    fun start() {
        var exit = false

        while (!exit) {
            displayMenu()
            when (val choice = scanner.nextLine()) {
                "1" -> {
                    displayArchives()
                    print("Enter the archive number to view notes (or 'q' to exit to main menu): ")
                    val archiveChoice = scanner.nextLine()
                    if (archiveChoice != "q") {
                        val archiveIndex = archiveChoice.toIntOrNull()
                        if (archiveIndex != null && archiveIndex in 0 until archives.size) {
                            displayNotes(archiveIndex)
                            print("Enter the note number to view contents: ")
                            val noteIndex = scanner.nextLine().toIntOrNull()
                            if (noteIndex != null && noteIndex in 0 until archives[archiveIndex].notes.size) {
                                val note = archives[archiveIndex].notes[noteIndex]
                                println("=== Note '${note.name}' (${archives[archiveIndex].name} Archive) ===")
                                println(note.content.trim())
                                println()
                            } else {
                                println("Invalid note number.")
                            }
                        } else {
                            println("Invalid archive number.")
                        }
                    }
                }
                "2" -> {
                    createArchive()
                }
                "3" -> {
                    exit = true
                }
                else -> {
                    println("Invalid choice.")
                }
            }
        }
    }
}

fun main() {
    val scanner = Scanner(System.`in`)
    TextPromptApp(scanner).start()
    scanner.close()
}
```

In this example, the app creates and manages `Archive` and `Note` instances. The `TextPromptApp` class handles the main logic of displaying menus, creating archives and notes, and editing note contents. The app is started in the `main` function by creating an instance of `TextPromptApp` and calling the `start` method.

Note that the user has to input numbers to navigate through menus, except when naming new archives/notes or entering note contents. The app uses `Scanner` to read user input from the console.

