Here is a C++ program to solve a Sudoku puzzle using backtracking:

```cpp
#include <iostream>
using namespace std;

const int N = 9;

// Function to print the Sudoku grid
void printGrid(char grid[N][N]) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cout << grid[i][j] << " ";
        }
        cout << endl;
    }
}

// Function to check if the given digit can be placed at the given position
bool isSafe(char grid[N][N], int row, int col, char num) {
    // Check if the number is already present in the current row
    for (int i = 0; i < N; i++) {
        if (grid[row][i] == num) {
            return false;
        }
    }

    // Check if the number is already present in the current column
    for (int i = 0; i < N; i++) {
        if (grid[i][col] == num) {
            return false;
        }
    }

    // Check if the number is already present in the current 3x3 sub-grid
    int subGridRow = (row / 3) * 3;
    int subGridCol = (col / 3) * 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (grid[subGridRow + i][subGridCol + j] == num) {
                return false;
            }
        }
    }

    return true;
}

// Function to solve the Sudoku puzzle using backtracking
bool solveSudoku(char grid[N][N]) {
    int row, col;
    bool isEmpty = false;

    // Find an empty cell in the Sudoku grid
    for (row = 0; row < N; row++) {
        for (col = 0; col < N; col++) {
            if (grid[row][col] == '.') {
                isEmpty = true;
                break;
            }
        }
        if (isEmpty) {
            break;
        }
    }

    // If no empty cell is found, the Sudoku puzzle is solved
    if (!isEmpty) {
        return true;
    }

    // Try each digit from 1 to 9 in the current empty cell
    for (char num = '1'; num <= '9'; num++) {
        if (isSafe(grid, row, col, num)) {
            // Place the digit in the current empty cell
            grid[row][col] = num;

            // Recursively solve the remaining Sudoku puzzle
            if (solveSudoku(grid)) {
                return true;
            }

            // If the current digit does not lead to a solution, remove it
            grid[row][col] = '.';
        }
    }

    return false;
}

int main() {
    char grid[N][N] = {{'5', '3', '.', '.', '7', '.', '.', '.', '.'},
                       {'6', '.', '.', '1', '9', '5', '.', '.', '.'},
                       {'.', '9', '8', '.', '.', '.', '.', '6', '.'},
                       {'8', '.', '.', '.', '6', '.', '.', '.', '3'},
                       {'4', '.', '.', '8', '.', '3', '.', '.', '1'},
                       {'7', '.', '.', '.', '2', '.', '.', '.', '6'},
                       {'.', '6', '.', '.', '.', '.', '2', '8', '.'},
                       {'.', '.', '.', '4', '1', '9', '.', '.', '5'},
                       {'.', '.', '.', '.', '8', '.', '.', '7', '9'}};

    if (solveSudoku(grid)) {
        cout << "Sudoku solution:" << endl;
        printGrid(grid);
    } else {
        cout << "No solution exists." << endl;
    }

    return 0;
}
```

In this program, we have used a 2D character array to represent the Sudoku grid. The empty cells are denoted by the '.' symbol.

The `printGrid()` function is used to print the Sudoku grid.

The `isSafe()` function checks if the given digit can be placed at the given position without violating any of the Sudoku rules.

The `solveSudoku()` function solves the Sudoku puzzle using backtracking. It finds the first empty cell in the grid, tries each digit from 1 to 9 in that cell, and recursively solves the remaining Sudoku puzzle. If a solution is found, it returns `true`. Otherwise, it backtracks and tries the next digit.

The `main()` function initializes the Sudoku grid and calls the `solveSudoku()` function. If a solution exists, it prints the solved Sudoku grid. Otherwise, it prints a message indicating that no solution exists.

Here is a C++ function that performs basic string compression according to the given requirements:

```cpp
#include <iostream>
#include <sstream>

std::string compressString(const std::string& str) {
    std::stringstream compressed;
    size_t count = 1;

    for (size_t i = 1; i < str.length(); i++) {
        if (str[i] == str[i - 1]) {
            count++;
        } else {
            compressed << str[i - 1] << count;
            count = 1;
        }
    }

    compressed << str.back() << count;
    std::string compressedStr = compressed.str();

    if (compressedStr.length() >= str.length()) {
        return str;
    } else {
        return compressedStr;
    }
}

int main() {
    std::string str = "aabcccccaaa";
    std::cout << "Original string: " << str << std::endl;
    std::cout << "Compressed string: " << compressString(str) << std::endl;

    return 0;
}
```

The `compressString` function takes a `const std::string&` parameter and returns a compressed version of the string. It uses a `stringstream` to build the compressed string by iterating over the characters of the input string.

Inside the loop, if the current character is the same as the previous character, the count of that character is incremented. If the current character is different, the previous character and its count are appended to the `stringstream`, and the count is reset to 1.

After the loop, the last character and its count are also appended to the `stringstream`. The compressed string is then obtained by converting the `stringstream` to a `std::string` using the `str()` method.

Finally, the function checks whether the compressed string is smaller than the original string. If it is not, the original string is returned; otherwise, the compressed string is returned.

In the `main` function, a sample string "aabcccccaaa" is compressed and printed. The output would be:

```
Original string: aabcccccaaa
Compressed string: a2b1c5a3
```

