#include <iostream>
#include <fstream>
#include <string>

// Structure to store letter information
struct LetterInfo {
    char letter;
    int count;
    double percentage;
};

void openFile(std::ifstream& inputFile, std::ofstream& outputFile) {
    std::string inputFileName, outputFileName;

    // Ask for input file name
    std::cout << "Enter input file name: ";
    std::cin >> inputFileName;

    // Open input file
    inputFile.open(inputFileName);
    if (!inputFile) {
        std::cout << "Error opening input file. Exiting program." << std::endl;
        exit(1);
    }

    // Ask for output file name
    std::cout << "Enter output file name: ";
    std::cin >> outputFileName;

    // Open output file
    outputFile.open(outputFileName);
    if (!outputFile) {
        std::cout << "Error opening output file. Exiting program." << std::endl;
        exit(1);
    }
}

void count(LetterInfo letterCounts[], std::ifstream& inputFile) {
    char letter;

    // Initialize counts to zero
    for (int i = 0; i < 26; i++) {
        letterCounts[i].count = 0;
    }

    while (inputFile.get(letter)) {
        if (isalpha(letter)) {
            if (isupper(letter)) {
                letterCounts[letter - 'A'].count++;
            } else {
                letterCounts[letter - 'a' + 26].count++;
            }
        }
    }
}

void printResult(LetterInfo letterCounts[], std::ofstream& outputFile) {
    outputFile << "Letter Count Percentage of Occurrence\n";

    for (int i = 0; i < 26; i++) {
        outputFile << letterCounts[i].letter << " " << letterCounts[i].count << " " << letterCounts[i].percentage << "%\n";
    }

    for (int i = 26; i < 52; i++) {
        outputFile << letterCounts[i].letter << " " << letterCounts[i].count << " " << letterCounts[i].percentage << "%\n";
    }
}

int main() {
    std::ifstream inputFile;
    std::ofstream outputFile;
    LetterInfo letterCounts[52]; // Array to store letter counts

    // Open files
    openFile(inputFile, outputFile);

    // Count letters
    count(letterCounts, inputFile);

    // Calculate percentages
    int totalLetters = 0;
    for (int i = 0; i < 52; i++) {
        totalLetters += letterCounts[i].count;
    }

    for (int i = 0; i < 52; i++) {
        letterCounts[i].percentage = (letterCounts[i].count / static_cast<double>(totalLetters)) * 100;
    }

    // Print result
    printResult(letterCounts, outputFile);

    // Close files
    inputFile.close();
    outputFile.close();

    return 0;
}
```

Note that this code assumes that the input file contains only letters and no other characters. If the input file can contain other characters, you may need to modify the `count` function to check for letters only.

