let sideExceeds;

Если объем асков или бидов перевешивает другую сторону в 3 раза и более, нужно возвращать тот, который превышает, иначе null

Для решения этой задачи можно использовать следующий подход:

```javascript
// Вычисляем суммарный объем асков и бидов
let historyQuantityTotal: HistoryQuantityTotalType = {
  ask: 0,
  bid: 0,
};

// Вычисляем максимальный объем между асками и бидами
let maxQuantity = Math.max(historyQuantityTotal.ask, historyQuantityTotal.bid);

// Проверяем условие перевеса объема
if ((maxQuantity / 3) >= historyQuantityTotal.ask || (maxQuantity / 3) >= historyQuantityTotal.bid) {
  // Определяем, какая сторона превышает объем и сохраняем значение в переменной sideExceeds
  sideExceeds = historyQuantityTotal.ask > historyQuantityTotal.bid ? "ask" : "bid";
} else {
  sideExceeds = null;
}

// Возвращаем значение sideExceeds
return sideExceeds;
```

В этом коде мы вычисляем суммарный объем асков и бидов в переменной `historyQuantityTotal`. Затем мы находим максимальный объем между асками и бидами с помощью `Math.max()`. После этого мы проверяем условие перевеса объема, где мы сравниваем максимальный объем со значением, равным трети этого объема. Если условие выполняется, то определяем, какая сторона превышает объем (если это аски, `historyQuantityTotal.ask` будет больше, если это биды, `historyQuantityTotal.bid` будет больше) и сохраняем значение в переменной `sideExceeds`. Если условие не выполняется, присваиваем переменной `sideExceeds` значение `null`. В конце возвращаем значение `sideExceeds`.

