```csharp
using UnityEngine;
using UnityEngine.AI;

public class BotMovement : MonoBehaviour
{
    public float movementSpeed = 10f; // Скорость движения бота
    public float stoppingDistance = 1f; // Расстояние при котором бот остановится у точки

    private NavMeshAgent navMeshAgent;
    private Vector3[] targetPoints;
    private int currentTargetIndex;

    private void Start()
    {
        navMeshAgent = GetComponent<NavMeshAgent>();
        targetPoints = new Vector3[5]; // Создаем массив на 5 точек

        // Генерируем случайные точки на 100 единиц удаленные друг от друга
        for (int i = 0; i < targetPoints.Length; i++)
        {
            targetPoints[i] = RandomNavmeshLocation(100f);
        }

        currentTargetIndex = 0;
        MoveToTarget();
    }

    private void Update()
    {
        // Проверяем достиг ли бот текущей цели
        if (Vector3.Distance(transform.position, targetPoints[currentTargetIndex]) < stoppingDistance)
        {
            currentTargetIndex = (currentTargetIndex + 1) % targetPoints.Length; // Выбираем следующую цель
            MoveToTarget();
        }
    }

    private void MoveToTarget()
    {
        navMeshAgent.SetDestination(targetPoints[currentTargetIndex]);
        navMeshAgent.speed = movementSpeed;
    }

    private Vector3 RandomNavmeshLocation(float radius)
    {
        // Генерируем случайную точку на NavMesh с радиусом
        Vector3 randomDirection = Random.insideUnitSphere * radius;
        randomDirection += transform.position;
        NavMeshHit hit;
        NavMesh.SamplePosition(randomDirection, out hit, radius, NavMesh.AllAreas);
        return hit.position;
    }
}
```

