```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.AI;

public class BotMovement : MonoBehaviour
{
    public float movementSpeed = 10f;
    public float stoppingDistanceSqr = 1f;
    public float waitTime = 2f; // Время ожидания на каждой точке

    private NavMeshAgent navMeshAgent;
    private Vector3[] targetPoints;
    private int currentTargetIndex;

    private void Start()
    {
        navMeshAgent = GetComponent<NavMeshAgent>();
        targetPoints = new Vector3[5];

        for (int i = 0; i < targetPoints.Length; i++)
        {
            targetPoints[i] = RandomNavmeshLocation(100f);
        }

        currentTargetIndex = 0;

        StartCoroutine(MoveToTargets());
    }

    private IEnumerator MoveToTargets()
    {
        while (true)
        {
            MoveToTarget();

            // Ждем, пока достигнем текущей цели
            while (Vector3.SqrMagnitude(transform.position - targetPoints[currentTargetIndex]) > stoppingDistanceSqr)
            {
                yield return null;
            }

            yield return new WaitForSeconds(waitTime);

            currentTargetIndex = (currentTargetIndex + 1) % targetPoints.Length;
        }
    }

    private void MoveToTarget()
    {
        navMeshAgent.SetDestination(targetPoints[currentTargetIndex]);
        navMeshAgent.speed = movementSpeed;
    }

    private Vector3 RandomNavmeshLocation(float radius)
    {
        Vector3 randomDirection = Random.insideUnitSphere * radius;
        randomDirection += transform.position;
        NavMeshHit hit;
        NavMesh.SamplePosition(randomDirection, out hit, radius, NavMesh.AllAreas);
        return hit.position;
    }
}
```

В этой версии используется корутина `MoveToTargets()`, которая зациклена бесконечно. Она перемещает бота к текущей цели и затем ждет, пока бот достигнет цели, используя `yield return null`. Затем происходит ожидание указанное время `waitTime`. После этого выбирается следующая цель и процесс повторяется.

Если вы хотите избежать расчета Y-координаты, вы можете использовать `Vector2` вместо `Vector3` для проверки расстояния. Вот обновленный код:

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.AI;

public class BotMovement : MonoBehaviour
{
    public float movementSpeed = 10f;
    public float stoppingDistanceSqr = 1f;
    public float waitTime = 2f;

    private NavMeshAgent navMeshAgent;
    private Vector2[] targetPoints;
    private int currentTargetIndex;

    private void Start()
    {
        navMeshAgent = GetComponent<NavMeshAgent>();
        targetPoints = new Vector2[5];

        for (int i = 0; i < targetPoints.Length; i++)
        {
            Vector3 randomPosition = RandomNavmeshLocation(100f);
            targetPoints[i] = new Vector2(randomPosition.x, randomPosition.z); // Используем только X и Z координаты
        }

        currentTargetIndex = 0;

        StartCoroutine(MoveToTargets());
    }

    private IEnumerator MoveToTargets()
    {
        while (true)
        {
            MoveToTarget();

            // Ждем, пока достигнем текущей цели (без учета Y-координаты)
            while (Vector2.SqrMagnitude(new Vector2(transform.position.x, transform.position.z) - targetPoints[currentTargetIndex]) > stoppingDistanceSqr)
            {
                yield return null;
            }

            yield return new WaitForSeconds(waitTime);

            currentTargetIndex = (currentTargetIndex + 1) % targetPoints.Length;
        }
    }

    private void MoveToTarget()
    {
        Vector3 targetPosition = new Vector3(targetPoints[currentTargetIndex].x, transform.position.y, targetPoints[currentTargetIndex].y);
        navMeshAgent.SetDestination(targetPosition);
        navMeshAgent.speed = movementSpeed;
    }

    private Vector3 RandomNavmeshLocation(float radius)
    {
        Vector3 randomDirection = Random.insideUnitSphere * radius;
        randomDirection += transform.position;
        NavMeshHit hit;
        NavMesh.SamplePosition(randomDirection, out hit, radius, NavMesh.AllAreas);
        return hit.position;
    }
}
