// Function to calculate the weekly pay
double weeklyPay(double hours, double rate, string name, int employeeType) {
    double regularPay = 0.0;
    double overtimePay = 0.0;
    double taxableIncome = 0.0;
    double fitRate = 0.0;
    double socialSecurityRate = 0.062;
    double medicareRate = 0.0145;
    double dentalContribution = 17.0;
    double retirementContribution = 77.0;

    // Calculate regular pay
    if (hours <= 40.0) {
        regularPay = hours * rate;
    } else {
        regularPay = 40.0 * rate;
        overtimePay = (hours - 40.0) * (rate * 2);
    }

    // Calculate taxable income and FIT rate
    if (rate < 15.0) {
        taxableIncome = regularPay + overtimePay;
        fitRate = 0.12;
    } else {
        taxableIncome = regularPay + overtimePay;
        fitRate = 0.15;
    }

    // Calculate total deductions
    double fitDeduction = taxableIncome * fitRate;
    double socialSecurityDeduction = regularPay * socialSecurityRate;
    double medicareDeduction = regularPay * medicareRate;
    double totalDeductions = fitDeduction + socialSecurityDeduction + medicareDeduction;

    // Calculate net pay
    double netPay = regularPay + overtimePay - totalDeductions;

    // Convert name to uppercase
    for (int i = 0; i < name.length(); i++) {
        name[i] = toupper(name[i]);
    }

    // Print the output
    cout << "\033[1;36m" << name << "\033[0m" << endl;
    cout << "Weekly Pay: $" << fixed << setprecision(2) << netPay << endl;
    if (employeeType == 1) {
        cout << "Employee Type: Full-time" << endl;
    } else if (employeeType == 2) {
        cout << "Employee Type: Part-time" << endl;
    }

    return netPay;
}

