    clientAddr.sin_family = AF_INET;
    clientAddr.sin_port = htons(2000);
    clientAddr.sin_addr.s_addr = inet_addr("192.178.111.1");
    if (connect(sockfd, (struct sockaddr *) &clientAddr, sizeof(clientAddr)) == -1) {
        std::cerr << "Failed to connect socket" << std::endl;
        close(sockfd);
        return;
    }

    // 创建epoll实例
    int epollfd = epoll_create(1);
    if (epollfd == -1) {
        std::cerr << "Failed to create epoll instance" << std::endl;
        close(sockfd);
        return;
    }

    // 添加套接字到epoll
    struct epoll_event ev{};
    ev.events = EPOLLIN | EPOLLOUT;  // 监听可读和可写事件
    ev.data.fd = sockfd;
    if (epoll_ctl(epollfd, EPOLL_CTL_ADD, sockfd, &ev) == -1) {
        std::cerr << "Failed to add socket to epoll" << std::endl;
        close(epollfd);
        close(sockfd);
        return;
    }

    while (true) {
        // 等待事件发生
        struct epoll_event events[1];
        int numEvents = epoll_wait(epollfd, events, 1, -1);
        if (numEvents == -1) {
            std::cerr << "Error in epoll_wait" << std::endl;
            break;
        }

        // 检查每个返回的事件
        for (int i = 0; i < numEvents; ++i) {
            int fd = events[i].data.fd;

            if (events[i].events & EPOLLIN) {
                // 套接字可读，接收数据
                char buffer[1024];
                memset(buffer, 0, sizeof(buffer));
                ssize_t bytesRead = recv(fd, buffer, sizeof(buffer) - 1, 0);
                if (bytesRead == -1) {
                    std::cerr << "Failed to receive data" << std::endl;
                    break;
                }
                std::cout << "Received data: " << buffer << std::endl;
            }

            if (events[i].events & EPOLLOUT) {
                // 套接字可写，发送数据
                std::string sendData = "Hello, server!";
                ssize_t bytesSent = send(fd, sendData.c_str(), sendData.size(), 0);
                if (bytesSent == -1) {
                    std::cerr << "Failed to send data" << std::endl;
                    break;
                }
                std::cout << "Sent data: " << sendData << std::endl;

                // 取消对可写事件的监视
                struct epoll_event modEv{};
                modEv.events = EPOLLIN;
                modEv.data.fd = fd;
                if (epoll_ctl(epollfd, EPOLL_CTL_MOD, fd, &modEv) == -1) {
                    std::cerr << "Failed to modify epoll event" << std::endl;
                    break;
                }
            }
        }
    }

    // 关闭套接字和epoll实例
    close(epollfd);
    close(sockfd);
}

int main() {
    std::thread t(udpThread);
    t.join();

    return 0;
}
```

这样，UDP套接字将在一个单独的线程中运行，并通过connect函数将其绑定到客户端的IP地址（192.178.111.1）和端口（2000）。你可以在主函数中启动线程，并使用join函数等待线程执行完成。请注意，这段代码目前仅适用于客户端与服务器之间的通信，如果要实现多个客户端与服务器之间的通信，可能需要进行进一步的修改。

In Java, primitive fields (instance variables) are indeed instantiated with default values, while primitive variables declared within a method (local variables) are not automatically initialized.

The default values for primitive fields in Java are as follows:

- `byte`, `short`, `int`, `long`: 0
- `float`, `double`: 0.0
- `char`: '\u0000' (null character)
- `boolean`: `false`

For example, consider the following class:

```java
public class MyClass {
    private int num;
    private boolean flag;

    public static void main(String[] args) {
        MyClass myObj = new MyClass();

        System.out.println(myObj.num);  // Output: 0
        System.out.println(myObj.flag); // Output: false
    }
}
```

In this case, the `num` field has a default value of 0, while the `flag` field has a default value of `false`.

On the other hand, local primitive variables are not initialized by default, meaning they do not have a defined value until explicitly assigned. It is mandatory to assign a value to a local variable before using it; otherwise, a compile-time error will occur.

Therefore, local primitive variables do not have a value of `null` since `null` represents the absence of an object reference, and primitives are not objects in Java.

