Here is an example program code for IP allocation in C# using FDRSA algorithm:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    public static void Main(string[] args)
    {
        // Number of IP addresses to allocate
        int numAddresses = 10;

        // Range of IP addresses
        string startIP = "192.168.0.0";
        string endIP = "192.168.0.255";

        // Allocate IP addresses using FDRSA algorithm
        List<string> allocatedIPs = AllocateIPs(startIP, endIP, numAddresses);

        // Print the allocated IP addresses
        Console.WriteLine("Allocated IP Addresses:");
        foreach (string ip in allocatedIPs)
        {
            Console.WriteLine(ip);
        }
    }

    public static List<string> AllocateIPs(string startIP, string endIP, int numAddresses)
    {
        // Convert start and end IP addresses to integers
        uint ipStart = IPToInteger(startIP);
        uint ipEnd = IPToInteger(endIP);

        // Calculate the IP range size
        uint rangeSize = ipEnd - ipStart + 1;

        // Check if the range size is smaller than the required number of addresses
        if (rangeSize < numAddresses)
        {
            throw new ArgumentException("Not enough IP addresses in the specified range.");
        }

        // Generate the list of available IP addresses
        List<uint> availableIPs = Enumerable.Range((int)ipStart, (int)rangeSize).Select(x => (uint)x).ToList();

        // Allocate the required number of IP addresses randomly using FDRSA algorithm
        Random random = new Random();
        List<string> allocatedIPs = new List<string>();
        for (int i = 0; i < numAddresses; i++)
        {
            int selectedIndex = random.Next(availableIPs.Count);
            uint allocatedIP = availableIPs[selectedIndex];
            availableIPs.RemoveAt(selectedIndex);
            allocatedIPs.Add(IntegerToIP(allocatedIP));
        }

        return allocatedIPs;
    }

    public static uint IPToInteger(string ipAddress)
    {
        string[] ipParts = ipAddress.Split('.');
        if (ipParts.Length != 4)
        {
            throw new ArgumentException("Invalid IP address format.");
        }

        uint ipInteger = 0;
        for (int i = 0; i < 4; i++)
        {
            byte ipPart;
            if (!byte.TryParse(ipParts[i], out ipPart))
            {
                throw new ArgumentException("Invalid IP address format.");
            }

            ipInteger = (ipInteger << 8) + ipPart;
        }

        return ipInteger;
    }

    public static string IntegerToIP(uint ipInteger)
    {
        byte[] ipBytes = BitConverter.GetBytes(ipInteger);
        string ipAddress = string.Join(".", ipBytes.Reverse());
        return ipAddress;
    }
}
```

In this example, the `AllocateIPs` method uses the FDRSA algorithm to allocate a specified number of IP addresses within a given IP range. The `IPToInteger` and `IntegerToIP` methods are used to convert IP addresses between string and integer representations. The program first defines the number of IP addresses to allocate, the start and end IP addresses of the range, and then calls the `AllocateIPs` method to perform the allocation. Finally, it prints the allocated IP addresses to the console.

