      trade.quantity / quantityDivider < minQuantity ? 0 : trade.radius / 50,
      trade.quantity / quantityDivider < minQuantity ? 0 : trade.radius / 50,
      1
    ]).flat();

    const positionBuffer = context.createBuffer();
    context.bindBuffer(context.ARRAY_BUFFER, positionBuffer);
    context.bufferData(
      context.ARRAY_BUFFER,
      new Float32Array(positions),
      context.STATIC_DRAW
    );

    const vao = context.createVertexArray();
    context.bindVertexArray(vao);
    context.enableVertexAttribArray(positionAttributeLocation);
    context.bindBuffer(context.ARRAY_BUFFER, positionBuffer);
    context.vertexAttribPointer(
      positionAttributeLocation, 2, context.FLOAT, false, 0, 0
    );

    setAttributes(context, program, {
      a_position: { size: 2, buffer: positionBuffer }
    });

    setUniforms(context, program, {
      u_resolution: [canvasSize.width, canvasSize.height],
      u_color: [1, 0, 0, 1],
    });

    context.drawArrays(context.LINE_STRIP, 0, positions.length / 2);
  },
};

export default orderFeedDrawer;
